fn normalize_plan_target(target: &str, shape: u8) -> Result<String, String> {
    if shape == SHAPE_VOICE {
        if target.eq_ignore_ascii_case("@discord-voice") {
            Ok("@discord-voice".to_owned())
        } else {
            Err("voice-план должен использовать HOST @discord-voice".to_owned())
        }
    } else {
        normalize(target).map_err(|error| error.to_string())
    }
}

fn shape_matches_plan(shape: u8, plan: &Plan) -> bool {
    match shape {
        SHAPE_HTTP => plan.transport == 6 && plan.proto == PROTO_HTTP,
        SHAPE_MODERN | SHAPE_LEGACY | SHAPE_GRANDFATHER | SHAPE_ECH_TCP => {
            plan.transport == 6 && plan.proto == 1
        }
        SHAPE_QUIC => plan.r2k_is_quic_address_plan(),
        SHAPE_VOICE => plan.transport == 17 && plan.proto == PROTO_VOICE,
        _ => false,
    }
}

fn binding_shape_transport(shape: u8, transport: u8) -> bool {
    match shape {
        SHAPE_HTTP | SHAPE_MODERN | SHAPE_LEGACY | SHAPE_GRANDFATHER | SHAPE_ECH_TCP => {
            transport == 6
        }
        SHAPE_QUIC | SHAPE_VOICE => transport == 17,
        _ => false,
    }
}

#[cfg(unix)]
fn set_name(
    socket_path: PathBuf,
    host: &str,
    family: &str,
    shape: &str,
    plan_path: PathBuf,
) -> Result<(), Box<dyn Error>> {
    let family = match family {
        "ipv4" | "4" => 4,
        "ipv6" | "6" => 6,
        _ => return Err("FAMILY принимает ipv4 или ipv6".into()),
    };
    let shape = match shape {
        "modern" => SHAPE_MODERN,
        "legacy" => SHAPE_LEGACY,
        "ech" => SHAPE_ECH_TCP,
        "http" => SHAPE_HTTP,
        "voice" => SHAPE_VOICE,
        "quic" => SHAPE_QUIC,
        _ => return Err("неизвестная SHAPE".into()),
    };
    let host = normalize_plan_target(host, shape).map_err(|error| format!("HOST: {error}"))?;
    let bytes = std::fs::read(&plan_path)?;
    set_name_bytes(socket_path, &host, family, shape, &bytes)
}

#[cfg(unix)]
fn set_addr(
    socket_path: PathBuf,
    address: &str,
    shape: &str,
    plan_path: PathBuf,
) -> Result<(), Box<dyn Error>> {
    let address = address
        .parse::<std::net::IpAddr>()
        .map_err(|error| format!("IP: {error}"))?;
    let shape = match shape {
        "modern" => SHAPE_MODERN,
        "legacy" => SHAPE_LEGACY,
        "ech" => SHAPE_ECH_TCP,
        "quic" => SHAPE_QUIC,
        "voice" => SHAPE_VOICE,
        _ => return Err("неизвестная SHAPE адресной привязки".into()),
    };
    let bytes = std::fs::read(&plan_path)?;
    let plan = Plan::parse(&bytes)?;
    if !shape_matches_plan(shape, &plan) {
        return Err("SHAPE не соответствует transport/proto плана".into());
    }
    r2o_datapath::engine::validate_runtime_plan(&plan)
        .map_err(|error| format!("план не подходит runtime r2o-datapath: {error}"))?;
    let command =
        encode_set_addr(address, shape, &bytes).map_err(|error| format!("SET_ADDR: {error}"))?;
    let mut client = ControlClient::connect(socket_path)?;
    client.send_command(&command, COMMAND_SET_ADDR)?;
    println!("план установлен для адреса {address} ({shape})");
    Ok(())
}

#[cfg(unix)]
fn delete_addr(socket_path: PathBuf, address: &str, shape: &str) -> Result<(), Box<dyn Error>> {
    let address = address
        .parse::<std::net::IpAddr>()
        .map_err(|error| format!("IP: {error}"))?;
    let shape = match shape {
        "modern" => SHAPE_MODERN,
        "legacy" => SHAPE_LEGACY,
        "ech" => SHAPE_ECH_TCP,
        "quic" => SHAPE_QUIC,
        "voice" => SHAPE_VOICE,
        _ => return Err("неизвестная SHAPE адресной привязки".into()),
    };
    let command =
        encode_delete_addr(address, shape).map_err(|error| format!("DEL_ADDR: {error}"))?;
    let mut client = ControlClient::connect(socket_path)?;
    client.send_command(&command, COMMAND_DEL_ADDR)?;
    println!("план удалён для адреса {address} ({shape})");
    Ok(())
}

#[cfg(unix)]
fn set_name_bytes(
    socket_path: PathBuf,
    host: &str,
    family: u8,
    shape: u8,
    bytes: &[u8],
) -> Result<(), Box<dyn Error>> {
    let host = normalize_plan_target(host, shape).map_err(|error| format!("HOST: {error}"))?;
    let plan = Plan::parse(bytes)?;
    if !shape_matches_plan(shape, &plan) {
        return Err("SHAPE не соответствует transport/proto плана".into());
    }
    r2o_datapath::engine::validate_runtime_plan(&plan)
        .map_err(|error| format!("план не подходит runtime r2o-datapath: {error}"))?;
    let command = encode_set_name(&host, shape, family, bytes)
        .map_err(|error| format!("SET_NAME: {error}"))?;

    let mut client = ControlClient::connect(socket_path)?;
    client.send_set_name(&command)?;
    println!("план установлен: {host} ({shape})");
    Ok(())
}

#[cfg(unix)]
fn apply_catalog(socket_path: PathBuf, catalog_path: PathBuf) -> Result<(), Box<dyn Error>> {
    let catalog = Catalog::load(&catalog_path)?;
    let mut client = ControlClient::connect(socket_path)?;
    let (_catalog, compiled) = catalog_commands_for_runtime(
        &catalog_path,
        &catalog,
        client.send_cap.load(Ordering::Relaxed),
    )?;
    let mut area_sequence = 0;
    let mut installed_areas = Vec::new();
    let mut cursor =
        CatalogSyncCursor::from_compiled(compiled, &mut area_sequence, &installed_areas)?;
    let mut active_groups = HashSet::new();
    loop {
        if !cursor.send_step(&mut client, &mut active_groups, &mut installed_areas)? {
            break;
        }
        let Some(deadline) = cursor
            .pending_area_ack
            .as_ref()
            .map(|pending| pending.deadline)
        else {
            continue;
        };
        let remaining = deadline.saturating_duration_since(std::time::Instant::now());
        if !wait_for_control_frame(&client.socket, remaining)? {
            cursor.expire_area_ack(
                std::time::Instant::now(),
                &mut active_groups,
                &mut installed_areas,
            );
            continue;
        }
        let Some(frame) = read_optional_frame(&mut client.socket)? else {
            return Err("соединение с датапатом закрыто до подтверждения области".into());
        };
        if frame.kind == r2k_core::control::EVENT_ACK {
            let ack = decode_ack(&frame)
                .map_err(|error| format!("подтверждение области датапата: {error}"))?;
            if cursor.observe_area_ack(ack, &mut active_groups, &mut installed_areas) {
                continue;
            }
        }
        client.queue_async_frame(frame)?;
    }
    println!(
        "каталог обработан: отправлено {}, пропущено неподдерживаемых {}",
        cursor.sent, cursor.skipped
    );
    Ok(())
}

#[cfg(unix)]
fn serve_catalog(
    socket_path: PathBuf,
    catalog_path: PathBuf,
    discover: bool,
    mark: Option<u32>,
    live_path: Option<PathBuf>,
) -> Result<(), Box<dyn Error>> {
    use std::io::Write;

    install_r2o_controller_signal_handlers()?;
    let catalog = Catalog::load(&catalog_path)?;
    let mut client = ControlClient::connect(socket_path)?;
    let (catalog, compiled) = catalog_commands_for_runtime(
        &catalog_path,
        &catalog,
        client.send_cap.load(Ordering::Relaxed),
    )?;
    println!(
        "каталог загружен: команд {}, пропущено неподдерживаемых {}; применение идёт порциями; {}",
        compiled.commands.len(),
        compiled.skipped,
        if discover {
            "наблюдение и автопоиск активны"
        } else {
            "наблюдение активно"
        }
    );
    std::io::stdout().flush()?;
    let https_cache_path = catalog_path.with_file_name("https-cache.json");
    let active_groups = HashSet::new();
    let live_catalog = Some((catalog.clone(), catalog_path.clone()));
    client.watch_events(
        discover.then_some((catalog, catalog_path.clone(), mark)),
        Some(https_cache_path),
        mark,
        live_catalog,
        live_path,
        active_groups,
        Some(compiled),
    )
}

#[cfg(unix)]
struct CatalogLock(std::fs::File);

#[cfg(unix)]
const R2O_CATALOG_SAVE_INTERVAL: std::time::Duration = std::time::Duration::from_secs(60);

#[cfg(unix)]
struct R2oCatalogPersistence {
    last_save: std::time::Instant,
    dirty: bool,
    base_catalog: Catalog,
    catalog_snapshot: Arc<std::sync::Mutex<Catalog>>,
}

#[cfg(unix)]
impl R2oCatalogPersistence {
    fn new(started: std::time::Instant, catalog_snapshot: Arc<std::sync::Mutex<Catalog>>) -> Self {
        let base_catalog = catalog_snapshot
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .clone();
        Self {
            last_save: started,
            dirty: false,
            base_catalog,
            catalog_snapshot,
        }
    }

    fn mark_dirty(&mut self) {
        self.dirty = true;
    }

    fn persist_due(
        &mut self,
        catalog: &mut Catalog,
        path: &Path,
        now: std::time::Instant,
        wall_now: i64,
    ) -> Result<bool, Box<dyn Error>> {
        if now.saturating_duration_since(self.last_save) < R2O_CATALOG_SAVE_INTERVAL {
            return Ok(false);
        }
        self.last_save = now;
        if !self.dirty {
            return Ok(false);
        }
        self.persist(catalog, path, wall_now)?;
        Ok(true)
    }

    fn persist_on_shutdown(
        &mut self,
        catalog: &mut Catalog,
        path: &Path,
        wall_now: i64,
    ) -> Result<bool, Box<dyn Error>> {
        if !self.dirty {
            return Ok(false);
        }
        self.persist(catalog, path, wall_now)?;
        Ok(true)
    }

    fn persist(
        &mut self,
        catalog: &mut Catalog,
        path: &Path,
        wall_now: i64,
    ) -> Result<(), Box<dyn Error>> {
        let (_lock, latest) = locked_catalog(path, catalog)?;
        let merged = Catalog::merge_concurrent_changes(&self.base_catalog, catalog, &latest)?;
        merged.save_atomic(path, wall_now)?;
        *catalog = merged;
        self.base_catalog = catalog.clone();
        *self
            .catalog_snapshot
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = catalog.clone();
        self.dirty = false;
        Ok(())
    }
}

#[cfg(unix)]
fn persist_catalog_update(
    catalog: &Catalog,
    path: &Path,
    now: i64,
    persistence: Option<&mut R2oCatalogPersistence>,
) -> Result<(), Box<dyn Error>> {
    if let Some(persistence) = persistence {
        persistence.mark_dirty();
        *persistence
            .catalog_snapshot
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = catalog.clone();
        Ok(())
    } else {
        catalog.save_atomic(path, now)?;
        Ok(())
    }
}

#[cfg(unix)]
fn locked_catalog_for_persistence(
    path: &Path,
    fallback: &Catalog,
    persistence: Option<&R2oCatalogPersistence>,
) -> Result<(CatalogLock, Catalog), Box<dyn Error>> {
    if persistence.is_some_and(|persistence| persistence.dirty) {
        Ok((CatalogLock::acquire(path)?, fallback.clone()))
    } else {
        locked_catalog(path, fallback)
    }
}

#[cfg(unix)]
impl CatalogLock {
    fn acquire(path: &Path) -> Result<Self, Box<dyn Error>> {
        use std::fs::OpenOptions;
        use std::os::fd::AsRawFd;
        use std::os::unix::fs::OpenOptionsExt;

        let mut lock_name = path
            .file_name()
            .ok_or("в пути каталога отсутствует имя файла")?
            .to_os_string();
        lock_name.push(".lock");
        let lock_path = path.with_file_name(lock_name);
        let file = OpenOptions::new()
            .read(true)
            .write(true)
            .create(true)
            .mode(0o600)
            .custom_flags(libc::O_CLOEXEC | libc::O_NOFOLLOW)
            .open(lock_path)?;
        if !file.metadata()?.is_file() {
            return Err("файл блокировки каталога имеет неверный тип".into());
        }
        loop {
            if unsafe { libc::flock(file.as_raw_fd(), libc::LOCK_EX) } == 0 {
                return Ok(Self(file));
            }
            let error = std::io::Error::last_os_error();
            if error.kind() != std::io::ErrorKind::Interrupted {
                return Err(error.into());
            }
        }
    }
}

#[cfg(unix)]
impl Drop for CatalogLock {
    fn drop(&mut self) {
        use std::os::fd::AsRawFd;
        let _ = unsafe { libc::flock(self.0.as_raw_fd(), libc::LOCK_UN) };
    }
}

#[cfg(unix)]
fn locked_catalog(
    path: &Path,
    fallback: &Catalog,
) -> Result<(CatalogLock, Catalog), Box<dyn Error>> {
    let lock = CatalogLock::acquire(path)?;
    let catalog = match std::fs::symlink_metadata(path) {
        Ok(metadata) if metadata.is_file() && !metadata.file_type().is_symlink() => {
            Catalog::load(path)?
        }
        Ok(_) => return Err("путь каталога указывает не на обычный файл".into()),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => fallback.clone(),
        Err(error) => return Err(error.into()),
    };
    Ok((lock, catalog))
}

#[cfg(unix)]
#[cfg(test)]
fn r2o_discovery_record_network_whitelist(
    path: &Path,
    fallback: &Catalog,
    discovered_name: Option<&str>,
    rx_cut: bool,
) -> Result<(), String> {
    let (_lock, mut catalog) = locked_catalog(path, fallback).map_err(|error| error.to_string())?;
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map_err(|error| error.to_string())?
        .as_secs() as i64;
    let network = catalog
        .network_whitelist
        .get_or_insert_with(r2o_controller::catalog::NetworkWhitelist::default);
    r2o_update_network_whitelist(
        network,
        &R2oNetworkWhitelistUpdate {
            name: discovered_name.map(str::to_owned),
            rx_cut,
        },
        now.max(1),
    );
    catalog
        .save_atomic(path, now.max(1))
        .map_err(|error| format!("не удалось сохранить белое имя сети: {error}"))
}

#[cfg(unix)]
fn r2o_apply_network_whitelist_update(
    catalog: &mut Catalog,
    path: &Path,
    update: &R2oNetworkWhitelistUpdate,
    now: i64,
    persistence: Option<&mut R2oCatalogPersistence>,
) -> Result<(), Box<dyn Error>> {
    let (_lock, previous) = locked_catalog_for_persistence(path, catalog, persistence.as_deref())?;
    let mut updated = previous;
    let network = updated
        .network_whitelist
        .get_or_insert_with(r2o_controller::catalog::NetworkWhitelist::default);
    r2o_update_network_whitelist(network, update, now.max(1));
    persist_catalog_update(&updated, path, now.max(1), persistence)?;
    *catalog = updated;
    Ok(())
}

#[cfg(unix)]
fn r2o_update_network_whitelist(
    network: &mut r2o_controller::catalog::NetworkWhitelist,
    update: &R2oNetworkWhitelistUpdate,
    now: i64,
) {
    if let Some(name) = &update.name {
        network.name.clone_from(name);
        network.searched = update.rx_cut;
        network.tx_only = !update.rx_cut;
        network.confirmed_at = Some(now.max(1));
    } else if !network.searched {
        network.name.clear();
        network.searched = true;
        network.confirmed_at = Some(now.max(1));
    }
}

#[cfg(unix)]
fn clear_catalog(path: PathBuf) -> Result<(), Box<dyn Error>> {
    let (_lock, _current) = locked_catalog(&path, &Catalog::default())?;
    let updated = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)?
        .as_secs() as i64;
    Catalog::default().save_atomic(&path, updated)?;
    println!("каталог очищен атомарно: {}", path.display());
    Ok(())
}

#[cfg(unix)]
enum CatalogInstallOp {
    Command(usize),
    CleanupName { host: String, command: Vec<u8> },
}

#[cfg(unix)]
struct CompiledCatalog {
    commands: Vec<(String, Vec<u8>)>,
    install_order: Vec<CatalogInstallOp>,
    group_commands: Vec<(usize, r2o_controller::live::LiveGroupKey)>,
    skipped: usize,
    tcp_stall_budgets: Vec<u16>,
}

#[cfg(unix)]
const R2O_TCP_STALL_FIELD_BUDGET: u16 = 25;
#[cfg(unix)]
const R2O_TCP_STALL_BUDGETS_MAX: usize = 8;
#[cfg(unix)]
const R2O_TCP_STALL_BUDGET_SLACK: u32 = 3;

#[cfg(unix)]
fn r2o_box_tcp_stall_budget(box_record: &r2o_controller::catalog::BoxRecord) -> Option<u16> {
    box_record.fingerprint.signals.iter().find_map(|signal| {
        if !matches!(signal.kind.as_str(), "rx-volume" | "rx-volume-wire")
            || !(1..=i32::from(u16::MAX)).contains(&signal.packets)
        {
            return None;
        }
        u16::try_from(signal.packets).ok()
    })
}

#[cfg(unix)]
fn r2o_tcp_stall_budgets(catalog: &Catalog) -> Vec<u16> {
    let mut budgets = Vec::new();
    for budget in catalog.boxes.iter().filter_map(r2o_box_tcp_stall_budget) {
        if budgets.is_empty() {
            budgets.push(R2O_TCP_STALL_FIELD_BUDGET);
        }
        if budgets.len() >= R2O_TCP_STALL_BUDGETS_MAX {
            break;
        }
        if !budgets.contains(&budget) {
            budgets.push(budget);
        }
    }
    budgets
}

#[cfg(unix)]
fn r2o_tcp_stall_budgets_for_name(catalog: &Catalog, host: &str) -> Vec<u16> {
    let mut budgets = Vec::new();
    for box_record in &catalog.boxes {
        let Some(budget) = r2o_box_tcp_stall_budget(box_record) else {
            continue;
        };
        let bound_to_tcp_name = box_record.bindings.iter().any(|binding| {
            binding.enabled
                && binding.kind == "name"
                && binding.target == host
                && (binding.transport == 0 || binding.transport == 6)
        });
        if bound_to_tcp_name && !budgets.contains(&budget) {
            budgets.push(budget);
            if budgets.len() == R2O_TCP_STALL_BUDGETS_MAX {
                break;
            }
        }
    }
    budgets
}

#[cfg(unix)]
fn r2o_tcp_stall_in_name_band(catalog: &Catalog, host: &str, packets: u32) -> bool {
    let budgets = r2o_tcp_stall_budgets_for_name(catalog, host);
    budgets.is_empty()
        || budgets.iter().any(|budget| {
            packets.saturating_add(R2O_TCP_STALL_BUDGET_SLACK) >= u32::from(*budget)
                && packets <= u32::from(*budget) + R2O_TCP_STALL_BUDGET_SLACK
        })
}

#[cfg(unix)]
const DOMAIN_DIRECT_CLEAR: u8 = 2;
#[cfg(unix)]
const DOMAIN_PLAN_FAILED: u8 = 4;

#[cfg(unix)]
const R2O_D2K_CAT_BUDGET_PASSED: u8 = 1;
#[cfg(unix)]
const R2O_D2K_CAT_BUDGET_CUT: u8 = 3;
#[cfg(unix)]
const R2O_D2K_VERBY_CLIENT: u8 = 2;
#[cfg(unix)]
const R2O_D2K_VERBY_PROBE: u8 = 1;
#[cfg(unix)]
const R2O_D2K_VERBY_STUN: u8 = 3;
#[cfg(unix)]
const R2O_D2K_VERBY_VOICE_DISCOVERY: u8 = 4;

#[cfg(unix)]
fn r2o_catalog_budget_rank(budget: u8) -> u8 {
    // Match core/sched.c::budget_rank: proven pass, unchecked, then cut.
    match budget {
        R2O_D2K_CAT_BUDGET_PASSED => 2,
        R2O_D2K_CAT_BUDGET_CUT => 0,
        _ => 1,
    }
}

#[cfg(unix)]
fn r2o_catalog_binding_beats(left: &Binding, right: &Binding) -> bool {
    let left_budget = r2o_catalog_budget_rank(left.budget);
    let right_budget = r2o_catalog_budget_rank(right.budget);
    left_budget > right_budget || left_budget == right_budget && left.confirmed > right.confirmed
}

#[cfg(unix)]
fn r2o_catalog_binding_is_weak(binding: &Binding) -> bool {
    binding.level > 0 && binding.level < 3
}

#[cfg(unix)]
fn r2o_catalog_binding_transport(binding: &Binding) -> u8 {
    if binding.transport == 0 {
        6
    } else {
        binding.transport
    }
}

#[cfg(unix)]
fn r2o_catalog_binding_family(binding: &Binding) -> u8 {
    if binding.family == 0 {
        4
    } else {
        binding.family
    }
}

#[cfg(unix)]
fn r2o_catalog_addr_binding_shape(binding: &Binding) -> u8 {
    match binding.shape {
        SHAPE_QUIC | SHAPE_VOICE if binding.transport == 17 => binding.shape,
        SHAPE_MODERN | SHAPE_LEGACY | SHAPE_ECH_TCP if matches!(binding.transport, 0 | 6) => {
            binding.shape
        }
        0 if binding.transport == 17 && binding.verified_by == R2O_D2K_VERBY_STUN => SHAPE_VOICE,
        0 if binding.transport == 17 && binding.verified_by == R2O_D2K_VERBY_PROBE => SHAPE_QUIC,
        _ => 0,
    }
}

#[cfg(unix)]
fn r2o_newer_name_binding(catalog: &Catalog, binding: &Binding) -> bool {
    if binding.kind != "name" {
        return false;
    }
    catalog.boxes.iter().any(|box_record| {
        box_record.bindings.iter().any(|other| {
            !std::ptr::eq(other, binding)
                && other.enabled
                && other
                    .recheck_since
                    .is_none_or(|recheck_since| recheck_since == 0)
                && !r2o_catalog_binding_is_weak(other)
                && r2o_catalog_binding_beats(other, binding)
                && other.kind == "name"
                && other.target == binding.target
                && r2o_catalog_binding_transport(other) == r2o_catalog_binding_transport(binding)
                && r2o_catalog_binding_family(other) == r2o_catalog_binding_family(binding)
                && other.shape == binding.shape
                && !(other.transport == 17 && other.verified_by == R2O_D2K_VERBY_CLIENT)
                && box_record
                    .plans
                    .iter()
                    .find(|plan| plan.id == other.plan_id)
                    .is_some_and(|plan| plan.enabled)
        })
    })
}

#[cfg(unix)]
#[cfg(test)]
fn catalog_commands(catalog: &Catalog) -> Result<CompiledCatalog, Box<dyn Error>> {
    let mut catalog = catalog.clone();
    catalog_commands_with_send_cap(&mut catalog, 0, 0)
}

#[cfg(unix)]
fn catalog_commands_for_runtime(
    path: &std::path::Path,
    fallback: &Catalog,
    send_cap: usize,
) -> Result<(Catalog, CompiledCatalog), Box<dyn Error>> {
    let (_lock, mut catalog) = locked_catalog(path, fallback)?;
    let before = catalog.clone();
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)?
        .as_secs() as i64;
    let compiled = catalog_commands_with_send_cap(&mut catalog, send_cap, now)?;
    if catalog != before {
        catalog.save_atomic(path, now.max(1))?;
    }
    Ok((catalog, compiled))
}

#[cfg(unix)]
fn catalog_commands_with_send_cap(
    catalog: &mut Catalog,
    send_cap: usize,
    now: i64,
) -> Result<CompiledCatalog, Box<dyn Error>> {
    let mut commands = Vec::new();
    let mut install_order = Vec::new();
    let mut group_commands = Vec::new();
    let mut skipped = 0_usize;
    let mut selection_catalog = catalog.clone();
    for (box_index, box_record) in catalog.boxes.iter_mut().enumerate() {
        for (binding_index, binding) in box_record.bindings.iter_mut().enumerate() {
            let selection_binding = &selection_catalog.boxes[box_index].bindings[binding_index];
            if !binding.enabled
                || binding
                    .recheck_since
                    .is_some_and(|recheck_since| recheck_since != 0)
            {
                continue;
            }
            if r2o_newer_name_binding(&selection_catalog, selection_binding) {
                continue;
            }
            if r2o_catalog_binding_is_weak(binding)
                || binding.transport == 17 && binding.verified_by == R2O_D2K_VERBY_CLIENT
            {
                skipped += 1;
                continue;
            }
            if binding.kind == "addr" {
                let shape = r2o_catalog_addr_binding_shape(binding);
                let family = r2o_catalog_binding_family(binding);
                if shape == 0 || !matches!(family, 4 | 6) {
                    skipped += 1;
                    continue;
                }
                let Ok(address) = binding.target.parse::<std::net::IpAddr>() else {
                    skipped += 1;
                    continue;
                };
                if address.is_ipv4() != (family == 4) {
                    skipped += 1;
                    continue;
                }
                let Some(saved_plan) = box_record
                    .plans
                    .iter()
                    .find(|plan| plan.id == binding.plan_id && plan.enabled)
                else {
                    skipped += 1;
                    continue;
                };
                let Some((bytes, plan)) =
                    r2o_catalog_compile_plan(&saved_plan.text, &saved_plan.id)
                else {
                    skipped += 1;
                    continue;
                };
                if r2o_catalog_plan_exceeds_send_cap(&plan, send_cap) {
                    r2o_catalog_mark_unfit(
                        binding,
                        &mut selection_catalog.boxes[box_index].bindings[binding_index],
                        &mut box_record.updated,
                        now,
                    );
                    skipped += 1;
                    continue;
                }
                let Ok(command) = r2o_catalog_encode_set_addr(address, shape, &bytes) else {
                    skipped += 1;
                    continue;
                };
                commands.push((binding.target.clone(), command));
                install_order.push(CatalogInstallOp::Command(commands.len() - 1));
                continue;
            }
            if binding.kind != "name" {
                skipped += 1;
                continue;
            }
            let family = match binding.family {
                0 | 4 => 4,
                6 => 6,
                _ => {
                    skipped += 1;
                    continue;
                }
            };
            let shape = if binding.shape == 0 {
                SHAPE_GRANDFATHER
            } else {
                binding.shape
            };
            if !binding_shape_transport(shape, r2o_catalog_binding_transport(binding)) {
                skipped += 1;
                continue;
            }
            let Ok(host) = normalize_plan_target(&binding.target, shape) else {
                skipped += 1;
                continue;
            };
            let Some(saved_plan) = box_record
                .plans
                .iter()
                .find(|plan| plan.id == binding.plan_id && plan.enabled)
            else {
                skipped += 1;
                continue;
            };
            let Some((bytes, plan)) = r2o_catalog_compile_plan(&saved_plan.text, &saved_plan.id)
            else {
                skipped += 1;
                continue;
            };
            if r2o_catalog_plan_exceeds_send_cap(&plan, send_cap) {
                r2o_catalog_mark_unfit(
                    binding,
                    &mut selection_catalog.boxes[box_index].bindings[binding_index],
                    &mut box_record.updated,
                    now,
                );
                if let Ok(delete) = encode_delete_name(
                    &binding.target,
                    r2o_catalog_binding_transport(binding),
                    if binding.shape == 0 {
                        SHAPE_GRANDFATHER
                    } else {
                        binding.shape
                    },
                    r2o_catalog_binding_family(binding),
                ) {
                    install_order.push(CatalogInstallOp::CleanupName {
                        host: binding.target.clone(),
                        command: delete,
                    });
                }
                skipped += 1;
                continue;
            }
            let Ok(command) = encode_set_name(&host, shape, family, &bytes) else {
                skipped += 1;
                continue;
            };
            commands.push((binding.target.clone(), command));
            install_order.push(CatalogInstallOp::Command(commands.len() - 1));
        }
    }
    if let Some(domain_state) = &catalog.domain_state {
        let mut plans_by_wire_key: HashMap<(String, u8, u8, u8), HashSet<String>> = HashMap::new();
        for group in &domain_state.groups {
            plans_by_wire_key
                .entry((
                    group.suffix.clone(),
                    group.key.transport,
                    group.key.family,
                    group.key.shape,
                ))
                .or_default()
                .insert(group.plan_id.clone());
        }

        let mut active_groups = Vec::new();
        let mut seen_suffixes = HashSet::new();
        let mut suffix_commands = Vec::new();
        for group in &domain_state.groups {
            let wire_key = (
                group.suffix.clone(),
                group.key.transport,
                group.key.family,
                group.key.shape,
            );
            if plans_by_wire_key
                .get(&wire_key)
                .is_none_or(|plan_ids| plan_ids.len() != 1)
            {
                skipped += 1;
                continue;
            }
            let Some(saved_plan) = catalog
                .boxes
                .iter()
                .flat_map(|box_record| &box_record.plans)
                .find(|plan| plan.id == group.plan_id && plan.enabled)
            else {
                skipped += 1;
                continue;
            };
            let bytes = compile_text(&saved_plan.text)
                .map_err(|error| format!("план области {}: {error}", group.suffix))?;
            let plan = Plan::parse(&bytes)?;
            if !binding_shape_transport(group.key.shape, group.key.transport)
                || !shape_matches_plan(group.key.shape, &plan)
                || r2o_datapath::engine::validate_runtime_plan(&plan).is_err()
            {
                skipped += 1;
                continue;
            }
            active_groups.push(group);
            if !seen_suffixes.insert(wire_key) {
                continue;
            }
            let command =
                encode_set_suffix(&group.suffix, group.key.shape, group.key.family, &bytes)
                    .map_err(|error| format!("SET_SUFFIX для {}: {error}", group.suffix))?;
            suffix_commands.push((
                format!("суффикс {}", group.suffix),
                command,
                r2o_controller::live::LiveGroupKey::from(group),
            ));
        }

        let mut seen_bypasses = HashSet::new();
        let mut bypass_commands = Vec::new();
        for observation in &domain_state.observations {
            let direct_clear = observation.evidence & DOMAIN_DIRECT_CLEAR != 0;
            let failed_group_plan = observation.evidence & DOMAIN_PLAN_FAILED != 0
                && active_groups.iter().any(|group| {
                    group.key == observation.key
                        && group.plan_id == observation.plan_id
                        && domain_member(&observation.name, &group.suffix)
                })
                && !has_confirmed_exact_binding(catalog, observation);
            if !direct_clear && !failed_group_plan {
                continue;
            }
            let wire_key = (
                observation.name.clone(),
                observation.key.transport,
                observation.key.shape,
                observation.key.family,
            );
            if !seen_bypasses.insert(wire_key) {
                continue;
            }
            let command = encode_set_bypass(
                &observation.name,
                observation.key.transport,
                observation.key.shape,
                observation.key.family,
            )
            .map_err(|error| format!("SET_BYPASS для {}: {error}", observation.name))?;
            bypass_commands.push((format!("исключение {}", observation.name), command));
        }
        for (host, command) in bypass_commands {
            commands.push((host, command));
            install_order.push(CatalogInstallOp::Command(commands.len() - 1));
        }
        for (host, command, key) in suffix_commands {
            group_commands.push((commands.len(), key));
            commands.push((host, command));
            install_order.push(CatalogInstallOp::Command(commands.len() - 1));
        }
    }
    Ok(CompiledCatalog {
        commands,
        install_order,
        group_commands,
        skipped,
        tcp_stall_budgets: r2o_tcp_stall_budgets(catalog),
    })
}

#[cfg(unix)]
fn r2o_catalog_plan_exceeds_send_cap(plan: &Plan, send_cap: usize) -> bool {
    send_cap > 0 && plan.max_emit() > send_cap
}

#[cfg(unix)]
fn r2o_catalog_compile_plan(text: &str, plan_id: &str) -> Option<(Vec<u8>, Plan)> {
    let bytes = match compile_text(text) {
        Ok(bytes) => bytes,
        Err(error) => {
            eprintln!("каталог: план {plan_id} не собирается: {error}");
            return None;
        }
    };
    match Plan::parse(&bytes) {
        Ok(plan) => Some((bytes, plan)),
        Err(error) => {
            eprintln!("каталог: план {plan_id} не разбирается runtime: {error}");
            None
        }
    }
}

#[cfg(unix)]
fn r2o_catalog_encode_set_addr(
    address: std::net::IpAddr,
    shape: u8,
    plan_records: &[u8],
) -> Result<Vec<u8>, &'static str> {
    let mut body = Vec::with_capacity(18 + plan_records.len());
    match address {
        std::net::IpAddr::V4(address) => {
            body.push(4);
            body.extend_from_slice(&address.octets());
            body.extend_from_slice(&[0; 12]);
        }
        std::net::IpAddr::V6(address) => {
            body.push(6);
            body.extend_from_slice(&address.octets());
        }
    }
    body.push(shape);
    body.extend_from_slice(plan_records);
    control::encode_frame(COMMAND_SET_ADDR, &body)
}

#[cfg(unix)]
fn r2o_catalog_mark_unfit(
    binding: &mut Binding,
    selection_binding: &mut Binding,
    box_updated: &mut i64,
    now: i64,
) {
    let marked_at = now.max(1);
    binding.recheck_since = Some(marked_at);
    binding.recheck_mono = Some(std::time::Instant::now());
    selection_binding.recheck_since = Some(marked_at);
    *box_updated = marked_at;
}

#[cfg(unix)]
fn r2o_catalog_mark_flow_unfit(
    catalog: &mut Catalog,
    target: &r2o_controller::discovery::DiscoveryTarget,
    plan_id: &[u8; 16],
    now: i64,
) -> (usize, usize) {
    let present = plan_id.iter().any(|byte| *byte != 0);
    let marked_at = now.max(1);
    let mut marked = 0;
    let mut waiting = 0;
    for box_record in &mut catalog.boxes {
        for binding in &mut box_record.bindings {
            if !binding.enabled
                || binding.kind != "name"
                || binding.target != target.host
                || (if binding.transport == 0 {
                    6
                } else {
                    binding.transport
                }) != 6
                || (if binding.family == 0 {
                    4
                } else {
                    binding.family
                }) != target.family
            {
                continue;
            }
            if present {
                let mut id = [0; 16];
                let bytes = binding.plan_id.as_bytes();
                let length = bytes.len().min(id.len());
                id[..length].copy_from_slice(&bytes[..length]);
                if id != *plan_id {
                    continue;
                }
            }
            if binding.recheck_since.is_some_and(|since| since != 0) {
                waiting += 1;
                continue;
            }
            binding.recheck_since = Some(marked_at);
            binding.recheck_mono = Some(std::time::Instant::now());
            box_record.updated = marked_at;
            marked += 1;
        }
    }
    (marked, waiting)
}

#[cfg(unix)]
fn has_confirmed_exact_binding(catalog: &Catalog, observation: &DomainObservation) -> bool {
    catalog.boxes.iter().any(|box_record| {
        box_record.bindings.iter().any(|binding| {
            binding.enabled
                && binding.level >= 3
                && binding.recheck_since.is_none()
                && binding.kind == "name"
                && normalize(&binding.target).is_ok_and(|name| name == observation.name)
                && (binding.transport == observation.key.transport
                    || binding.transport == 0 && observation.key.transport == 6)
                && (binding.family == observation.key.family
                    || binding.family == 0 && observation.key.family == 4)
                && group_shape_fits(binding.shape, observation.key.shape)
                && group_path(binding.transport, &binding.probe_path)
                    == group_path(observation.key.transport, &observation.key.probe_path)
                && binding.ech_origin == observation.key.ech_origin
        })
    })
}

#[cfg(unix)]
fn group_shape_fits(saved: u8, observed: u8) -> bool {
    saved == 0 || saved == observed || saved == SHAPE_MODERN && observed == SHAPE_ECH_TCP
}

#[cfg(unix)]
fn group_path(transport: u8, path: &str) -> &str {
    if transport == 17 || path.is_empty() {
        "/"
    } else {
        path
    }
}

#[cfg(unix)]
fn r2o_public_resource_ip(address: std::net::IpAddr) -> bool {
    match address {
        std::net::IpAddr::V4(address) => {
            let [first, second, _, _] = address.octets();
            first != 0
                && first != 10
                && first != 127
                && first < 224
                && !(first == 169 && second == 254)
                && !(first == 192 && second == 168)
                && !(first == 172 && (16..=31).contains(&second))
                && !(first == 100 && (64..=127).contains(&second))
        }
        std::net::IpAddr::V6(address) => address.octets()[0] & 0xe0 == 0x20,
    }
}

#[cfg(unix)]
fn r2o_target_confirmed_probe_path(
    catalog: &Catalog,
    target: &r2o_controller::discovery::DiscoveryTarget,
) -> Option<String> {
    let Ok(endpoint) = target.endpoint.parse::<std::net::SocketAddr>() else {
        return None;
    };
    if endpoint.port() != 443
        || target.host.parse::<std::net::IpAddr>().is_ok()
        || !r2o_public_resource_ip(endpoint.ip())
        || !matches!(target.family, 4 | 6)
        || endpoint.is_ipv4() != (target.family == 4)
    {
        return None;
    }
    let (transport, shape) = match target.shape {
        SHAPE_ECH_TCP => (6, SHAPE_MODERN),
        SHAPE_QUIC => (17, SHAPE_QUIC),
        shape => (6, shape),
    };
    catalog
        .boxes
        .iter()
        .flat_map(|box_record| &box_record.bindings)
        .filter(|binding| {
            binding.enabled
                && binding.level >= 3
                && binding.kind == "name"
                && binding.target == target.host
                && binding.transport == transport
                && (if binding.family == 0 {
                    4
                } else {
                    binding.family
                }) == target.family
                && binding.shape == shape
                && r2o_controller::r2o_resource::r2o_resource_path_ok(&binding.probe_path)
        })
        .reduce(|best, binding| {
            if binding.confirmed > best.confirmed {
                binding
            } else {
                best
            }
        })
        .map(|binding| binding.probe_path.clone())
}

#[cfg(unix)]
fn r2o_discovery_resource_probe_paths(
    target: &r2o_controller::discovery::DiscoveryTarget,
    catalog: Option<&Catalog>,
    memory: &std::sync::Mutex<r2o_controller::r2o_resource::R2oResourceMemory>,
) -> (String, Option<String>) {
    let Ok(endpoint) = target.endpoint.parse::<std::net::SocketAddr>() else {
        return ("/".into(), None);
    };
    if endpoint.port() != 443
        || target.host.parse::<std::net::IpAddr>().is_ok()
        || !r2o_public_resource_ip(endpoint.ip())
        || !matches!(target.family, 4 | 6)
        || endpoint.is_ipv4() != (target.family == 4)
    {
        return ("/".into(), None);
    }
    let confirmed = catalog.and_then(|catalog| r2o_target_confirmed_probe_path(catalog, target));
    let (proven, hint) = memory
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .paths_for_host(&target.host, std::time::Instant::now());
    let primary = confirmed
        .or_else(|| proven.clone())
        .or_else(|| hint.clone())
        .unwrap_or_else(|| "/".into());
    let alternate = proven
        .filter(|path| path != &primary)
        .or_else(|| hint.filter(|path| path != &primary));
    (primary, alternate)
}

#[cfg(unix)]
fn r2o_quic_discovery_probe_path(
    snapshot: &[u8],
    server: std::net::SocketAddr,
    catalog: &Catalog,
    resource_memory: &std::sync::Mutex<r2o_controller::r2o_resource::R2oResourceMemory>,
) -> String {
    let host =
        r2o_quic_snapshot_server_name(snapshot, server).unwrap_or_else(|| server.ip().to_string());
    let target = r2o_controller::discovery::DiscoveryTarget {
        host,
        endpoint: server.to_string(),
        family: if server.is_ipv4() { 4 } else { 6 },
        shape: SHAPE_QUIC,
    };
    r2o_discovery_resource_probe_paths(&target, Some(catalog), resource_memory).0
}

#[cfg(unix)]
fn r2o_discovery_volume_wire_len(
    target: &r2o_controller::discovery::DiscoveryTarget,
    client_hello: Option<&[u8]>,
) -> Option<usize> {
    client_hello
        .map(<[u8]>::len)
        .or_else(|| match target.shape {
            SHAPE_MODERN => Trigger::tls13(&target.host)
                .ok()
                .map(|trigger| trigger.payload.len()),
            SHAPE_LEGACY => Trigger::tls(&target.host)
                .ok()
                .map(|trigger| trigger.payload.len()),
            _ => None,
        })
}

#[cfg(unix)]
fn r2o_discovery_volume_fetch_options(
    target: &r2o_controller::discovery::DiscoveryTarget,
    path: &str,
    mark: Option<u32>,
    wire_len: Option<usize>,
) -> Result<r2o_controller::fetch::FetchOptions, String> {
    let endpoint = target
        .endpoint
        .parse::<std::net::SocketAddr>()
        .map_err(|error| format!("адрес объёмной пробы недопустим: {error}"))?;
    let options = r2o_controller::fetch::FetchOptions {
        name: target.host.clone(),
        ip: Some(endpoint.ip()),
        port: endpoint.port(),
        path: path.into(),
        deadline: std::time::Duration::from_secs(8),
        tls12: target.shape == SHAPE_LEGACY,
        wire_len,
        mark,
    };
    options.validate()?;
    Ok(options)
}

#[cfg(unix)]
fn r2o_discovery_measure_volume(
    options: &r2o_controller::fetch::FetchOptions,
    alternate_path: Option<&str>,
) -> (
    Result<r2o_controller::fetch::R2oFetchVolumeTxResult, String>,
    r2o_controller::fetch::R2oFetchVolumeRxResult,
) {
    let tx = r2o_controller::fetch::r2o_fetch_measure_tx_volume(options);
    let rx = if options.port == 80
        || tx
            .as_ref()
            .is_ok_and(|result| result.reason.starts_with("нет TCP к "))
    {
        r2o_controller::fetch::R2oFetchVolumeRxResult::default()
    } else {
        r2o_controller::fetch::r2o_fetch_measure_rx_volume_with_fallback_path_and_timeouts(
            options,
            alternate_path,
            r2o_controller::fetch::R2O_D2O_VERIFY_STEP_TIMEOUT,
            r2o_controller::fetch::R2O_D2O_VOLUME_RX_TIMEOUT,
        )
    };
    (tx, rx)
}

#[cfg(unix)]
fn r2o_discovery_volume_cut(
    tx: &Result<r2o_controller::fetch::R2oFetchVolumeTxResult, String>,
    rx: &r2o_controller::fetch::R2oFetchVolumeRxResult,
) -> bool {
    tx.as_ref()
        .is_ok_and(|result| result.verdict == r2o_controller::fetch::R2oFetchVolumeTxVerdict::Cut)
        || rx.evidence.is_some()
}

#[cfg(unix)]
fn r2o_discovery_cached_volume_cut(
    searches: &std::sync::Mutex<R2oDiscoveryVolumeSearchCache>,
    target: &r2o_controller::discovery::DiscoveryTarget,
    client_hello: Option<&[u8]>,
    candidate_catalog: Option<&Catalog>,
    send_cap: &AtomicUsize,
    resource_memory: &std::sync::Mutex<r2o_controller::r2o_resource::R2oResourceMemory>,
    white_name: &str,
) -> bool {
    let (probe_path, alternate_path) =
        r2o_discovery_resource_probe_paths(target, candidate_catalog, resource_memory);
    let key = R2oDiscoveryVolumeSearchKey {
        wire_len: r2o_discovery_volume_wire_len(target, client_hello),
        send_cap: send_cap.load(Ordering::Relaxed),
        probe_path,
        alternate_path,
        network_probe: r2o_discovery_network_whitelist_probe(candidate_catalog, false),
        white_name: white_name.to_owned(),
    };
    searches
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .has_volume_cut_for_run(
            target,
            &r2o_discovery_task_key(target),
            &key,
            std::time::Instant::now(),
        )
}

#[cfg(unix)]
fn r2o_discovery_network_whitelist_probe(catalog: Option<&Catalog>, rx_cut: bool) -> bool {
    catalog.is_some_and(|catalog| {
        catalog.network_whitelist.as_ref().is_none_or(|network| {
            (!network.searched && network.name.is_empty())
                || (rx_cut && !network.name.is_empty() && network.tx_only)
        })
    })
}

#[cfg(unix)]
fn r2o_discovery_volume_ladder_eligible(
    tx: &Result<r2o_controller::fetch::R2oFetchVolumeTxResult, String>,
    rx: &r2o_controller::fetch::R2oFetchVolumeRxResult,
) -> bool {
    r2o_discovery_volume_cut(tx, rx)
}

#[cfg(unix)]
fn r2o_discovery_volume_ladder_decision(
    result: &Result<r2o_controller::fetch::FetchResult, String>,
    applied: bool,
    packet_budget_required: bool,
) -> R2oFamilyRecoveryDecision {
    if packet_budget_required
        && !result.as_ref().is_ok_and(|fetch| {
            fetch.r2o_volume_observation.packet_budget
                == r2o_controller::r2o_volume::R2oVolumePacketBudget::Passed
        })
    {
        return R2oFamilyRecoveryDecision::Reclassify;
    }
    r2o_family_recovery_decision(result, applied)
}

#[cfg(unix)]
fn r2o_discovery_partial_rx_inconclusive_reason(
    observation: &r2o_controller::r2o_volume::R2oVolumeObservation,
) -> Option<String> {
    if !r2o_controller::r2o_volume::r2o_volume_rx_partial(observation) {
        return None;
    }
    let wire_partial = observation.status == 0 && observation.rx_tls_record_missing;
    let (domain, bytes) = if wire_partial {
        ("TLS wire", observation.rx_tls_wire_bytes)
    } else {
        ("HTTP body", observation.body_bytes)
    };
    Some(format!(
        "RX {domain} оборвался после {bytes} байт; повторный объёмный замер не завершён"
    ))
}

#[cfg(unix)]
fn r2o_discovery_mark_partial_rx_inconclusive(
    outcome: &mut DiscoveryOutcome,
    observation: &r2o_controller::r2o_volume::R2oVolumeObservation,
    volume_proven: bool,
) -> bool {
    if volume_proven {
        return false;
    }
    let Some(reason) = r2o_discovery_partial_rx_inconclusive_reason(observation) else {
        return false;
    };
    outcome.direct_clear = false;
    outcome.retry_after = Some(R2O_DISCOVERY_INCOMPLETE_RETRY);
    outcome.detail.push_str(&format!("; {reason}"));
    true
}

#[cfg(unix)]
fn r2o_discovery_volume_fingerprint(
    tx: &Result<r2o_controller::fetch::R2oFetchVolumeTxResult, String>,
    rx: &r2o_controller::fetch::R2oFetchVolumeRxResult,
) -> r2o_controller::catalog::Fingerprint {
    let mut signals = Vec::with_capacity(2);
    if let Ok(result) = tx
        && result.verdict == r2o_controller::fetch::R2oFetchVolumeTxVerdict::Cut
    {
        signals.push(r2o_controller::catalog::Signal {
            kind: "volume".into(),
            volume: i32::try_from(result.at_kb).unwrap_or(i32::MAX),
            seen: 1,
            ..r2o_controller::catalog::Signal::default()
        });
    }
    if let Some(evidence) = &rx.evidence {
        signals.push(r2o_controller::catalog::Signal {
            kind: match evidence.domain {
                r2o_controller::r2o_volume::R2oVolumeRxDomain::TlsWire => "rx-volume-wire",
                r2o_controller::r2o_volume::R2oVolumeRxDomain::HttpBody => "rx-volume",
            }
            .into(),
            volume: i32::try_from(evidence.cut_kb).unwrap_or(i32::MAX),
            seen: 1,
            packets: i32::try_from(evidence.cut_packets).unwrap_or(i32::MAX),
            ..r2o_controller::catalog::Signal::default()
        });
    }
    r2o_controller::catalog::Fingerprint {
        method: r2o_controller::catalog::FINGERPRINT_METHOD,
        signals,
    }
}

#[cfg(unix)]
fn r2o_discovery_candidate_wire_len(
    target: &r2o_controller::discovery::DiscoveryTarget,
    client_hello: Option<&[u8]>,
    ech_config: Option<&r2o_controller::ech::R2oEchConfig>,
) -> Option<usize> {
    client_hello
        .map(<[u8]>::len)
        .or_else(|| r2o_discovery_volume_wire_len(target, None))
        .or_else(|| {
            if target.shape != SHAPE_ECH_TCP {
                return None;
            }
            let config = ech_config?;
            let ech = r2o_controller::ech::r2o_ech_tls_config(config).ok()?;
            r2o_controller::r2o_tls::r2o_tls_ech_client_hello(&config.origin_name, ech)
                .ok()
                .map(|hello| hello.len())
        })
}

#[cfg(unix)]
fn r2o_discovery_suspect_signal(
    code: u8,
    ttl: u8,
    reference_ttl: u8,
    traffic_class: u8,
    ip_id: u16,
) -> R2oDiscoverySuspectSignal {
    let kind = match code {
        1 | 4 => "rst".to_owned(),
        2 => "repeat".to_owned(),
        3 => "silent".to_owned(),
        other => format!("код-{other}"),
    };
    let is_rst = kind == "rst";
    R2oDiscoverySuspectSignal {
        fingerprint: r2o_controller::catalog::Signal {
            ttl: if is_rst { ttl } else { 0 },
            ttl_delta: if is_rst {
                i32::from(ttl) - i32::from(reference_ttl)
            } else {
                0
            },
            tos: if is_rst { traffic_class } else { 0 },
            ipid: if is_rst { ip_id } else { 0 },
            kind,
            seen: 1,
            ..r2o_controller::catalog::Signal::default()
        },
        trigger_code: code,
    }
}

#[cfg(unix)]
struct R2oDiscoverySuspectSignal {
    fingerprint: r2o_controller::catalog::Signal,
    trigger_code: u8,
}

#[cfg(unix)]
fn r2o_discovery_volume_bucket(volume_kb: i32) -> i32 {
    if volume_kb <= 0 {
        return 0;
    }
    (i32::BITS - volume_kb.leading_zeros()) as i32
}

#[cfg(unix)]
fn r2o_discovery_volume_known_plans(
    catalog: Option<&Catalog>,
    target: &r2o_controller::discovery::DiscoveryTarget,
    observed: &r2o_controller::catalog::Fingerprint,
    tried: &[u32],
) -> Vec<(String, String)> {
    let Some(catalog) = catalog else {
        return Vec::new();
    };
    if !matches!(target.shape, SHAPE_MODERN | SHAPE_LEGACY) {
        return Vec::new();
    }
    let observed_buckets: Vec<(&str, i32)> = observed
        .signals
        .iter()
        .filter(|signal| {
            matches!(
                signal.kind.as_str(),
                "volume" | "rx-volume" | "rx-volume-wire"
            )
        })
        .map(|signal| {
            (
                signal.kind.as_str(),
                r2o_discovery_volume_bucket(signal.volume),
            )
        })
        .collect();
    let mut candidates = Vec::new();
    for box_record in &catalog.boxes {
        if !box_record.fingerprint.is_compatible_with(observed) {
            continue;
        }
        let same_bucket = box_record.fingerprint.signals.iter().any(|saved| {
            observed_buckets.iter().any(|(kind, bucket)| {
                *kind == saved.kind
                    && *bucket > 0
                    && *bucket == r2o_discovery_volume_bucket(saved.volume)
            })
        });
        for plan in &box_record.plans {
            if !plan.enabled || plan.proto != "tls" || plan.text.len() >= 4096 {
                continue;
            }
            if tried.contains(&r2o_controller::r2o_fallback::tried_key(&plan.text)) {
                continue;
            }
            let Ok(bytes) = compile_text(&plan.text) else {
                continue;
            };
            let Ok(runtime_plan) = Plan::parse(&bytes) else {
                continue;
            };
            if runtime_plan.transport != 6
                || runtime_plan.proto != 1
                || r2o_datapath::engine::validate_runtime_plan(&runtime_plan).is_err()
            {
                continue;
            }
            candidates.push((
                same_bucket,
                plan.successes,
                plan.text.clone(),
                box_record.id.clone(),
            ));
        }
    }
    candidates.sort_by(|left, right| right.0.cmp(&left.0).then_with(|| right.1.cmp(&left.1)));
    let mut plans: Vec<(String, String)> = Vec::new();
    for (_, _, text, box_id) in candidates {
        if !plans.iter().any(|(_, known_text)| known_text == &text) {
            plans.push((box_id, text));
        }
    }
    plans
}

#[cfg(unix)]
fn r2o_discovery_existing_binding_blocks_outcome(
    catalog: &Catalog,
    target: &r2o_controller::discovery::DiscoveryTarget,
    input: u8,
    volume_recovery: bool,
) -> bool {
    r2o_controller::discovery::has_usable_binding(catalog, target)
        && !(input == 1 && r2o_controller::discovery::has_usable_profile_binding(catalog, target))
        && !volume_recovery
}

#[cfg(unix)]
fn domain_member(name: &str, suffix: &str) -> bool {
    name == suffix
        || name
            .strip_suffix(suffix)
            .is_some_and(|prefix| prefix.ends_with('.'))
}

#[cfg(unix)]
fn matching_domain_group<'a>(
    catalog: &'a Catalog,
    target: &r2o_controller::discovery::DiscoveryTarget,
) -> Option<&'a r2o_controller::catalog::DomainGroup> {
    if target.shape == SHAPE_QUIC {
        return None;
    }
    let selected_path = r2o_target_confirmed_probe_path(catalog, target).unwrap_or_default();
    let key = GroupKey {
        transport: 6,
        family: target.family,
        shape: if target.shape == SHAPE_ECH_TCP {
            SHAPE_MODERN
        } else {
            target.shape
        },
        probe_path: if selected_path == "/" {
            String::new()
        } else {
            selected_path
        },
        ..GroupKey::default()
    };
    let domain_state = catalog.domain_state.as_ref()?;
    let group = domain_state.match_domain(&target.host, &key)?;
    let probe_path = group_path(group.key.transport, &group.key.probe_path);
    if probe_path != "/" && !r2o_controller::r2o_resource::r2o_resource_path_ok(probe_path) {
        return None;
    }
    let groups = &domain_state.groups;
    if groups.iter().any(|other| {
        other.suffix == group.suffix
            && other.key.transport == group.key.transport
            && other.key.family == group.key.family
            && other.key.shape == group.key.shape
            && other.plan_id != group.plan_id
    }) {
        return None;
    }
    let saved_plan = catalog
        .boxes
        .iter()
        .flat_map(|box_record| &box_record.plans)
        .find(|plan| plan.id == group.plan_id && plan.enabled)?;
    let bytes = compile_text(&saved_plan.text).ok()?;
    let plan = Plan::parse(&bytes).ok()?;
    if !shape_matches_plan(group.key.shape, &plan)
        || r2o_datapath::engine::validate_runtime_plan(&plan).is_err()
    {
        return None;
    }
    Some(group)
}

#[cfg(unix)]
fn r2o_installed_family_group(
    catalog: &Catalog,
    target: &r2o_controller::discovery::DiscoveryTarget,
    active_groups: &HashSet<r2o_controller::live::LiveGroupKey>,
) -> Option<r2o_controller::live::LiveGroupKey> {
    if target.host.parse::<std::net::IpAddr>().is_ok() || target.shape == 0 {
        return None;
    }
    let state = catalog.domain_state.as_ref()?;
    let transport = r2o_discovery_transport(target);
    let group = state.groups.iter().find(|group| {
        let key = &group.key;
        key.transport == transport
            && key.family == target.family
            && key.shape == target.shape
            && state
                .match_domain(&target.host, key)
                .is_some_and(|matched| std::ptr::eq(matched, *group))
            && active_groups.contains(&r2o_controller::live::LiveGroupKey::from(*group))
    })?;
    if catalog
        .boxes
        .iter()
        .flat_map(|box_record| &box_record.bindings)
        .any(|binding| {
            binding.enabled
                && binding.level >= 3
                && binding.kind == "name"
                && binding.target == target.host
                && (if binding.transport == 0 {
                    6
                } else {
                    binding.transport
                }) == transport
                && (if binding.family == 0 {
                    4
                } else {
                    binding.family
                }) == target.family
                && (binding.shape == 0 || binding.shape == target.shape)
        })
    {
        return None;
    }
    Some(r2o_controller::live::LiveGroupKey::from(group))
}

#[cfg(unix)]
fn matching_domain_recovery_candidates(
    catalog: &Catalog,
    target: &r2o_controller::discovery::DiscoveryTarget,
) -> Vec<R2oFamilyRecoveryCandidate> {
    const MAX_CANDIDATES: usize = 8;

    let Some(group) = matching_domain_group(catalog, target) else {
        return Vec::new();
    };
    let Some(state) = catalog.domain_state.as_ref() else {
        return Vec::new();
    };
    let mut candidates = Vec::new();
    for group_pass in [true, false] {
        for observation in &state.observations {
            if observation.evidence & 1 == 0
                || observation.evidence & (2 | 4) != 0
                || observation.key != group.key
                || !domain_member(&observation.name, &group.suffix)
                || (observation.plan_id == group.plan_id) != group_pass
            {
                continue;
            }
            for box_record in &catalog.boxes {
                let Some(saved_plan) = box_record
                    .plans
                    .iter()
                    .find(|plan| plan.id == observation.plan_id && plan.enabled)
                else {
                    continue;
                };
                if saved_plan.proto != "tls" || saved_plan.text.len() >= 4096 {
                    continue;
                }
                let confirmed = box_record.bindings.iter().any(|binding| {
                    binding.enabled
                        && binding.level >= 3
                        && binding.recheck_since.is_none()
                        && binding.kind == "name"
                        && normalize(&binding.target).is_ok_and(|name| name == observation.name)
                        && binding.plan_id == observation.plan_id
                        && (binding.transport == observation.key.transport
                            || binding.transport == 0 && observation.key.transport == 6)
                        && (binding.family == observation.key.family
                            || binding.family == 0 && observation.key.family == 4)
                        && group_shape_fits(binding.shape, observation.key.shape)
                        && group_path(binding.transport, &binding.probe_path)
                            == group_path(observation.key.transport, &observation.key.probe_path)
                        && binding.ech_origin == observation.key.ech_origin
                });
                if !confirmed {
                    continue;
                }
                let Ok(bytes) = compile_text(&saved_plan.text) else {
                    continue;
                };
                let Ok(plan) = Plan::parse(&bytes) else {
                    continue;
                };
                if !shape_matches_plan(target.shape, &plan)
                    || r2o_datapath::engine::validate_runtime_plan(&plan).is_err()
                    || candidates
                        .iter()
                        .any(|candidate: &R2oFamilyRecoveryCandidate| {
                            candidate.plan_text == saved_plan.text
                        })
                {
                    continue;
                }
                candidates.push(R2oFamilyRecoveryCandidate {
                    plan_id: plan.id,
                    plan_text: saved_plan.text.clone(),
                    group_plan: group_pass,
                    probe_path: group_path(group.key.transport, &group.key.probe_path).into(),
                });
                break;
            }
            if candidates.len() == MAX_CANDIDATES {
                return candidates;
            }
        }
    }
    candidates
}

#[cfg(unix)]
const CATALOG_SYNC_CHUNK: usize = 8;

#[cfg(unix)]
struct PendingCatalogSyncCommand {
    host: String,
    command: Vec<u8>,
    group: Option<r2o_controller::live::LiveGroupKey>,
    area_action: Option<CatalogAreaAction>,
    expected_ack: Option<u16>,
    expected_area_id: Option<[u8; 16]>,
    counts_toward_chunk: bool,
}

#[cfg(unix)]
#[derive(Clone, Copy, Debug, Hash, PartialEq, Eq)]
enum CatalogAreaKind {
    Suffix,
    Bypass,
}

#[cfg(unix)]
#[derive(Clone, Debug, Hash, PartialEq, Eq)]
struct CatalogAreaKey {
    kind: CatalogAreaKind,
    name: String,
    transport: u8,
    shape: u8,
    family: u8,
}

#[cfg(unix)]
#[derive(Clone, Debug)]
struct InstalledCatalogArea {
    key: CatalogAreaKey,
    plan_id: Option<String>,
    group: Option<r2o_controller::live::LiveGroupKey>,
    confirmed: bool,
}

#[cfg(unix)]
#[derive(Clone, Debug)]
enum CatalogAreaAction {
    Set(InstalledCatalogArea),
    Delete(CatalogAreaKey),
}

#[cfg(unix)]
impl CatalogAreaAction {
    fn key(&self) -> &CatalogAreaKey {
        match self {
            Self::Set(area) => &area.key,
            Self::Delete(key) => key,
        }
    }
}

#[cfg(unix)]
struct CatalogSyncCursor {
    pending: VecDeque<PendingCatalogSyncCommand>,
    pending_area_ack: Option<PendingCatalogAreaAck>,
    sent: usize,
    skipped: usize,
    areas_failed: bool,
}

#[cfg(unix)]
struct PendingCatalogAreaAck {
    host: String,
    expected: u16,
    area_id: [u8; 16],
    action: CatalogAreaAction,
    deadline: std::time::Instant,
}

#[cfg(unix)]
fn catalog_area_action(
    command: &[u8],
    group: Option<r2o_controller::live::LiveGroupKey>,
) -> Result<Option<CatalogAreaAction>, Box<dyn Error>> {
    let Some(kind) = command
        .get(4..6)
        .map(|bytes| u16::from_be_bytes([bytes[0], bytes[1]]))
    else {
        return Ok(None);
    };
    if !matches!(
        kind,
        control::COMMAND_SET_SUFFIX | control::COMMAND_SET_BYPASS
    ) {
        return Ok(None);
    }
    let body = command.get(6..).ok_or("кадр области каталога обрезан")?;
    let Some(name_len) = body.first().copied().map(usize::from) else {
        return Ok(None);
    };
    let name_end = 1_usize
        .checked_add(name_len)
        .filter(|end| *end <= body.len())
        .ok_or("имя области каталога обрезано")?;
    let name = std::str::from_utf8(&body[1..name_end])?.to_owned();
    let (key, plan_id, group) = match kind {
        control::COMMAND_SET_SUFFIX => {
            let context = body
                .get(name_end..name_end + 2)
                .ok_or("контекст суффикса каталога обрезан")?;
            let plan = Plan::parse(
                body.get(name_end + 2..)
                    .ok_or("план суффикса каталога обрезан")?,
            )?;
            let transport = group
                .as_ref()
                .map(|group| group.transport)
                .unwrap_or(plan.transport);
            (
                CatalogAreaKey {
                    kind: CatalogAreaKind::Suffix,
                    name,
                    transport,
                    shape: context[0],
                    family: context[1],
                },
                group.as_ref().map(|group| group.plan_id.clone()),
                group,
            )
        }
        control::COMMAND_SET_BYPASS => {
            let context = body
                .get(name_end..name_end + 3)
                .ok_or("контекст исключения каталога обрезан")?;
            (
                CatalogAreaKey {
                    kind: CatalogAreaKind::Bypass,
                    name,
                    transport: context[0],
                    shape: context[1],
                    family: context[2],
                },
                None,
                None,
            )
        }
        _ => return Ok(None),
    };
    Ok(Some(CatalogAreaAction::Set(InstalledCatalogArea {
        key,
        plan_id,
        group,
        confirmed: true,
    })))
}

#[cfg(unix)]
fn catalog_area_delete_command(key: &CatalogAreaKey) -> Result<Vec<u8>, Box<dyn Error>> {
    Ok(match key.kind {
        CatalogAreaKind::Suffix => {
            control::encode_delete_suffix(&key.name, key.transport, key.shape, key.family)?
        }
        CatalogAreaKind::Bypass => {
            control::encode_delete_bypass(&key.name, key.transport, key.shape, key.family)?
        }
    })
}

#[cfg(unix)]
fn catalog_area_remove_group(
    area: &InstalledCatalogArea,
    active_groups: &mut HashSet<r2o_controller::live::LiveGroupKey>,
) {
    if let Some(group) = &area.group {
        active_groups.remove(group);
    }
}

#[cfg(unix)]
fn catalog_area_store(
    areas: &mut Vec<InstalledCatalogArea>,
    area: InstalledCatalogArea,
) -> Option<InstalledCatalogArea> {
    if let Some(index) = areas.iter().position(|installed| installed.key == area.key) {
        Some(std::mem::replace(&mut areas[index], area))
    } else {
        areas.push(area);
        None
    }
}

#[cfg(unix)]
fn catalog_area_queue_stale_deletes(
    pending: &mut VecDeque<PendingCatalogSyncCommand>,
    installed_areas: &[InstalledCatalogArea],
    desired_areas: &HashSet<CatalogAreaKey>,
    area_sequence: &mut u64,
) -> Result<(), Box<dyn Error>> {
    let mut remaining = installed_areas
        .iter()
        .map(|installed| installed.key.clone())
        .collect::<Vec<_>>();
    let mut index = 0;
    while index < remaining.len() {
        if desired_areas.contains(&remaining[index]) {
            index += 1;
            continue;
        }
        let key = remaining.swap_remove(index);
        *area_sequence = area_sequence.wrapping_add(1);
        let mut area_id = [0; 16];
        area_id[..8].copy_from_slice(&area_sequence.to_ne_bytes());
        let command = control_frame_with_area_id(&catalog_area_delete_command(&key)?, area_id)?;
        pending.push_back(PendingCatalogSyncCommand {
            host: key.name.clone(),
            command,
            group: None,
            area_action: Some(CatalogAreaAction::Delete(key.clone())),
            expected_ack: Some(match key.kind {
                CatalogAreaKind::Suffix => control::COMMAND_DEL_SUFFIX,
                CatalogAreaKind::Bypass => control::COMMAND_DEL_BYPASS,
            }),
            expected_area_id: Some(area_id),
            counts_toward_chunk: false,
        });
    }
    Ok(())
}

#[cfg(unix)]
fn control_frame_with_area_id(
    command: &[u8],
    area_id: [u8; 16],
) -> Result<Vec<u8>, Box<dyn Error>> {
    let length = command.get(..4).ok_or("кадр команды каталога обрезан")?;
    let length = u32::from_be_bytes(length.try_into().expect("four-byte frame length")) as usize;
    if command.len() != length + 4 {
        return Err("длина команды каталога не совпадает с кадром".into());
    }
    let new_length = length
        .checked_add(area_id.len())
        .filter(|length| *length <= control::FRAME_MAX)
        .ok_or("команда области каталога с area ID слишком длинная")?;
    let mut identified = Vec::with_capacity(command.len() + area_id.len());
    identified.extend_from_slice(&(new_length as u32).to_be_bytes());
    identified.extend_from_slice(&command[4..]);
    identified.extend_from_slice(&area_id);
    Ok(identified)
}

#[cfg(unix)]
impl CatalogSyncCursor {
    fn from_compiled(
        compiled: CompiledCatalog,
        area_sequence: &mut u64,
        installed_areas: &[InstalledCatalogArea],
    ) -> Result<Self, Box<dyn Error>> {
        let groups = compiled
            .group_commands
            .into_iter()
            .collect::<HashMap<_, _>>();
        let mut desired_areas = HashSet::new();
        for (index, (_, command)) in compiled.commands.iter().enumerate() {
            if let Some(action) = catalog_area_action(command, groups.get(&index).cloned())? {
                desired_areas.insert(action.key().clone());
            }
        }
        let mut pending = VecDeque::new();
        let mut stale_deletes_queued = false;
        for operation in compiled.install_order {
            match operation {
                CatalogInstallOp::Command(index) => {
                    let (host, command) = compiled
                        .commands
                        .get(index)
                        .ok_or("индекс команды каталога вне собранного списка")?;
                    let kind = command
                        .get(4..6)
                        .map(|bytes| u16::from_be_bytes([bytes[0], bytes[1]]));
                    let area_command = kind.is_some_and(|kind| {
                        matches!(
                            kind,
                            control::COMMAND_SET_SUFFIX
                                | control::COMMAND_DEL_SUFFIX
                                | control::COMMAND_SET_BYPASS
                                | control::COMMAND_DEL_BYPASS
                        )
                    });
                    let area_action = catalog_area_action(command, groups.get(&index).cloned())?;
                    if area_command && !stale_deletes_queued {
                        catalog_area_queue_stale_deletes(
                            &mut pending,
                            installed_areas,
                            &desired_areas,
                            area_sequence,
                        )?;
                        stale_deletes_queued = true;
                    }
                    if let Some(CatalogAreaAction::Set(desired)) = &area_action
                        && installed_areas.iter().any(|installed| {
                            installed.key == desired.key
                                && installed.confirmed
                                && installed.plan_id == desired.plan_id
                        })
                    {
                        continue;
                    }
                    let (command, expected_area_id) = if area_command {
                        *area_sequence = area_sequence.wrapping_add(1);
                        let mut area_id = [0; 16];
                        area_id[..8].copy_from_slice(&area_sequence.to_ne_bytes());
                        (control_frame_with_area_id(command, area_id)?, Some(area_id))
                    } else {
                        (command.clone(), None)
                    };
                    pending.push_back(PendingCatalogSyncCommand {
                        host: host.clone(),
                        command,
                        group: groups.get(&index).cloned(),
                        area_action,
                        expected_ack: area_command.then_some(kind.expect("area command kind")),
                        expected_area_id,
                        counts_toward_chunk: matches!(
                            kind,
                            Some(COMMAND_SET_NAME | COMMAND_SET_ADDR)
                        ),
                    });
                }
                CatalogInstallOp::CleanupName { host, command } => {
                    pending.push_back(PendingCatalogSyncCommand {
                        host,
                        command,
                        group: None,
                        area_action: None,
                        expected_ack: None,
                        expected_area_id: None,
                        counts_toward_chunk: false,
                    });
                }
            }
        }
        if !stale_deletes_queued {
            catalog_area_queue_stale_deletes(
                &mut pending,
                installed_areas,
                &desired_areas,
                area_sequence,
            )?;
        }
        if !compiled.tcp_stall_budgets.is_empty() {
            pending.push_back(PendingCatalogSyncCommand {
                host: "бюджеты потока TCP".into(),
                command: encode_set_tcp_stall_budgets(&compiled.tcp_stall_budgets)
                    .map_err(|error| format!("SET_TCP_STALL_BUDGETS: {error}"))?,
                group: None,
                area_action: None,
                expected_ack: None,
                expected_area_id: None,
                counts_toward_chunk: false,
            });
        }
        Ok(Self {
            pending,
            pending_area_ack: None,
            sent: 0,
            skipped: compiled.skipped,
            areas_failed: false,
        })
    }

    fn send_step(
        &mut self,
        client: &mut ControlClient,
        active_groups: &mut HashSet<r2o_controller::live::LiveGroupKey>,
        _installed_areas: &mut Vec<InstalledCatalogArea>,
    ) -> Result<bool, Box<dyn Error>> {
        if self.pending_area_ack.is_some() {
            return Ok(true);
        }
        let mut sent_now = 0;
        while sent_now < CATALOG_SYNC_CHUNK {
            let Some(operation) = self.pending.pop_front() else {
                break;
            };
            if let Some(expected) = operation.expected_ack {
                if self.areas_failed {
                    self.skipped += 1;
                    continue;
                }
                let area_id = operation
                    .expected_area_id
                    .ok_or("команда области каталога не имеет area ID")?;
                if let Err(error) = client.write_command(&operation.command) {
                    eprintln!(
                        "каталог: команда для {} не подтверждена: {error}",
                        operation.host
                    );
                    self.skipped += 1;
                    self.areas_failed = true;
                    continue;
                }
                self.pending_area_ack = Some(PendingCatalogAreaAck {
                    host: operation.host,
                    expected,
                    area_id,
                    action: operation
                        .area_action
                        .ok_or("команда области каталога не имеет действия")?,
                    deadline: std::time::Instant::now() + std::time::Duration::from_secs(5),
                });
                return Ok(true);
            }
            if let Err(error) = client.write_command(&operation.command) {
                eprintln!(
                    "каталог: команда для {} не отправилась: {error}",
                    operation.host
                );
                self.skipped += 1;
                continue;
            }
            self.sent += 1;
            if operation.counts_toward_chunk {
                sent_now += 1;
            }
            if let Some(group) = operation.group {
                active_groups.insert(group);
            }
        }
        Ok(!self.pending.is_empty() || self.pending_area_ack.is_some())
    }

    fn observe_area_ack(
        &mut self,
        ack: r2k_core::control::Ack,
        active_groups: &mut HashSet<r2o_controller::live::LiveGroupKey>,
        installed_areas: &mut Vec<InstalledCatalogArea>,
    ) -> bool {
        let Some(pending) = self.pending_area_ack.as_ref() else {
            return false;
        };
        if ack.command != pending.expected || ack.area_id != Some(pending.area_id) {
            return false;
        }
        let pending = self
            .pending_area_ack
            .take()
            .expect("checked pending area ACK");
        if ack.ok {
            self.sent += 1;
            match pending.action {
                CatalogAreaAction::Set(mut area) => {
                    area.confirmed = true;
                    if let Some(previous) = catalog_area_store(installed_areas, area.clone()) {
                        catalog_area_remove_group(&previous, active_groups);
                    }
                    if let Some(group) = area.group {
                        active_groups.insert(group);
                    }
                }
                CatalogAreaAction::Delete(key) => {
                    if let Some(index) = installed_areas
                        .iter()
                        .position(|installed| installed.key == key)
                    {
                        let removed = installed_areas.swap_remove(index);
                        catalog_area_remove_group(&removed, active_groups);
                    }
                }
            }
        } else {
            eprintln!(
                "каталог: команда для {} отвергнута датапатом (код {})",
                pending.host, ack.reason
            );
            self.skipped += 1;
            self.areas_failed = true;
        }
        true
    }

    fn expire_area_ack(
        &mut self,
        now: std::time::Instant,
        active_groups: &mut HashSet<r2o_controller::live::LiveGroupKey>,
        installed_areas: &mut Vec<InstalledCatalogArea>,
    ) {
        if self
            .pending_area_ack
            .as_ref()
            .is_some_and(|pending| now >= pending.deadline)
        {
            let pending = self
                .pending_area_ack
                .take()
                .expect("checked pending area ACK");
            match pending.action {
                CatalogAreaAction::Set(mut area) => {
                    area.confirmed = false;
                    if let Some(previous) = catalog_area_store(installed_areas, area) {
                        catalog_area_remove_group(&previous, active_groups);
                    }
                }
                CatalogAreaAction::Delete(key) => {
                    if let Some(area) = installed_areas.iter_mut().find(|area| area.key == key) {
                        area.confirmed = false;
                        catalog_area_remove_group(area, active_groups);
                    }
                }
            }
            eprintln!(
                "каталог: команда для {} не подтверждена: истёк срок ожидания ACK",
                pending.host
            );
            self.skipped += 1;
            self.areas_failed = true;
        }
    }
}

#[cfg(unix)]
impl ControlClient {
    fn write_command(&mut self, command: &[u8]) -> Result<(), Box<dyn Error>> {
        use std::io::Write;
        self.socket.write_all(command)?;
        Ok(())
    }

    fn wait_for_sent_command_ack(
        &mut self,
        command: &[u8],
        expected: u16,
        timeout: std::time::Duration,
    ) -> Result<Option<r2k_core::control::Ack>, Box<dyn Error>> {
        let expected_trial_id = control_command_trial_id(command, expected);
        let deadline = std::time::Instant::now() + timeout;
        loop {
            let remaining = deadline.saturating_duration_since(std::time::Instant::now());
            if remaining.is_zero() || !wait_for_control_frame(&self.socket, remaining)? {
                return Ok(None);
            }
            let frame = read_optional_frame(&mut self.socket)?
                .ok_or("соединение с датапатом закрыто до подтверждения команды")?;
            if frame.kind == control::EVENT_ACK {
                let ack = decode_ack(&frame)
                    .map_err(|error| format!("подтверждение датапата: {error}"))?;
                if ack.command != expected
                    || expected_trial_id.is_some_and(|trial_id| ack.trial_id != Some(trial_id))
                {
                    self.queue_async_frame(frame)?;
                    continue;
                }
                return Ok(Some(ack));
            }
            self.queue_async_frame(frame)?;
        }
    }
}

#[cfg(unix)]
fn ack_reason_text(reason: u8) -> &'static str {
    match reason {
        control::ACK_BAD_PLAN => "план не подходит runtime",
        control::ACK_NO_ROOM => "таблица планов заполнена",
        control::ACK_BAD_ARGS => "датапат отверг аргументы",
        _ => "неизвестная причина",
    }
}

#[cfg(unix)]
fn saved_http_candidate_keys(
    catalog: &Catalog,
    target: &r2o_controller::discovery::DiscoveryTarget,
) -> Vec<String> {
    let mut saved = Vec::new();
    for box_record in &catalog.boxes {
        for binding in &box_record.bindings {
            let same_name = binding.target.eq_ignore_ascii_case(&target.host);
            let same_context = same_name
                && binding.family == target.family
                && binding.shape == SHAPE_HTTP
                && binding.transport == 6;
            if binding.kind != "name"
                || binding.shape != SHAPE_HTTP
                || binding.transport != 6
                || (!binding.enabled && !(same_context && binding.recheck_since.is_some()))
            {
                continue;
            }
            let Some(plan) = box_record.plans.iter().find(|plan| {
                plan.enabled
                    && plan.proto == "http"
                    && plan.id.eq_ignore_ascii_case(&binding.plan_id)
            }) else {
                continue;
            };
            let Some(key) = candidate_key_from_plan_text(&plan.text) else {
                continue;
            };
            saved.push((same_context, binding.confirmed, key));
        }
    }
    saved.sort_by(|a, b| b.0.cmp(&a.0).then_with(|| b.1.cmp(&a.1)));
    let mut keys = Vec::new();
    for (_, _, key) in saved {
        if !keys.contains(&key) {
            keys.push(key);
        }
    }
    keys
}

#[cfg(unix)]
#[derive(Clone, Debug, Default)]
struct HttpLiveFailures {
    programs: Vec<Vec<u8>>,
    evidence_lost: bool,
}

#[cfg(unix)]
#[derive(Default)]
struct HttpSearchRecordCache(HashMap<(String, u8), HttpSearchRecord>);

#[cfg(unix)]
#[derive(Default)]
struct HttpSearchRecord {
    cut: bool,
    repeat_path: Vec<u8>,
    repro_gap: bool,
}

#[cfg(unix)]
impl HttpSearchRecordCache {
    fn key(target: &r2o_controller::discovery::DiscoveryTarget) -> (String, u8) {
        (target.host.to_ascii_lowercase(), target.family)
    }

    fn record(&mut self, target: &r2o_controller::discovery::DiscoveryTarget) {
        self.0.entry(Self::key(target)).or_default();
    }

    fn record_name(&mut self, host: &str, family: u8) {
        self.0
            .entry((host.to_ascii_lowercase(), family))
            .or_default();
    }

    fn count(&self) -> usize {
        self.0.len()
    }

    fn record_cut(&mut self, target: &r2o_controller::discovery::DiscoveryTarget, path: &[u8]) {
        let record = self.0.entry(Self::key(target)).or_default();
        record.repro_gap = false;
        if !record.cut || record.repeat_path.is_empty() {
            record.cut = true;
            record.repeat_path = path.to_vec();
        }
    }

    fn record_repeat_path(
        &mut self,
        target: &r2o_controller::discovery::DiscoveryTarget,
        path: &[u8],
    ) {
        let record = self.0.entry(Self::key(target)).or_default();
        record.repro_gap = !r2o_controller::http_search::repeatable_path(path);
        record.repeat_path = if record.repro_gap {
            Vec::new()
        } else {
            path.to_vec()
        };
    }

    fn context(
        &self,
        target: &r2o_controller::discovery::DiscoveryTarget,
        event_path: &[u8],
        event_baseline: r2o_controller::http_search::Answer,
    ) -> Option<(Vec<u8>, r2o_controller::http_search::Answer)> {
        let Some(record) = self.0.get(&Self::key(target)) else {
            return Some((event_path.to_vec(), event_baseline));
        };
        if record.repro_gap {
            return None;
        }
        Some((
            if record.repeat_path.is_empty() {
                event_path.to_vec()
            } else {
                record.repeat_path.clone()
            },
            if record.cut {
                r2o_controller::http_search::Answer::Cut
            } else {
                event_baseline
            },
        ))
    }
}

#[cfg(unix)]
fn measured_http_candidate_keys(catalog: &Catalog) -> Vec<String> {
    const MAX_MEASURED_CANDIDATES: usize = 8;

    let mut measured = Vec::new();
    for box_record in &catalog.boxes {
        for plan in &box_record.plans {
            if plan.proto != "tls" || !plan.enabled || plan.successes <= 0 {
                continue;
            }
            for key in measured_poison_keys(&plan.text) {
                measured.push((plan.successes, key));
            }
        }
    }
    measured.sort_by_key(|entry| std::cmp::Reverse(entry.0));

    let mut keys = Vec::new();
    for (_, key) in measured {
        if !keys.contains(&key) {
            keys.push(key);
            if keys.len() == MAX_MEASURED_CANDIDATES {
                break;
            }
        }
    }
    keys
}

#[cfg(unix)]
fn failed_http_programs(
    catalog: &Catalog,
    target: &r2o_controller::discovery::DiscoveryTarget,
) -> HttpLiveFailures {
    let mut failures = HttpLiveFailures::default();
    for box_record in &catalog.boxes {
        for binding in &box_record.bindings {
            if binding.kind != "name"
                || !binding.target.eq_ignore_ascii_case(&target.host)
                || binding.enabled
                || binding.recheck_since.is_none()
                || binding.transport != 6
                || binding.family != target.family
                || binding.shape != SHAPE_HTTP
                || binding.verified_by != 1
                || binding.input != 2
            {
                continue;
            }
            let Some(plan) = box_record
                .plans
                .iter()
                .find(|plan| plan.id.eq_ignore_ascii_case(&binding.plan_id))
            else {
                failures.evidence_lost = true;
                continue;
            };
            let Some(key) = candidate_key_from_plan_text(&plan.text) else {
                failures.evidence_lost = true;
                continue;
            };
            let Some(program) = candidate_program(&key) else {
                failures.evidence_lost = true;
                continue;
            };
            if !failures.programs.contains(&program) {
                failures.programs.push(program);
            }
        }
    }
    failures
}

#[cfg(unix)]
fn http_search_candidates(
    catalog: &Catalog,
    target: &r2o_controller::discovery::DiscoveryTarget,
) -> Vec<String> {
    let measured = measured_http_candidate_keys(catalog);
    let mut candidates = saved_http_candidate_keys(catalog, target);
    for key in candidate_keys() {
        if !measured.is_empty() && *key == "fake-seqshift" {
            continue;
        }
        if !candidates.iter().any(|saved| saved == key) {
            candidates.push((*key).to_owned());
        }
    }
    for key in measured {
        if !candidates.contains(&key) {
            candidates.push(key);
        }
    }
    candidates
}

#[cfg(unix)]
fn catalog_has_http_search_owner(
    catalog: &Catalog,
    target: &r2o_controller::discovery::DiscoveryTarget,
    plan_id: [u8; 16],
) -> bool {
    let plan_id: String = plan_id.iter().map(|byte| format!("{byte:02x}")).collect();
    catalog.boxes.iter().any(|box_record| {
        box_record.plans.iter().any(|plan| {
            plan.enabled
                && plan.proto.eq_ignore_ascii_case("http")
                && plan.id.eq_ignore_ascii_case(&plan_id)
        }) && box_record.bindings.iter().any(|binding| {
            binding.enabled
                && binding.recheck_since.is_none()
                && binding.kind == "name"
                && binding.target == target.host
                && binding.plan_id.eq_ignore_ascii_case(&plan_id)
                && binding.level >= 3
                && binding.transport == 6
                && binding.family == target.family
                && binding.shape == SHAPE_HTTP
                && binding.verified_by == 1
                && binding.input == 2
        })
    })
}

#[cfg(unix)]
struct HttpSearchTask {
    target: r2o_controller::discovery::DiscoveryTarget,
    request_path: Vec<u8>,
    expected_baseline: r2o_controller::http_search::Answer,
    candidates: Vec<String>,
    live_failures: HttpLiveFailures,
    mark: Option<u32>,
    owned_binding: Option<HttpSearchOwnedBinding>,
}

#[cfg(unix)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum HttpSearchOwnedBinding {
    Confirmed {
        plan_id: [u8; 16],
        binding: r2k_core::control::BindingContext,
    },
    Pending {
        plan_id: [u8; 16],
        previous: Option<([u8; 16], r2k_core::control::BindingContext)>,
    },
}

#[cfg(unix)]
struct PendingHttpSearchAfterHttps {
    target: r2o_controller::discovery::DiscoveryTarget,
    request_path: Vec<u8>,
    expected_baseline: r2o_controller::http_search::Answer,
    live_bound_cut: bool,
}

#[cfg(unix)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum HttpSearchHttpsAction {
    Queue,
    Wait,
    Suppress,
}

#[cfg(unix)]
fn r2o_http_search_https_action(
    response_code: u8,
    live_bound_failure: bool,
    state: Option<HttpsProbeState>,
    probe_pending: bool,
) -> HttpSearchHttpsAction {
    if response_code != 3 || live_bound_failure {
        return HttpSearchHttpsAction::Queue;
    }
    if let Some(state) = state {
        return if state.should_redirect() {
            HttpSearchHttpsAction::Suppress
        } else {
            HttpSearchHttpsAction::Queue
        };
    }
    if probe_pending {
        HttpSearchHttpsAction::Wait
    } else {
        HttpSearchHttpsAction::Suppress
    }
}

