#[cfg(unix)]
struct R2oFamilyRecoveryWorker {
    jobs: Option<SyncSender<R2oFamilyRecoveryTask>>,
    outcomes: Receiver<R2oFamilyRecoveryOutcome>,
    cancel: Arc<AtomicBool>,
    active: HashSet<r2o_controller::discovery::DiscoveryTarget>,
    thread: Option<JoinHandle<()>>,
}

#[cfg(unix)]
impl R2oFamilyRecoveryWorker {
    fn new(
        measurement_gate: r2o_controller::r2o_resource_limit::R2oMeasurementGate,
        trial_commands: SyncSender<HttpSearchCommand>,
    ) -> Self {
        let (jobs, job_receiver) = mpsc::sync_channel::<R2oFamilyRecoveryTask>(8);
        let (outcome_sender, outcomes) = mpsc::sync_channel(8);
        let cancel = Arc::new(AtomicBool::new(false));
        let worker_cancel = Arc::clone(&cancel);
        let worker_gate = measurement_gate.clone();
        let worker_commands = trial_commands;
        let thread = std::thread::spawn(move || {
            while let Ok(task) = job_receiver.recv() {
                if worker_cancel.load(Ordering::Relaxed) {
                    break;
                }
                let outcome = {
                    let tcp_target = r2o_discovery_transport(&task.target) == 6;
                    let Some(_permit) =
                        worker_gate.r2o_acquire_family_recovery(&worker_cancel, tcp_target)
                    else {
                        break;
                    };
                    r2o_family_recovery_run(task, &worker_commands, &worker_cancel)
                };
                if outcome_sender.send(outcome).is_err() {
                    break;
                }
            }
        });
        Self {
            jobs: Some(jobs),
            outcomes,
            cancel,
            active: HashSet::new(),
            thread: Some(thread),
        }
    }

    fn queue(
        &mut self,
        target: r2o_controller::discovery::DiscoveryTarget,
        candidates: Vec<R2oFamilyRecoveryCandidate>,
        mark: Option<u32>,
    ) -> bool {
        if candidates.is_empty() || !self.active.insert(target.clone()) {
            return false;
        }
        let Some(jobs) = self.jobs.as_ref() else {
            self.active.remove(&target);
            return false;
        };
        if jobs
            .try_send(R2oFamilyRecoveryTask {
                target: target.clone(),
                candidates,
                mark,
            })
            .is_err()
        {
            self.active.remove(&target);
            return false;
        }
        true
    }

    fn try_outcome(&self) -> Option<R2oFamilyRecoveryOutcome> {
        self.outcomes.try_recv().ok()
    }

    fn complete(&mut self, target: &r2o_controller::discovery::DiscoveryTarget) {
        self.active.remove(target);
    }

    fn r2o_begin_shutdown(&mut self) {
        self.cancel.store(true, Ordering::Relaxed);
        self.jobs.take();
    }

    fn r2o_all_finished(&self) -> bool {
        self.thread
            .as_ref()
            .is_none_or(std::thread::JoinHandle::is_finished)
    }

    fn r2o_join(&mut self) {
        if let Some(thread) = self.thread.take() {
            let _ = thread.join();
        }
    }
}

#[cfg(unix)]
impl Drop for R2oFamilyRecoveryWorker {
    fn drop(&mut self) {
        self.r2o_begin_shutdown();
        self.r2o_join();
    }
}

#[cfg(unix)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum R2oFamilyRecoveryDecision {
    Verified,
    Reclassify,
}

#[cfg(unix)]
fn r2o_family_recovery_decision(
    result: &Result<r2o_controller::fetch::FetchResult, String>,
    applied: bool,
) -> R2oFamilyRecoveryDecision {
    let response_complete = result.as_ref().is_ok_and(|fetch| {
        fetch.handshake_verified
            || (fetch.tls.is_some()
                && fetch
                    .ech_accepted
                    .is_none_or(|accepted| accepted && fetch.peer_name_ok == Some(true))
                && fetch.complete
                && fetch.application_verified
                && (200..600).contains(&fetch.status)
                && !fetch.cloudflare_challenge
                && !matches!(
                    fetch.http_outcome,
                    r2o_controller::fetch::R2oFetchHttpOutcome::Blocked
                        | r2o_controller::fetch::R2oFetchHttpOutcome::LegalDenial
                ))
    });
    if response_complete && applied {
        R2oFamilyRecoveryDecision::Verified
    } else {
        R2oFamilyRecoveryDecision::Reclassify
    }
}

#[cfg(unix)]
fn r2o_confirm_discovery_outcome(
    mut outcome: DiscoveryOutcome,
    result: Result<r2o_controller::fetch::FetchResult, String>,
    applied: bool,
) -> DiscoveryOutcome {
    if outcome.plan_text.is_none()
        || r2o_family_recovery_decision(&result, applied) == R2oFamilyRecoveryDecision::Verified
    {
        return outcome;
    }
    outcome.plan_text = None;
    outcome.retry_after = Some(R2O_DISCOVERY_FAILURE_RETRY);
    if result
        .as_ref()
        .is_ok_and(|fetch| fetch.cloudflare_challenge)
    {
        outcome.detail.push_str(
            "; сервер вернул Cloudflare challenge: это не подтверждает обход и кандидат не сохранён",
        );
    } else {
        outcome.detail.push_str(
            "; кандидат не сохранён: временная проба не получила полный HTTPS-ответ и точное APPLIED",
        );
    }
    outcome
}

#[cfg(unix)]
fn r2o_family_recovery_fetch(
    target: &r2o_controller::discovery::DiscoveryTarget,
    mark: Option<u32>,
    probe_path: &str,
) -> Result<r2o_controller::fetch::FetchResult, String> {
    let endpoint = target
        .endpoint
        .parse::<std::net::SocketAddr>()
        .map_err(|error| format!("адрес семейной пробы недопустим: {error}"))?;
    r2o_controller::fetch::r2o_fetch_with_phase_timeout(
        &r2o_controller::fetch::FetchOptions {
            name: target.host.clone(),
            ip: Some(endpoint.ip()),
            port: endpoint.port(),
            path: probe_path.into(),
            deadline: std::time::Duration::from_secs(8),
            tls12: target.shape == SHAPE_LEGACY,
            wire_len: None,
            mark: r2o_candidate_confirmation_mark(mark),
        },
        r2o_controller::fetch::R2O_D2O_VERIFY_STEP_TIMEOUT,
    )
    .map_err(|error| format!("проверка известного семейного плана не завершилась: {error}"))
}

#[cfg(unix)]
fn r2o_family_recovery_run(
    task: R2oFamilyRecoveryTask,
    commands: &SyncSender<HttpSearchCommand>,
    cancel: &AtomicBool,
) -> R2oFamilyRecoveryOutcome {
    let mut outcome = R2oFamilyRecoveryOutcome {
        target: task.target.clone(),
        plan_id: task.candidates[0].plan_id,
        result: Err("не найден подходящий план семейного восстановления".to_owned()),
        applied: false,
    };
    let destination = match task.target.endpoint.parse::<std::net::SocketAddr>() {
        Ok(destination) => destination,
        Err(error) => {
            outcome.result = Err(format!("адрес семейной пробы недопустим: {error}"));
            return outcome;
        }
    };

    for candidate in task.candidates {
        if cancel.load(Ordering::Relaxed) {
            outcome.result = Err("проверка семейного плана отменена".to_owned());
            return outcome;
        }
        outcome.plan_id = candidate.plan_id;
        let trial = if candidate.group_plan {
            let result = r2o_family_recovery_fetch(&task.target, task.mark, &candidate.probe_path);
            let applied = r2o_collect_controller_applied_events_until(
                commands,
                [0; 16],
                std::time::Duration::from_secs(5),
                |event| {
                    result.as_ref().is_ok_and(|fetch| {
                        r2o_family_applied_flow_matches(
                            event,
                            &task.target,
                            fetch.local_port,
                            candidate.plan_id,
                            [0; 16],
                        )
                    })
                },
            )
            .map(|events| {
                events.iter().any(|event| {
                    r2o_family_applied_flow_matches(
                        event,
                        &task.target,
                        result.as_ref().map_or(0, |fetch| fetch.local_port),
                        candidate.plan_id,
                        [0; 16],
                    )
                })
            });
            match applied {
                Ok(applied) => (result, applied),
                Err(error) => (Err(error), false),
            }
        } else {
            r2o_family_recovery_sibling_trial(
                &task.target,
                destination,
                &candidate,
                task.mark,
                commands,
            )
        };
        outcome.result = trial.0;
        outcome.applied = trial.1;
        if r2o_family_recovery_decision(&outcome.result, outcome.applied)
            == R2oFamilyRecoveryDecision::Verified
        {
            return outcome;
        }
    }
    outcome
}

#[cfg(unix)]
fn r2o_family_recovery_sibling_trial(
    target: &r2o_controller::discovery::DiscoveryTarget,
    destination: std::net::SocketAddr,
    candidate: &R2oFamilyRecoveryCandidate,
    mark: Option<u32>,
    commands: &SyncSender<HttpSearchCommand>,
) -> (Result<r2o_controller::fetch::FetchResult, String>, bool) {
    r2o_family_recovery_sibling_trial_with_ech(target, destination, candidate, mark, commands, None)
}

#[cfg(unix)]
fn r2o_family_recovery_sibling_trial_with_ech(
    target: &r2o_controller::discovery::DiscoveryTarget,
    destination: std::net::SocketAddr,
    candidate: &R2oFamilyRecoveryCandidate,
    mark: Option<u32>,
    commands: &SyncSender<HttpSearchCommand>,
    ech: Option<&r2o_controller::ech::R2oEchConfig>,
) -> (Result<r2o_controller::fetch::FetchResult, String>, bool) {
    let wire_len = r2o_discovery_candidate_wire_len(target, None, ech);
    let (result, applied, _) = r2o_family_recovery_sibling_trial_with_ech_state(
        target,
        destination,
        candidate,
        mark,
        commands,
        ech,
        None,
        false,
        wire_len,
        None,
        r2o_controller::fetch::r2o_d2o_verification_encoding(&candidate.probe_path),
    );
    (result, applied)
}

#[cfg(unix)]
fn r2o_family_recovery_sibling_trial_with_ech_state(
    target: &r2o_controller::discovery::DiscoveryTarget,
    destination: std::net::SocketAddr,
    candidate: &R2oFamilyRecoveryCandidate,
    mark: Option<u32>,
    commands: &SyncSender<HttpSearchCommand>,
    ech: Option<&r2o_controller::ech::R2oEchConfig>,
    client_hello: Option<&[u8]>,
    allow_non_http_alpn: bool,
    wire_len: Option<usize>,
    packet_budget: Option<u32>,
    request_encoding: r2o_controller::fetch::R2oFetchEncoding,
) -> (
    Result<r2o_controller::fetch::FetchResult, String>,
    bool,
    bool,
) {
    let result = (|| {
        let confirmation_mark = r2o_candidate_confirmation_mark(mark);
        let bound = BoundTcpProbe::open(target.family, confirmation_mark)
            .map_err(|error| format!("не удалось открыть сокет семейной пробы: {error}"))?;
        let local_port = bound.local_port;
        let trial_id = random_id().map_err(|error| error.to_string())?;
        let records = compile_text(&candidate.plan_text).map_err(|error| error.to_string())?;
        let command = encode_set_name_probe(
            &target.host,
            target.shape,
            target.family,
            local_port,
            &records,
            trial_id,
        )
        .map_err(|error| error.to_string())?;
        let ack = ask_http_controller(commands, |reply| HttpSearchCommand::InstallProbe {
            host: target.host.clone(),
            shape: target.shape,
            family: target.family,
            port: local_port,
            command,
            trial_id,
            candidate_settle: true,
            reply,
        })?;
        if ack
            .as_ref()
            .is_some_and(|ack| ack.trial_id != Some(trial_id))
        {
            return Err("подтверждение семейной пробы содержит чужой trial ID".into());
        }
        if ack.as_ref().is_some_and(|ack| !ack.ok) {
            ask_http_controller(commands, |reply| HttpSearchCommand::DeleteProbe {
                host: target.host.clone(),
                shape: target.shape,
                family: target.family,
                port: local_port,
                reply,
            })?;
            return Err("датапат отверг временный план семейной пробы".into());
        }

        let connected = bound
            .connect(
                destination,
                r2o_controller::fetch::R2O_D2O_VERIFY_STEP_TIMEOUT,
            )
            .map_err(|error| format!("не удалось подключить семейную пробу: {error}"));
        let mut transport_established = false;
        let mut socket_hold = None;
        let captured_non_http_alpn = allow_non_http_alpn
            .then(|| {
                client_hello.and_then(r2o_controller::r2o_tls::r2o_tls_client_hello_non_http_alpn)
            })
            .flatten();
        let ech_snapshot_replay = (target.shape == SHAPE_ECH_TCP && ech.is_none())
            .then_some(client_hello)
            .flatten();
        let fetch_result = match connected {
            Ok((stream, _, connected_port, _)) if connected_port == local_port => {
                transport_established = true;
                match stream.try_clone() {
                    Err(error) => Err(format!("не удалось удержать сокет до APPLIED: {error}")),
                    Ok(held) => {
                        socket_hold = Some(held);
                        let options = r2o_controller::fetch::FetchOptions {
                            name: ech
                                .map(|config| config.origin_name.clone())
                                .unwrap_or_else(|| target.host.clone()),
                            ip: Some(destination.ip()),
                            port: destination.port(),
                            path: candidate.probe_path.clone(),
                            deadline: std::time::Duration::from_secs(8),
                            tls12: target.shape == SHAPE_LEGACY,
                            wire_len,
                            mark: confirmation_mark,
                        };
                        if let Some(client_hello) = ech_snapshot_replay {
                            r2o_controller::fetch::r2o_verify_tls_replayed_client_hello(
                                &options,
                                stream,
                                client_hello,
                                r2o_controller::fetch::R2O_D2O_VERIFY_STEP_TIMEOUT,
                            )
                        } else if let Some(alpn) = captured_non_http_alpn.as_deref() {
                            r2o_controller::fetch::r2o_verify_tls_connected_stream_with_alpn(
                                &options,
                                stream,
                                alpn,
                                r2o_controller::fetch::R2O_D2O_VERIFY_STEP_TIMEOUT,
                            )
                        } else if let Some(ech) = ech {
                            let config = r2o_controller::ech::r2o_ech_tls_config(ech)?;
                            r2o_controller::fetch::r2o_fetch_ech_connected_stream_with_phase_timeout(
                                &options,
                                stream,
                                &config,
                                r2o_controller::fetch::R2O_D2O_VERIFY_STEP_TIMEOUT,
                            )
                        } else if packet_budget.is_some() {
                            r2o_controller::fetch::r2o_fetch_connected_stream_with_packet_budget_phase_timeout_and_encoding(
                                &options,
                                stream,
                                packet_budget,
                                Some(r2o_controller::fetch::R2O_D2O_VERIFY_STEP_TIMEOUT),
                                request_encoding,
                            )
                        } else {
                            r2o_controller::fetch::r2o_fetch_connected_stream_with_packet_budget_phase_timeout_and_encoding(
                                &options,
                                stream,
                                None,
                                Some(r2o_controller::fetch::R2O_D2O_VERIFY_STEP_TIMEOUT),
                                request_encoding,
                            )
                        }
                    }
                }
            }
            Ok((_stream, _, _, _)) => Err("TCP-зонд получил неожиданный локальный порт".into()),
            Err(error) => Err(error),
        };
        let events = r2o_collect_controller_applied_events_until(
            commands,
            trial_id,
            if transport_established {
                std::time::Duration::from_secs(5)
            } else {
                std::time::Duration::ZERO
            },
            |event| {
                r2o_family_applied_flow_matches(
                    event,
                    target,
                    local_port,
                    candidate.plan_id,
                    trial_id,
                )
            },
        );
        let delete_result = ask_http_controller(commands, |reply| HttpSearchCommand::DeleteProbe {
            host: target.host.clone(),
            shape: target.shape,
            family: target.family,
            port: local_port,
            reply,
        });
        drop(socket_hold);
        let events = events?;
        delete_result?;
        let applied = events.iter().any(|event| {
            r2o_family_applied_flow_matches(event, target, local_port, candidate.plan_id, trial_id)
        });
        Ok((fetch_result, applied, transport_established))
    })();
    match result {
        Ok((fetch, applied, transport_established)) => (fetch, applied, transport_established),
        Err(error) => (Err(error), false, false),
    }
}

#[cfg(unix)]
fn r2o_run_discovery_candidate_trial(
    target: &r2o_controller::discovery::DiscoveryTarget,
    source_text: &str,
    probe_path: &str,
    mark: Option<u32>,
    commands: &SyncSender<HttpSearchCommand>,
    client_hello: Option<&[u8]>,
    ech_config: Option<&r2o_controller::ech::R2oEchConfig>,
    resource_memory: &std::sync::Mutex<r2o_controller::r2o_resource::R2oResourceMemory>,
    packet_budget: Option<u32>,
) -> (
    Result<r2o_controller::fetch::FetchResult, String>,
    bool,
    usize,
) {
    r2o_run_discovery_candidate_trial_with_encoding(
        target,
        source_text,
        probe_path,
        mark,
        commands,
        client_hello,
        ech_config,
        resource_memory,
        packet_budget,
        r2o_controller::fetch::R2oFetchEncoding::Identity,
    )
}

#[cfg(unix)]
fn r2o_run_discovery_candidate_trial_with_encoding(
    target: &r2o_controller::discovery::DiscoveryTarget,
    source_text: &str,
    probe_path: &str,
    mark: Option<u32>,
    commands: &SyncSender<HttpSearchCommand>,
    client_hello: Option<&[u8]>,
    ech_config: Option<&r2o_controller::ech::R2oEchConfig>,
    resource_memory: &std::sync::Mutex<r2o_controller::r2o_resource::R2oResourceMemory>,
    packet_budget: Option<u32>,
    request_encoding: r2o_controller::fetch::R2oFetchEncoding,
) -> (
    Result<r2o_controller::fetch::FetchResult, String>,
    bool,
    usize,
) {
    let (result, applied, attempts) = r2o_run_discovery_candidate_trial_with_retries(
        target,
        source_text,
        probe_path,
        mark,
        commands,
        client_hello,
        ech_config,
        resource_memory,
        1 + usize::from(client_hello.is_some()),
        packet_budget,
        request_encoding,
        || false,
    );
    (result, applied, attempts)
}

#[cfg(unix)]
fn r2o_run_discovery_candidate_trial_with_retries(
    target: &r2o_controller::discovery::DiscoveryTarget,
    source_text: &str,
    probe_path: &str,
    mark: Option<u32>,
    commands: &SyncSender<HttpSearchCommand>,
    client_hello: Option<&[u8]>,
    ech_config: Option<&r2o_controller::ech::R2oEchConfig>,
    resource_memory: &std::sync::Mutex<r2o_controller::r2o_resource::R2oResourceMemory>,
    probe_budget_remaining: usize,
    packet_budget: Option<u32>,
    request_encoding: r2o_controller::fetch::R2oFetchEncoding,
    retry_budget_available: impl FnMut() -> bool,
) -> (
    Result<r2o_controller::fetch::FetchResult, String>,
    bool,
    usize,
) {
    let (result, applied, attempts, _) = r2o_run_discovery_candidate_trial_with_progress(
        target,
        source_text,
        probe_path,
        mark,
        commands,
        client_hello,
        false,
        ech_config,
        resource_memory,
        probe_budget_remaining,
        packet_budget,
        request_encoding,
        false,
        retry_budget_available,
        true,
        None,
        &mut |_, _, _, _| {},
    );
    (result, applied, attempts)
}

#[cfg(unix)]
#[derive(Clone, Copy, Default)]
struct R2oCandidateTrialEvidence {
    transport_established: bool,
    local_limit: bool,
    dropped_before: u32,
    dropped_after: u32,
    layered_rx_handled: bool,
    layered_rx_proven: bool,
}

#[cfg(unix)]
fn r2o_run_discovery_candidate_trial_with_progress(
    target: &r2o_controller::discovery::DiscoveryTarget,
    source_text: &str,
    probe_path: &str,
    mark: Option<u32>,
    commands: &SyncSender<HttpSearchCommand>,
    client_hello: Option<&[u8]>,
    allow_non_http_alpn: bool,
    ech_config: Option<&r2o_controller::ech::R2oEchConfig>,
    resource_memory: &std::sync::Mutex<r2o_controller::r2o_resource::R2oResourceMemory>,
    probe_budget_remaining: usize,
    packet_budget: Option<u32>,
    request_encoding: r2o_controller::fetch::R2oFetchEncoding,
    layered_rx: bool,
    retry_budget_available: impl FnMut() -> bool,
    measured_arm: bool,
    dropped_events: Option<&AtomicUsize>,
    progress: &mut dyn FnMut(usize, usize, &str, &str),
) -> (
    Result<r2o_controller::fetch::FetchResult, String>,
    bool,
    usize,
    R2oCandidateTrialEvidence,
) {
    if probe_budget_remaining == 0 {
        return (
            Err("бюджет зондов Discovery исчерпан до проверки кандидата".into()),
            false,
            0,
            Default::default(),
        );
    }
    let ech_snapshot_is_trial_proof =
        target.shape == SHAPE_ECH_TCP && ech_config.is_none() && client_hello.is_some();
    let proof_probe_reserve = usize::from(client_hello.is_some() && !ech_snapshot_is_trial_proof);
    let Some(max_retries) = r2o_discovery_candidate_retry_count(
        probe_budget_remaining.saturating_sub(proof_probe_reserve),
    ) else {
        return (
            Err(
                "бюджета зондов Discovery недостаточно для проверки и подтверждения кандидата"
                    .into(),
            ),
            false,
            0,
            Default::default(),
        );
    };
    let arm_retry_limit = if measured_arm { max_retries } else { 0 };
    let max_retries = (arm_retry_limit + 1).min(
        probe_budget_remaining
            .saturating_sub(proof_probe_reserve + 1)
            .min(u8::MAX as usize) as u8,
    );
    let plan_id = match random_id() {
        Ok(id) => id,
        Err(error) => return (Err(error.to_string()), false, 0, Default::default()),
    };
    let plan_text = match r2o_controller::discovery::plan_text_for_trial(source_text, plan_id) {
        Ok(text) => text,
        Err(error) => return (Err(error), false, 0, Default::default()),
    };
    let destination = match target.endpoint.parse::<std::net::SocketAddr>() {
        Ok(destination) => destination,
        Err(error) => {
            return (
                Err(format!("адрес Discovery-пробы недопустим: {error}")),
                false,
                0,
                Default::default(),
            );
        }
    };
    let candidate = R2oFamilyRecoveryCandidate {
        plan_id,
        plan_text,
        group_plan: false,
        probe_path: probe_path.into(),
    };
    if target.shape == SHAPE_ECH_TCP && ech_config.is_none() && client_hello.is_none() {
        return (
            Err("кандидат ECH нельзя подтвердить без совместимой TLS-конфигурации".into()),
            false,
            0,
            Default::default(),
        );
    }
    let mut attempts = 0;
    let mut bare_retries = 0;
    let mut arm_retries = 0;
    let retry_budget_available = std::cell::RefCell::new(retry_budget_available);
    let (result, applied, _, evidence) = r2o_repeat_candidate_trials(
        max_retries,
        || {
            let sequence_budget = probe_budget_remaining.saturating_sub(attempts);
            let (sequence, layered_rx_handled, _, layered_rx_evidence) =
                r2o_discovery_layered_rx_candidate_trials(
                    layered_rx,
                    request_encoding,
                    sequence_budget,
                    || retry_budget_available.borrow_mut()(),
                    || std::thread::sleep(r2o_controller::fetch::R2O_VOLUME_RX_PROBE_GAP),
                    |encoding| {
                        attempts += 1;
                        let dropped_before = dropped_events
                            .map_or(0, |counter| counter.load(Ordering::Relaxed) as u32);
                        let trial_ech_config = r2o_discovery_refresh_ech_probe_config(
                            target,
                            ech_config,
                            mark,
                            |origin, mark| r2o_controller::ech::resolve_ech_config(origin, mark),
                        );
                        let trial = match trial_ech_config {
                            Ok(trial_ech_config) => {
                                let wire_len = r2o_discovery_candidate_wire_len(
                                    target,
                                    client_hello,
                                    trial_ech_config.as_ref(),
                                );
                                r2o_family_recovery_sibling_trial_with_ech_state(
                                    target,
                                    destination,
                                    &candidate,
                                    mark,
                                    commands,
                                    trial_ech_config.as_ref(),
                                    client_hello,
                                    allow_non_http_alpn,
                                    wire_len,
                                    packet_budget,
                                    encoding,
                                )
                            }
                            Err(error) => (Err(error), false, false),
                        };
                        if let Ok(fetch) = &trial.0
                            && r2o_controller::fetch::r2o_fetch_result_can_remember_resources(fetch)
                        {
                            resource_memory
                                .lock()
                                .unwrap_or_else(std::sync::PoisonError::into_inner)
                                .remember_hints(&fetch.r2o_resources, std::time::Instant::now());
                        }
                        let dropped_after = dropped_events
                            .map_or(0, |counter| counter.load(Ordering::Relaxed) as u32);
                        (trial, dropped_before, dropped_after)
                    },
                    |(trial, _, _)| r2o_discovery_layered_rx_observation(&trial.0, trial.1),
                );
            let (trial, dropped_before, dropped_after) = sequence;
            let verified = !layered_rx_handled
                && r2o_family_recovery_decision(&trial.0, trial.1)
                    == R2oFamilyRecoveryDecision::Verified;
            let (application, result) = r2o_discovery_plan_result(&trial.0, trial.1, verified);
            progress(
                attempts,
                (usize::from(max_retries) + 1).max(attempts),
                &application,
                &result,
            );
            let evidence = R2oCandidateTrialEvidence {
                transport_established: trial.2,
                local_limit: trial
                    .0
                    .as_ref()
                    .is_ok_and(|fetch| fetch.r2o_volume_observation.local_limit),
                dropped_before,
                dropped_after,
                layered_rx_handled,
                layered_rx_proven: layered_rx_evidence.is_some(),
            };
            (trial.0, trial.1, trial.2, evidence)
        },
        |(result, applied, transport_established, evidence)| {
            if evidence.layered_rx_handled
                || !retry_budget_available.borrow_mut()()
                || r2o_family_recovery_decision(result, *applied)
                    == R2oFamilyRecoveryDecision::Verified
            {
                return false;
            }
            let transport_only =
                *transport_established && result.as_ref().map_or(true, |fetch| fetch.tls.is_none());
            if !applied && transport_only && bare_retries < 1 {
                bare_retries += 1;
                return true;
            }
            if arm_retries < arm_retry_limit
                && evidence.dropped_before == evidence.dropped_after
                && r2o_discovery_candidate_retryable(result, *applied, *transport_established)
            {
                arm_retries += 1;
                return true;
            }
            false
        },
    );
    if !evidence.layered_rx_handled
        && !result.as_ref().is_ok_and(|fetch| fetch.handshake_verified)
        && r2o_family_recovery_decision(&result, applied) == R2oFamilyRecoveryDecision::Verified
        && let Some(client_hello) = client_hello
    {
        progress(
            attempts,
            usize::from(max_retries) + 1,
            "точный APPLIED получен",
            "проверяется ClientHello из живого потока",
        );
        let snapshot_applied = r2o_discovery_client_shape_trial(
            target,
            &candidate.plan_text,
            client_hello,
            mark,
            commands,
        )
        .unwrap_or(false);
        attempts += 1;
        progress(
            attempts,
            usize::from(max_retries) + 2,
            if snapshot_applied {
                "точный APPLIED получен для ClientHello"
            } else {
                "ClientHello не подтверждён"
            },
            if snapshot_applied {
                "проверка плана завершена"
            } else {
                "план не прошёл проверку ClientHello из живого потока"
            },
        );
        return (result, applied && snapshot_applied, attempts, evidence);
    }
    (result, applied, attempts, evidence)
}

#[cfg(unix)]
fn r2o_discovery_candidate_retry_count(probe_budget_remaining: usize) -> Option<u8> {
    (probe_budget_remaining > 0).then(|| {
        R2O_DISCOVERY_CANDIDATE_VERIFY_RETRIES.min(
            probe_budget_remaining
                .saturating_sub(1)
                .min(u8::MAX as usize) as u8,
        )
    })
}

fn r2o_candidate_confirmation_mark(_direct_probe_mark: Option<u32>) -> Option<u32> {
    // The direct-probe mark deliberately bypasses NFQUEUE. Candidate proof must
    // traverse the datapath; None would inherit BoundTcpProbe's bypass default.
    Some(0)
}

#[cfg(unix)]
fn r2o_repeat_candidate_trials<T>(
    max_retries: u8,
    mut trial: impl FnMut() -> T,
    mut should_retry: impl FnMut(&T) -> bool,
) -> T {
    for attempt in 0..=max_retries {
        let result = trial();
        if attempt == max_retries || !should_retry(&result) {
            return result;
        }
    }
    unreachable!("цикл повторов кандидата всегда возвращает исход")
}

#[cfg(unix)]
fn r2o_discovery_layered_rx_candidate_trials<T>(
    layered_rx: bool,
    request_encoding: r2o_controller::fetch::R2oFetchEncoding,
    probe_budget_remaining: usize,
    mut retry_budget_available: impl FnMut() -> bool,
    mut wait_before_next: impl FnMut(),
    mut run_trial: impl FnMut(r2o_controller::fetch::R2oFetchEncoding) -> T,
    mut observation: impl FnMut(&T) -> Option<r2o_controller::r2o_volume::R2oVolumeObservation>,
) -> (
    T,
    bool,
    usize,
    Option<r2o_controller::r2o_volume::R2oVolumeRxEvidence>,
) {
    let first_encoding = if layered_rx {
        r2o_controller::fetch::r2o_d2o_layered_rx_candidate_encoding(0)
            .expect("d2o layered RX identity phase")
    } else {
        request_encoding
    };
    let mut trial = run_trial(first_encoding);
    let mut attempts = 1;
    let Some(first_observation) = layered_rx
        .then(|| observation(&trial))
        .flatten()
        .filter(r2o_controller::r2o_volume::r2o_volume_rx_partial)
    else {
        return (trial, false, attempts, None);
    };
    if attempts >= probe_budget_remaining || !retry_budget_available() {
        return (trial, true, attempts, None);
    }

    wait_before_next();
    let identity = r2o_controller::fetch::r2o_d2o_layered_rx_candidate_encoding(1)
        .expect("d2o layered RX repeat phase");
    let second = run_trial(identity);
    attempts += 1;
    let second_observation = observation(&second);
    let repeat_agrees = second_observation.is_some_and(|second| {
        r2o_controller::r2o_volume::r2o_volume_rx_partial(&second)
            && r2o_controller::r2o_volume::r2o_volume_rx_layered_repeat_agrees(
                &first_observation,
                &second,
            )
    });
    trial = second;
    if !repeat_agrees || attempts >= probe_budget_remaining || !retry_budget_available() {
        return (trial, true, attempts, None);
    }

    wait_before_next();
    let gzip = r2o_controller::fetch::r2o_d2o_layered_rx_candidate_encoding(2)
        .expect("d2o layered RX gzip phase");
    trial = run_trial(gzip);
    attempts += 1;
    let evidence = observation(&trial).and_then(|gzip| {
        r2o_controller::r2o_volume::r2o_volume_rx_evidence(
            &first_observation,
            &second_observation.expect("agreed layered RX repeat"),
            &gzip,
        )
    });
    (trial, true, attempts, evidence)
}

#[cfg(unix)]
fn r2o_discovery_candidate_retryable(
    result: &Result<r2o_controller::fetch::FetchResult, String>,
    applied: bool,
    transport_established: bool,
) -> bool {
    if !applied {
        return false;
    }
    let Ok(fetch) = result else {
        return transport_established;
    };
    transport_established
        && !fetch.r2o_volume_observation.local_limit
        && !fetch.cloudflare_challenge
        && fetch.http_outcome != r2o_controller::fetch::R2oFetchHttpOutcome::LegalDenial
}

#[cfg(unix)]
fn r2o_discovery_layered_rx_observation(
    result: &Result<r2o_controller::fetch::FetchResult, String>,
    applied: bool,
) -> Option<r2o_controller::r2o_volume::R2oVolumeObservation> {
    if !applied {
        return None;
    }
    result.as_ref().ok().and_then(|fetch| {
        (!matches!(
            fetch.http_outcome,
            r2o_controller::fetch::R2oFetchHttpOutcome::Blocked
                | r2o_controller::fetch::R2oFetchHttpOutcome::LegalDenial
        ))
        .then_some(fetch.r2o_volume_observation)
    })
}

#[cfg(unix)]
fn r2o_discovery_search_owned(
    raw_usable: bool,
    rst_rule_failures: usize,
    measured_arm: bool,
) -> bool {
    measured_arm || raw_usable && rst_rule_failures == 0
}

fn r2o_discovery_split_needs_raw(verdict: Verdict) -> bool {
    matches!(verdict, Verdict::Prefix | Verdict::WholePacket)
}

fn r2o_discovery_split_raw_executed(verdict: Verdict, raw_dials: u64) -> bool {
    r2o_discovery_split_needs_raw(verdict) && raw_dials > 0
}

fn r2o_discovery_split_gate(
    verdict: Verdict,
    split_pos: Option<usize>,
    raw_dials: u64,
) -> (Verdict, Option<usize>, bool) {
    let socket_only = r2o_discovery_split_needs_raw(verdict)
        && !r2o_discovery_split_raw_executed(verdict, raw_dials);
    if socket_only {
        (Verdict::Flaky, None, true)
    } else {
        (verdict, split_pos, false)
    }
}

fn r2o_discovery_bridge_search_owned(
    socket_only_split: bool,
    raw_usable: bool,
    raw_split_executed: bool,
    rst_rule_failures: usize,
    measured_arm: bool,
) -> bool {
    socket_only_split
        || r2o_discovery_search_owned(
            raw_usable || raw_split_executed,
            rst_rule_failures,
            measured_arm,
        )
}

#[cfg(unix)]
fn r2o_discovery_measured_fallback_allowed(
    measured_arm: bool,
    result: &Result<r2o_controller::fetch::FetchResult, String>,
    applied: bool,
    evidence: R2oCandidateTrialEvidence,
) -> bool {
    if !measured_arm {
        return false;
    }
    if result.as_ref().is_ok_and(|fetch| {
        fetch.cloudflare_challenge
            || fetch.http_outcome == r2o_controller::fetch::R2oFetchHttpOutcome::LegalDenial
    }) {
        return false;
    }
    r2o_controller::r2o_fallback::MeasuredArmFailure {
        transport: 6,
        // This runner receives only the arm returned by the full detect provider.
        search_owned: true,
        owned_fallback: false,
        own_first: 0,
        after_cached: true,
        arm_matches: true,
        applied,
        local_limit: evidence.local_limit,
        dropped_before: evidence.dropped_before,
        dropped_after: evidence.dropped_after,
        transport_established: evidence.transport_established,
    }
    .fallback_enabled()
}

#[cfg(unix)]
fn r2o_discovery_measured_split_plan(
    verdict: Verdict,
    search_owned: bool,
    split_pos: Option<usize>,
    trigger_len: usize,
    gap_us: u32,
    send_cap: usize,
) -> Option<String> {
    if !search_owned || !matches!(verdict, Verdict::Prefix | Verdict::WholePacket) {
        return None;
    }
    let split = split_pos?;
    if trigger_len > 16_384 || split == 0 || split >= trigger_len {
        return None;
    }
    let segment = if send_cap == 0 {
        1400
    } else {
        send_cap.saturating_sub(72).min(1400)
    };
    (segment > 0).then(|| {
        format!(
            "r2o-plan 1 5\nid 00000000000000000000000000000000\nproto tcp tls\nwire detect-tcp-v1\nsegment {segment}\nsplit payload_start +{split}\norder forward\npace {gap_us}\n"
        )
    })
}

#[cfg(unix)]
fn r2o_discovery_owned_fallback_needed(
    timed_out: bool,
    search_owned: bool,
    verdict: Verdict,
    has_plan: bool,
) -> bool {
    !timed_out && search_owned && verdict == Verdict::Opaque && !has_plan
}

#[cfg(unix)]
fn r2o_discovery_plan_shape(shape: u8) -> u8 {
    if shape == SHAPE_ECH_TCP {
        SHAPE_MODERN
    } else {
        shape
    }
}

#[cfg(unix)]
fn r2o_discovery_client_shape_trial(
    target: &r2o_controller::discovery::DiscoveryTarget,
    source_text: &str,
    client_hello: &[u8],
    mark: Option<u32>,
    commands: &SyncSender<HttpSearchCommand>,
) -> Result<bool, String> {
    let destination = target
        .endpoint
        .parse::<std::net::SocketAddr>()
        .map_err(|error| format!("адрес снимка ClientHello недопустим: {error}"))?;
    let bound = BoundTcpProbe::open(target.family, r2o_candidate_confirmation_mark(mark))
        .map_err(|error| format!("не удалось открыть сокет снимка ClientHello: {error}"))?;
    let local_port = bound.local_port;
    let trial_id = random_id().map_err(|error| error.to_string())?;
    let records = compile_text(source_text).map_err(|error| error.to_string())?;
    let plan = Plan::parse(&records).map_err(|error| error.to_string())?;
    let command = encode_set_name_probe(
        &target.host,
        target.shape,
        target.family,
        local_port,
        &records,
        trial_id,
    )
    .map_err(|error| error.to_string())?;
    let ack = ask_http_controller(commands, |reply| HttpSearchCommand::InstallProbe {
        host: target.host.clone(),
        shape: target.shape,
        family: target.family,
        port: local_port,
        command,
        trial_id,
        candidate_settle: true,
        reply,
    })?;
    if ack
        .as_ref()
        .is_some_and(|ack| ack.trial_id != Some(trial_id))
    {
        let _ = ask_http_controller(commands, |reply| HttpSearchCommand::DeleteProbe {
            host: target.host.clone(),
            shape: target.shape,
            family: target.family,
            port: local_port,
            reply,
        });
        return Err("подтверждение пробы снимка содержит чужой trial ID".into());
    }
    if ack.as_ref().is_some_and(|ack| !ack.ok) {
        ask_http_controller(commands, |reply| HttpSearchCommand::DeleteProbe {
            host: target.host.clone(),
            shape: target.shape,
            family: target.family,
            port: local_port,
            reply,
        })?;
        return Err("датапат отверг временный план снимка ClientHello".into());
    }

    let mut socket_hold = None;
    let send_result = match bound.connect(
        destination,
        r2o_controller::fetch::R2O_D2O_VERIFY_STEP_TIMEOUT,
    ) {
        Ok((mut stream, _, connected_port, _)) if connected_port == local_port => {
            match stream.try_clone() {
                Ok(held) => {
                    socket_hold = Some(held);
                    r2o_controller::r2o_tls::r2o_tls_replay_client_hello(
                        &mut stream,
                        client_hello,
                        r2o_controller::fetch::R2O_D2O_VERIFY_STEP_TIMEOUT,
                    )
                    .map_err(|error| format!("не удалось повторить снимок ClientHello: {error}"))
                }
                Err(error) => Err(format!("не удалось удержать сокет до APPLIED: {error}")),
            }
        }
        Ok((_stream, _, _, _)) => Err("сокет снимка получил неожиданный локальный порт".into()),
        Err(error) => Err(format!("не удалось подключить снимок ClientHello: {error}")),
    };
    let events = r2o_collect_controller_applied_events_until(
        commands,
        trial_id,
        if send_result.as_ref().is_ok_and(|proof| *proof) {
            std::time::Duration::from_secs(5)
        } else {
            std::time::Duration::ZERO
        },
        |event| r2o_family_applied_flow_matches(event, target, local_port, plan.id, trial_id),
    );
    let delete_result = ask_http_controller(commands, |reply| HttpSearchCommand::DeleteProbe {
        host: target.host.clone(),
        shape: target.shape,
        family: target.family,
        port: local_port,
        reply,
    });
    drop(socket_hold);
    let server_hello = send_result?;
    delete_result?;
    let events = events?;
    Ok(server_hello
        && events.iter().any(|event| {
            r2o_family_applied_flow_matches(event, target, local_port, plan.id, trial_id)
        }))
}

#[cfg(unix)]
fn r2o_family_applied_flow_matches(
    event: &r2k_core::control::AppliedEvent,
    target: &r2o_controller::discovery::DiscoveryTarget,
    local_port: u16,
    plan_id: [u8; 16],
    trial_id: [u8; 16],
) -> bool {
    let Ok(endpoint) = target.endpoint.parse::<std::net::SocketAddr>() else {
        return false;
    };
    if event.key[0] != target.family
        || event.key[37] != 6
        || event.trial_id != trial_id
        || event.plan_id != plan_id
    {
        return false;
    }
    let low_port = u16::from_be_bytes([event.key[33], event.key[34]]);
    let high_port = u16::from_be_bytes([event.key[35], event.key[36]]);
    let server_bytes = if low_port == local_port && high_port == endpoint.port() {
        &event.key[17..33]
    } else if high_port == local_port && low_port == endpoint.port() {
        &event.key[1..17]
    } else {
        return false;
    };
    match endpoint.ip() {
        std::net::IpAddr::V4(ip) => server_bytes[..4] == ip.octets(),
        std::net::IpAddr::V6(ip) => server_bytes == ip.octets(),
    }
}

#[cfg(unix)]
impl R2oLateRxWorker {
    fn new(measurement_gate: r2o_controller::r2o_resource_limit::R2oMeasurementGate) -> Self {
        let (jobs, job_receiver) =
            mpsc::sync_channel::<R2oLateRxInput>(R2O_LATE_RX_TASK_CAPACITY - 1);
        let (outcome_sender, outcomes) = mpsc::sync_channel(R2O_LATE_RX_TASK_CAPACITY);
        let cancel = Arc::new(AtomicBool::new(false));
        let worker_cancel = Arc::clone(&cancel);
        let worker_gate = measurement_gate.clone();
        let thread = std::thread::spawn(move || {
            while let Ok(input) = job_receiver.recv() {
                if worker_cancel.load(Ordering::Relaxed) {
                    break;
                }
                let result = {
                    let Some(_permit) = worker_gate.r2o_acquire_tcp(&worker_cancel) else {
                        break;
                    };
                    r2o_controller::fetch::r2o_fetch_measure_rx_volume_with_fallback_path(
                        &input.options,
                        input.alternate_path.as_deref(),
                    )
                };
                if outcome_sender
                    .send(R2oLateRxOutcome { input, result })
                    .is_err()
                {
                    break;
                }
            }
        });
        Self {
            jobs: Some(jobs),
            outcomes,
            cancel,
            active: HashSet::new(),
            thread: Some(thread),
        }
    }

    fn queue(
        &mut self,
        input: R2oLateRxInput,
        now: std::time::Instant,
        discovery: Option<&DiscoveryWorker>,
    ) -> bool {
        if input.discovery_target.as_ref().is_some_and(|target| {
            discovery.is_some_and(|worker| worker.r2o_late_trigger_blocked(target, now))
        }) {
            return false;
        }
        let failure_key = r2o_late_rx_failure_key(&input);
        if self.active.contains(&failure_key) {
            return false;
        }
        let Some(jobs) = self.jobs.as_ref() else {
            return false;
        };
        if jobs.try_send(input).is_err() {
            return false;
        }
        self.active.insert(failure_key);
        true
    }

    fn try_outcome(&mut self) -> Option<R2oLateRxOutcome> {
        let outcome = self.outcomes.try_recv().ok()?;
        self.active.remove(&r2o_late_rx_failure_key(&outcome.input));
        Some(outcome)
    }
}

#[cfg(unix)]
impl Drop for R2oLateRxWorker {
    fn drop(&mut self) {
        self.cancel.store(true, Ordering::Relaxed);
        self.jobs.take();
        if let Some(thread) = self.thread.take() {
            let _ = thread.join();
        }
    }
}

#[cfg(unix)]
struct HttpSearchWorker {
    jobs: Option<mpsc::Sender<HttpSearchTask>>,
    command_sender: SyncSender<HttpSearchCommand>,
    commands: Option<Receiver<HttpSearchCommand>>,
    outcomes: Option<Receiver<HttpSearchOutcome>>,
    pending_jobs: Arc<AtomicUsize>,
    records: Arc<std::sync::Mutex<HttpSearchRecordCache>>,
    cancel: Arc<AtomicBool>,
    thread: Option<JoinHandle<()>>,
}

#[cfg(unix)]
impl HttpSearchWorker {
    fn new(measurement_gate: r2o_controller::r2o_resource_limit::R2oMeasurementGate) -> Self {
        let (job_sender, job_receiver) = mpsc::channel::<HttpSearchTask>();
        let pending_jobs = Arc::new(AtomicUsize::new(0));
        let worker_pending_jobs = Arc::clone(&pending_jobs);
        let (command_sender, commands) = mpsc::sync_channel::<HttpSearchCommand>(16);
        let worker_command_sender = command_sender.clone();
        let (outcome_sender, outcomes) = mpsc::sync_channel::<HttpSearchOutcome>(16);
        let records = Arc::new(std::sync::Mutex::new(HttpSearchRecordCache::default()));
        let worker_records = Arc::clone(&records);
        let cancel = Arc::new(AtomicBool::new(false));
        let worker_cancel = Arc::clone(&cancel);
        let worker_gate = measurement_gate.clone();
        let thread = std::thread::spawn(move || {
            let mut diagnostic_seq = 0_u64;
            while let Ok(task) = job_receiver.recv() {
                worker_pending_jobs.fetch_sub(1, Ordering::Relaxed);
                if worker_cancel.load(Ordering::Relaxed) {
                    break;
                }
                let target = task.target.clone();
                let Some(_permit) = worker_gate.r2o_acquire_tcp(&worker_cancel) else {
                    break;
                };
                diagnostic_seq = diagnostic_seq.wrapping_add(1);
                let diagnostic_started = std::time::Instant::now();
                let (result, disposition, terminal, creates_record, revoke_owned_binding) = {
                    match run_http_search_task(task, &worker_command_sender, &worker_cancel) {
                        Ok(completion) => (
                            Ok(()),
                            completion.disposition,
                            completion.diagnostic,
                            completion.creates_record,
                            completion.revoke_owned_binding,
                        ),
                        Err(failure) => (
                            Err(failure.message),
                            HttpSearchDisposition::Inconclusive,
                            Some(failure.diagnostic),
                            failure.creates_record,
                            None,
                        ),
                    }
                };
                if creates_record {
                    worker_records
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner)
                        .record(&target);
                }
                let diagnostic_event = terminal.map(|terminal| {
                    r2o_http_search_diagnostic_event(
                        diagnostic_seq,
                        &target,
                        diagnostic_started
                            .elapsed()
                            .as_millis()
                            .min(u64::MAX as u128) as u64,
                        terminal,
                    )
                });
                drop(_permit);
                if outcome_sender
                    .send(HttpSearchOutcome {
                        target,
                        result,
                        disposition,
                        diagnostic_event,
                        revoke_owned_binding,
                    })
                    .is_err()
                {
                    break;
                }
            }
        });
        Self {
            jobs: Some(job_sender),
            command_sender,
            commands: Some(commands),
            outcomes: Some(outcomes),
            pending_jobs,
            records,
            cancel,
            thread: Some(thread),
        }
    }

    fn queue(&self, task: HttpSearchTask) -> bool {
        let Some(jobs) = self.jobs.as_ref() else {
            return false;
        };
        self.pending_jobs.fetch_add(1, Ordering::Relaxed);
        if jobs.send(task).is_ok() {
            true
        } else {
            self.pending_jobs.fetch_sub(1, Ordering::Relaxed);
            false
        }
    }

    fn queued_jobs(&self) -> usize {
        self.pending_jobs.load(Ordering::Relaxed)
    }

    fn record_cut(&self, target: &r2o_controller::discovery::DiscoveryTarget, path: &[u8]) {
        self.records
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .record_cut(target, path);
    }

    fn record_repeat_path(&self, target: &r2o_controller::discovery::DiscoveryTarget, path: &[u8]) {
        self.records
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .record_repeat_path(target, path);
    }

    fn search_context(
        &self,
        target: &r2o_controller::discovery::DiscoveryTarget,
        event_path: &[u8],
        event_baseline: r2o_controller::http_search::Answer,
    ) -> Option<(Vec<u8>, r2o_controller::http_search::Answer)> {
        self.records
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .context(target, event_path, event_baseline)
    }

    fn record_count(&self) -> usize {
        self.records
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .count()
    }

    fn seed_records(&self, catalog: &Catalog) {
        let mut records = self
            .records
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        for box_record in &catalog.boxes {
            for binding in &box_record.bindings {
                if !binding.enabled
                    || binding.kind != "name"
                    || binding.transport != 6
                    || binding.family != 4 && binding.family != 6
                    || binding.shape != SHAPE_HTTP
                    || binding.verified_by != R2O_D2K_VERBY_PROBE
                {
                    continue;
                }
                let Some(plan) = box_record.plans.iter().find(|plan| {
                    plan.enabled
                        && plan.proto == "http"
                        && plan.id.eq_ignore_ascii_case(&binding.plan_id)
                }) else {
                    continue;
                };
                if candidate_key_from_plan_text(&plan.text).is_some() {
                    records.record_name(&binding.target, binding.family);
                }
            }
        }
    }

    fn try_command(&self) -> Option<HttpSearchCommand> {
        self.commands.as_ref()?.try_recv().ok()
    }

    fn command_sender(&self) -> SyncSender<HttpSearchCommand> {
        self.command_sender.clone()
    }

    fn try_outcome(&self) -> Option<HttpSearchOutcome> {
        self.outcomes.as_ref()?.try_recv().ok()
    }
}

#[cfg(unix)]
impl Drop for HttpSearchWorker {
    fn drop(&mut self) {
        self.cancel.store(true, Ordering::Relaxed);
        self.jobs.take();
        self.commands.take();
        self.outcomes.take();
        if let Some(thread) = self.thread.take() {
            let _ = thread.join();
        }
    }
}

#[cfg(unix)]
const R2O_QUIC_DISCOVERY_WORKER_COUNT: usize = 2;

#[cfg(unix)]
type R2oQuicDiscoveryRunner = dyn Fn(
        &mut R2oQuicDiscoveryTask,
        SyncSender<HttpSearchCommand>,
        Arc<AtomicBool>,
    ) -> Result<Option<(String, String)>, String>
    + Send
    + Sync;

#[cfg(unix)]
struct R2oQuicDiscoveryJob {
    task: R2oQuicDiscoveryTask,
    remeasured: Arc<AtomicBool>,
}

#[cfg(unix)]
struct R2oQuicActiveSnapshot {
    host: String,
    remeasured: Arc<AtomicBool>,
}

#[cfg(unix)]
struct R2oQuicDiscoveryWorker {
    jobs: Option<SyncSender<R2oQuicDiscoveryJob>>,
    commands: Option<Receiver<HttpSearchCommand>>,
    outcomes: Receiver<R2oQuicDiscoveryOutcome>,
    cancel: Arc<AtomicBool>,
    active: HashMap<std::net::SocketAddr, R2oQuicActiveSnapshot>,
    pending_snapshots: Arc<std::sync::Mutex<HashMap<std::net::SocketAddr, (Vec<u8>, String)>>>,
    threads: Vec<JoinHandle<()>>,
}

#[cfg(unix)]
impl R2oQuicDiscoveryWorker {
    fn new() -> Self {
        Self::r2o_new_with_runner(Arc::new(|task, commands, cancel| {
            ControlClient::r2o_run_quic_discovery_trial(
                task.server,
                &task.snapshot,
                &task.probe_path,
                &commands,
                &cancel,
                task.started_at,
                &mut task.permit,
                task.r2o_mark,
                task.deny_recheck,
                &mut task.stall_cut,
            )
            .map_err(|error| error.to_string())
        }))
    }

    fn r2o_new_with_runner(runner: Arc<R2oQuicDiscoveryRunner>) -> Self {
        let (jobs, job_receiver) =
            mpsc::sync_channel::<R2oQuicDiscoveryJob>(R2O_QUIC_DISCOVERY_WORKER_COUNT);
        let job_receiver = Arc::new(std::sync::Mutex::new(job_receiver));
        let (command_sender, commands) = mpsc::sync_channel::<HttpSearchCommand>(16);
        let (outcome_sender, outcomes) =
            mpsc::sync_channel::<R2oQuicDiscoveryOutcome>(R2O_QUIC_DISCOVERY_WORKER_COUNT);
        let cancel = Arc::new(AtomicBool::new(false));
        let pending_snapshots = Arc::new(std::sync::Mutex::new(HashMap::new()));
        let mut threads = Vec::with_capacity(R2O_QUIC_DISCOVERY_WORKER_COUNT);
        for _ in 0..R2O_QUIC_DISCOVERY_WORKER_COUNT {
            let worker_jobs = Arc::clone(&job_receiver);
            let worker_commands = command_sender.clone();
            let worker_outcomes = outcome_sender.clone();
            let worker_cancel = Arc::clone(&cancel);
            let worker_snapshots = Arc::clone(&pending_snapshots);
            let worker_runner = Arc::clone(&runner);
            threads.push(std::thread::spawn(move || {
                loop {
                    let job = worker_jobs
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner)
                        .recv();
                    let Ok(mut job) = job else {
                        break;
                    };
                    if worker_cancel.load(Ordering::Relaxed) {
                        break;
                    }
                    let server = job.task.server;
                    let deny_recheck = job.task.deny_recheck;
                    let mut result = worker_runner(
                        &mut job.task,
                        worker_commands.clone(),
                        Arc::clone(&worker_cancel),
                    );
                    let replacement = {
                        let mut snapshots = worker_snapshots
                            .lock()
                            .unwrap_or_else(std::sync::PoisonError::into_inner);
                        let replacement = if !worker_cancel.load(Ordering::Relaxed)
                            && !job.remeasured.load(Ordering::Relaxed)
                        {
                            snapshots.remove(&server)
                        } else {
                            snapshots.remove(&server);
                            None
                        };
                        job.remeasured.store(true, Ordering::Relaxed);
                        replacement
                    };
                    if let Some((snapshot, probe_path)) = replacement {
                        job.task.snapshot = snapshot;
                        job.task.probe_path = probe_path;
                        job.task.stall_cut = false;
                        result = worker_runner(
                            &mut job.task,
                            worker_commands.clone(),
                            Arc::clone(&worker_cancel),
                        );
                    }
                    worker_snapshots
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner)
                        .remove(&server);
                    if worker_outcomes
                        .send(R2oQuicDiscoveryOutcome {
                            server,
                            snapshot: job.task.snapshot.clone(),
                            host: r2o_quic_snapshot_server_name(&job.task.snapshot, server)
                                .unwrap_or_else(|| server.ip().to_string()),
                            probe_path: job.task.probe_path.clone(),
                            deny_recheck,
                            stall_cut: job.task.stall_cut,
                            result,
                        })
                        .is_err()
                    {
                        break;
                    }
                }
            }));
        }
        Self {
            jobs: Some(jobs),
            commands: Some(commands),
            outcomes,
            cancel,
            active: HashMap::new(),
            pending_snapshots,
            threads,
        }
    }

    fn queue(&mut self, task: R2oQuicDiscoveryTask) -> bool {
        let server = task.server;
        if self.active.contains_key(&server) {
            return false;
        }
        let Some(host) = r2o_quic_snapshot_server_name(&task.snapshot, server) else {
            return false;
        };
        let Some(jobs) = self.jobs.as_ref() else {
            return false;
        };
        let remeasured = Arc::new(AtomicBool::new(false));
        if jobs
            .try_send(R2oQuicDiscoveryJob {
                task,
                remeasured: Arc::clone(&remeasured),
            })
            .is_err()
        {
            return false;
        }
        self.active
            .insert(server, R2oQuicActiveSnapshot { host, remeasured });
        true
    }

    fn queue_client_snapshot(
        &self,
        hello: &r2k_core::control::HelloEvent,
        catalog: &Catalog,
        resource_memory: &std::sync::Mutex<r2o_controller::r2o_resource::R2oResourceMemory>,
    ) -> bool {
        if hello.key[37] != 17 || hello.shape != Some(SHAPE_QUIC) {
            return false;
        }
        let Some(snapshot) = hello.quic_snapshot.as_ref() else {
            return false;
        };
        let (low, high) = flow_socket_addresses(&hello.key, true);
        let event_host = match hello.host.as_deref() {
            Some(host) => match std::str::from_utf8(host) {
                Ok(host) => Some(host),
                Err(_) => return false,
            },
            None => None,
        };
        for (server, active) in &self.active {
            if *server != low && *server != high {
                continue;
            }
            if active.remeasured.load(Ordering::Relaxed) {
                return false;
            }
            let matches_host = event_host.map_or_else(
                || active.host == server.ip().to_string(),
                |host| active.host == host,
            );
            if !matches_host {
                return false;
            }
            let mut snapshots = self
                .pending_snapshots
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            if active.remeasured.load(Ordering::Relaxed) {
                return false;
            }
            let probe_path =
                r2o_quic_discovery_probe_path(snapshot, *server, catalog, resource_memory);
            snapshots.insert(*server, (snapshot.clone(), probe_path));
            return true;
        }
        false
    }

    fn has_capacity(&self) -> bool {
        self.active.len() < R2O_QUIC_DISCOVERY_WORKER_COUNT
    }

    fn try_command(&self) -> Option<HttpSearchCommand> {
        self.commands.as_ref()?.try_recv().ok()
    }

    fn try_outcome(&mut self) -> Option<R2oQuicDiscoveryOutcome> {
        let outcome = self.outcomes.try_recv().ok()?;
        self.active.remove(&outcome.server);
        self.pending_snapshots
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .remove(&outcome.server);
        Some(outcome)
    }

    fn r2o_begin_shutdown(&mut self) {
        self.cancel.store(true, Ordering::Relaxed);
        self.jobs.take();
        self.pending_snapshots
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .clear();
    }

    fn r2o_all_finished(&self) -> bool {
        self.threads.iter().all(JoinHandle::is_finished)
    }

    fn r2o_join(&mut self) {
        for thread in self.threads.drain(..) {
            let _ = thread.join();
        }
        self.commands.take();
    }
}

#[cfg(unix)]
impl Drop for R2oQuicDiscoveryWorker {
    fn drop(&mut self) {
        self.r2o_begin_shutdown();
        self.commands.take();
        self.r2o_join();
    }
}

