#[cfg(unix)]
#[derive(Default)]
struct R2oDiscoveryVolumeSearchCache {
    carried_rx: HashMap<R2oDiscoveryTaskKey, R2oDiscoveryVolumeSearch>,
    entries: VecDeque<(
        r2o_controller::discovery::DiscoveryTarget,
        R2oDiscoveryVolumeSearch,
    )>,
}

#[cfg(unix)]
impl R2oDiscoveryVolumeSearchCache {
    fn get(
        &mut self,
        target: &r2o_controller::discovery::DiscoveryTarget,
        key: &R2oDiscoveryVolumeSearchKey,
        now: std::time::Instant,
    ) -> Option<R2oDiscoveryVolumeSearch> {
        self.entries.retain(|(_, search)| {
            now.saturating_duration_since(search.measured_at) < R2O_DISCOVERY_TASK_LIFETIME
        });
        let index = self
            .entries
            .iter()
            .position(|(candidate, _)| candidate == target)?;
        let mut cached_key = self.entries[index].1.key.clone();
        cached_key.network_probe = key.network_probe;
        if cached_key != *key {
            self.entries.remove(index);
            return None;
        }
        let entry = self.entries.remove(index)?;
        let search = entry.1.clone();
        self.entries.push_back(entry);
        Some(search)
    }

    fn carry_proven_rx_for_snapshot(
        &mut self,
        target: &r2o_controller::discovery::DiscoveryTarget,
        task_key: &R2oDiscoveryTaskKey,
    ) {
        let Some(index) = self
            .entries
            .iter()
            .position(|(candidate, _)| candidate == target)
        else {
            return;
        };
        let Some((_, mut search)) = self.entries.remove(index) else {
            return;
        };
        if search.rx.evidence.is_some() {
            search.next_candidate = 0;
            self.carried_rx.insert(task_key.clone(), search);
        }
    }

    fn get_for_run(
        &mut self,
        target: &r2o_controller::discovery::DiscoveryTarget,
        task_key: &R2oDiscoveryTaskKey,
        key: &R2oDiscoveryVolumeSearchKey,
        now: std::time::Instant,
    ) -> Option<R2oDiscoveryVolumeSearch> {
        self.carried_rx
            .remove(task_key)
            .or_else(|| self.get(target, key, now))
    }

    fn has_volume_cut_for_run(
        &self,
        target: &r2o_controller::discovery::DiscoveryTarget,
        task_key: &R2oDiscoveryTaskKey,
        key: &R2oDiscoveryVolumeSearchKey,
        now: std::time::Instant,
    ) -> bool {
        if self
            .carried_rx
            .get(task_key)
            .is_some_and(|search| r2o_discovery_volume_cut(&search.tx, &search.rx))
        {
            return true;
        }
        self.entries.iter().any(|(candidate, search)| {
            if candidate != target
                || !r2o_discovery_volume_cut(&search.tx, &search.rx)
                || now.saturating_duration_since(search.measured_at) >= R2O_DISCOVERY_TASK_LIFETIME
            {
                return false;
            }
            let mut cached_key = search.key.clone();
            cached_key.network_probe = key.network_probe;
            cached_key == *key
        })
    }

    fn forget_carried_rx(&mut self, task_key: &R2oDiscoveryTaskKey) {
        self.carried_rx.remove(task_key);
    }

    fn insert(
        &mut self,
        target: r2o_controller::discovery::DiscoveryTarget,
        search: R2oDiscoveryVolumeSearch,
    ) {
        self.entries.retain(|(candidate, _)| candidate != &target);
        self.entries.push_back((target, search));
        while self.entries.len() > R2O_VOLUME_SEARCH_CACHE_CAPACITY {
            self.entries.pop_front();
        }
    }

    fn remove(&mut self, target: &r2o_controller::discovery::DiscoveryTarget) {
        self.entries.retain(|(candidate, _)| candidate != target);
    }
}

