    fn queue_client_snapshot_with_tcp_timestamp_and_planned_and_trigger(
        &mut self,
        target: r2o_controller::discovery::DiscoveryTarget,
        client_hello: Vec<u8>,
        tcp_has_timestamp: Option<bool>,
        trigger_planned: bool,
        trigger_code: Option<u8>,
    ) -> bool {
        if self.r2o_discovery_challenge_active(&target, std::time::Instant::now()) {
            return false;
        }
        if !self.remember_client_snapshot(&target, &client_hello, tcp_has_timestamp) {
            return false;
        }
        if target.shape == SHAPE_ECH_TCP && self.r2o_record_ech_input(&target) {
            self.r2o_clear_ech_profile_failures(&target.host, target.family);
        }
        let task_key = r2o_discovery_task_key(&target);
        // C on_shape keeps an experiment's owned ClientHello immutable.
        if self.active.get(&task_key).is_some_and(|active_target| {
            matches!(
                active_target.shape,
                SHAPE_MODERN | SHAPE_LEGACY | SHAPE_ECH_TCP
            ) && active_target.shape != target.shape
        }) {
            return false;
        }
        if self.active.contains_key(&task_key)
            && self
                .client_hellos
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .contains_key(&task_key)
        {
            return false;
        }
        {
            let mut client_tcp_timestamps = self
                .client_tcp_timestamps
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            if let Some(tcp_has_timestamp) = tcp_has_timestamp {
                client_tcp_timestamps.insert(task_key.clone(), tcp_has_timestamp);
            } else {
                client_tcp_timestamps.remove(&task_key);
            }
        }
        self.completed.remove(&task_key);
        if self.active.contains_key(&task_key) {
            self.client_snapshot_reasks
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .insert(task_key.clone());
            self.catalog_refreshes
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .remove(&task_key);
            self.pending_rechecks.insert(
                task_key.clone(),
                (target, Some(client_hello), trigger_planned),
            );
            if let Some(cancel) = self
                .active_cancels
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .get(&task_key)
            {
                cancel.store(true, Ordering::Relaxed);
            }
            return true;
        }
        self.seen.remove(&target);
        self.seen_order.retain(|seen| seen != &target);
        self.client_hellos
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .insert(task_key, client_hello);
        if !self.queue_with_tcp_timestamp_and_planned_and_trigger(
            target.clone(),
            tcp_has_timestamp,
            trigger_planned,
            trigger_code,
        ) {
            self.client_hellos
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .remove(&r2o_discovery_task_key(&target));
            return false;
        }
        self.client_snapshot_targets
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .insert(target);
        true
    }

    fn has_recent_client_shape(&self, target: &r2o_controller::discovery::DiscoveryTarget) -> bool {
        self.recent_client_shapes
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .get(target)
            .is_some()
    }

    fn queue_client_snapshot_after_confirmed_failure_with_planned_and_trigger(
        &mut self,
        target: r2o_controller::discovery::DiscoveryTarget,
        client_hello: Vec<u8>,
        tcp_has_timestamp: Option<bool>,
        trigger_planned: bool,
        trigger_code: Option<u8>,
    ) -> bool {
        if !self.active.contains_key(&r2o_discovery_task_key(&target)) {
            let task_key = r2o_discovery_task_key(&target);
            self.seen.remove(&target);
            self.seen_order.retain(|seen| seen != &target);
            self.completed.remove(&task_key);
            let failure_key = r2o_discovery_failure_key(&target);
            self.r2o_clear_failed_endpoint(&failure_key);
            self.failed_retry_after.remove(&failure_key);
        }
        self.queue_client_snapshot_with_tcp_timestamp_and_planned_and_trigger(
            target,
            client_hello,
            tcp_has_timestamp,
            trigger_planned,
            trigger_code,
        )
    }

    fn remember_client_snapshot(
        &mut self,
        target: &r2o_controller::discovery::DiscoveryTarget,
        client_hello: &[u8],
        tcp_has_timestamp: Option<bool>,
    ) -> bool {
        let shape = r2k_core::tls::parse(client_hello);
        let observed_shape = if shape.ech_offer {
            SHAPE_ECH_TCP
        } else if shape.is_tls13 {
            SHAPE_MODERN
        } else {
            SHAPE_LEGACY
        };
        if !matches!(target.shape, SHAPE_MODERN | SHAPE_LEGACY | SHAPE_ECH_TCP)
            || observed_shape != target.shape
            || Trigger::tls_client_hello(&target.host, client_hello).is_err()
        {
            return false;
        }
        self.recent_client_shapes
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .note(target, client_hello, tcp_has_timestamp);
        true
    }

    fn r2o_record_ech_input(
        &mut self,
        target: &r2o_controller::discovery::DiscoveryTarget,
    ) -> bool {
        if self
            .ech_input_names
            .iter()
            .any(|(name, family)| name == &target.host && *family == target.family)
        {
            return false;
        }
        if self.ech_input_names.len() == R2O_DISCOVERY_ECH_INPUT_CAPACITY {
            self.ech_input_names.pop_front();
        }
        self.ech_input_names
            .push_back((target.host.clone(), target.family));
        true
    }

    fn r2o_clear_ech_profile_failures(&mut self, host: &str, family: u8) {
        let failures = self
            .ech_input_clearable_failures
            .iter()
            .filter(|(failed_host, _, failed_family, _)| {
                failed_host == host && *failed_family == family
            })
            .cloned()
            .collect::<Vec<_>>();
        for failure in failures {
            self.r2o_clear_failed_endpoint(&failure);
            self.cooldown_ring
                .remove(&R2oDiscoveryCooldownKey::Endpoint(failure));
        }
    }

    fn take_client_snapshot_provenance(
        &mut self,
        target: &r2o_controller::discovery::DiscoveryTarget,
    ) -> bool {
        self.client_snapshot_targets
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .remove(target)
    }

