    #[cfg(unix)]
    #[test]
    fn own_first_layered_rx_trial_sequence_matches_d2o() {
        use r2o_controller::r2o_volume::{R2oVolumeObservation, R2oVolumeRxEncoding};

        let observations = include_str!("../tests/fixtures/d2o_layered_rx.tsv")
            .lines()
            .filter(|line| !line.starts_with('#') && !line.trim().is_empty())
            .map(|line| {
                let fields = line
                    .split_whitespace()
                    .map(|field| field.parse::<u64>().expect("числовое поле fixture"))
                    .collect::<Vec<_>>();
                assert_eq!(fields.len(), 8);
                R2oVolumeObservation {
                    status: fields[0] as u16,
                    body_complete: fields[1] != 0,
                    body_encoding: match fields[2] {
                        0 => R2oVolumeRxEncoding::Identity,
                        1 => R2oVolumeRxEncoding::Gzip,
                        _ => panic!("неизвестное кодирование fixture"),
                    },
                    body_framing_valid: fields[3] != 0,
                    body_has_length: fields[4] != 0,
                    body_chunked: fields[5] != 0,
                    body_expected: fields[6],
                    body_bytes: fields[7],
                    ..R2oVolumeObservation::default()
                }
            })
            .collect::<Vec<_>>();
        assert_eq!(observations.len(), 3);

        let mut next = 0;
        let mut waits = 0;
        let mut encodings = Vec::new();
        let (last, layered_rx_handled, attempts, evidence) =
            super::r2o_discovery_layered_rx_candidate_trials(
                true,
                r2o_controller::fetch::R2oFetchEncoding::GzipDeflate,
                observations.len(),
                || true,
                || waits += 1,
                |encoding| {
                    encodings.push(encoding);
                    let observation = observations[next];
                    next += 1;
                    (observation, true)
                },
                |(observation, applied)| applied.then_some(*observation),
            );
        assert!(layered_rx_handled);
        assert_eq!(attempts, 3);
        assert_eq!(waits, 2);
        assert_eq!(next, 3);
        assert!(evidence.is_some());
        assert_eq!(last.0, observations[2]);
        let encodings = encodings
            .into_iter()
            .map(|encoding| match encoding {
                r2o_controller::fetch::R2oFetchEncoding::Identity => "identity",
                r2o_controller::fetch::R2oFetchEncoding::Gzip => "gzip",
                r2o_controller::fetch::R2oFetchEncoding::GzipDeflate => {
                    panic!("обычное кодирование в layered RX")
                }
            })
            .collect::<Vec<_>>()
            .join(",");
        let output = format!("encodings={encodings};cut=1;handled=1\n");
        if let Ok(path) = std::env::var("R2O_LAYERED_RX_DIFF_OUTPUT") {
            std::fs::write(path, output).expect("записать C/Rust differential output");
        }
    }

    #[cfg(unix)]
    #[test]
    fn flow_unfit_rechecks_only_enabled_exact_plan_bindings_and_keeps_them() {
        let target = DiscoveryTarget {
            host: "discord.com".to_owned(),
            endpoint: "203.0.113.8:443".to_owned(),
            family: 4,
            shape: SHAPE_MODERN,
        };
        let mut plan_id = [0; 16];
        plan_id[..10].copy_from_slice(b"plan-match");
        let binding = |plan_id: &str, enabled, family| Binding {
            kind: "name".to_owned(),
            target: target.host.clone(),
            plan_id: plan_id.to_owned(),
            level: 3,
            enabled,
            transport: 6,
            family,
            shape: SHAPE_MODERN,
            ..Binding::default()
        };
        let mut catalog = Catalog {
            boxes: vec![BoxRecord {
                id: "box".to_owned(),
                updated: 50,
                bindings: vec![
                    binding("plan-match", true, 4),
                    binding("plan-other", true, 4),
                    binding("plan-match", false, 4),
                    binding("plan-match", true, 6),
                ],
                ..BoxRecord::default()
            }],
            ..Catalog::default()
        };

        assert_eq!(
            r2o_catalog_mark_flow_unfit(&mut catalog, &target, &plan_id, 123),
            (1, 0)
        );
        let bindings = &catalog.boxes[0].bindings;
        assert_eq!(bindings[0].recheck_since, Some(123));
        assert_eq!(bindings[0].recheck_mono.is_some(), true);
        assert!(bindings[0].enabled);
        assert_eq!(bindings[0].plan_id, "plan-match");
        assert_eq!(bindings[1].recheck_since, None);
        assert_eq!(bindings[2].recheck_since, None);
        assert_eq!(bindings[3].recheck_since, None);
        assert_eq!(catalog.boxes[0].updated, 123);

        assert_eq!(
            r2o_catalog_mark_flow_unfit(&mut catalog, &target, &plan_id, 124),
            (0, 1)
        );
        assert_eq!(catalog.boxes[0].bindings[0].recheck_since, Some(123));
    }

    #[cfg(unix)]
    #[test]
    fn flow_unfit_deduplication_uses_the_d2o_eight_entry_ring() {
        let target = DiscoveryTarget {
            host: "discord.com".to_owned(),
            endpoint: "203.0.113.8:443".to_owned(),
            family: 4,
            shape: SHAPE_MODERN,
        };
        let mut done = super::R2oFlowUnfitDone::default();
        assert!(done.remember(&target, [1; 16]));
        assert!(!done.remember(&target, [1; 16]));
        for index in 0..8 {
            let mut other = target.clone();
            other.host = format!("site-{index}.example");
            assert!(done.remember(&other, [index + 2; 16]));
        }
        assert!(!done.contains(&target, &[1; 16]));
    }

    #[cfg(unix)]
    #[test]
    fn confirmed_http_install_returns_before_ack_and_records_exact_late_ack() {
        use super::HttpAcknowledgedBinding;
        use std::os::unix::net::UnixStream;
        use std::time::{Duration, Instant};

        let (socket, mut peer) = UnixStream::pair().unwrap();
        let mut client = ControlClient {
            socket,
            send_maxlen: 1500,
            send_cap: Arc::new(std::sync::atomic::AtomicUsize::new(1500)),
            pending_events: Default::default(),
            pending_applied_events: Default::default(),
            dropped_events: Arc::new(AtomicUsize::new(0)),
            http_search_started: Default::default(),
            http_acknowledged_bindings: Default::default(),
        };
        let trial_id = [0x55; 16];
        let plan_id = [0x11; 16];
        let text = candidate_text("split", Some(&plan_id)).unwrap();
        let records = compile_text(&text).unwrap();
        let command = r2k_core::control::encode_set_name_bound(
            "example.test",
            SHAPE_HTTP,
            4,
            &records,
            trial_id,
        )
        .unwrap();
        println!(
            "D2O_HTTP_BOUND_SET={}",
            command
                .iter()
                .map(|byte| format!("{byte:02x}"))
                .collect::<String>()
        );

        let started = Instant::now();
        client
            .write_http_candidate_install(&command, "example.test", 4, plan_id, trial_id)
            .unwrap();
        assert!(started.elapsed() < Duration::from_millis(100));
        let sent = read_frame(&mut peer).unwrap();
        assert_eq!(sent.kind, COMMAND_SET_NAME_BOUND);
        assert!(matches!(
            client.http_acknowledged_bindings.get(&("example.test".into(), 4)),
            Some(HttpAcknowledgedBinding::Pending {
                trial_id: pending_trial,
                ..
            }) if *pending_trial == trial_id
        ));

        let binding = BindingContext {
            generation: 3,
            kind: 1,
            family: 4,
            shape: SHAPE_HTTP,
            temporary: false,
            epoch: [8; 16],
        };
        client.record_http_bound_binding_acknowledgement(Ack {
            command: COMMAND_SET_NAME_BOUND,
            ok: true,
            reason: 0,
            trial_id: Some(trial_id),
            area_id: None,
            binding_context: Some(binding),
        });
        assert_eq!(
            client
                .http_acknowledged_bindings
                .get(&("example.test".into(), 4)),
            Some(&HttpAcknowledgedBinding::Confirmed { plan_id, binding })
        );
    }

    #[cfg(unix)]
    #[test]
    fn confirmed_http_candidate_is_durable_before_catalog_flush_interval() {
        use super::R2oCatalogPersistence;
        use std::os::unix::net::UnixStream;
        use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

        let work = std::env::temp_dir().join(format!(
            "r2o-http-immediate-save-{}-{}",
            std::process::id(),
            SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ));
        std::fs::create_dir(&work).unwrap();
        let catalog_path = work.join("catalog.json");
        Catalog::default().save_atomic(&catalog_path, 1).unwrap();
        let mut catalog = Catalog::load(&catalog_path).unwrap();
        let target = r2o_controller::discovery::DiscoveryTarget {
            host: "example.com".into(),
            endpoint: "127.0.0.1:80".into(),
            family: 4,
            shape: SHAPE_HTTP,
        };
        let (socket, mut peer) = UnixStream::pair().unwrap();
        let mut client = ControlClient {
            socket,
            send_maxlen: 1500,
            send_cap: Arc::new(std::sync::atomic::AtomicUsize::new(1500)),
            pending_events: Default::default(),
            pending_applied_events: Default::default(),
            dropped_events: Arc::new(AtomicUsize::new(0)),
            http_search_started: Default::default(),
            http_acknowledged_bindings: Default::default(),
        };
        let peer = std::thread::spawn(move || {
            let frame = read_frame(&mut peer).unwrap();
            assert_eq!(frame.kind, COMMAND_SET_NAME_BOUND);
        });
        let started = Instant::now();
        let snapshot = Arc::new(std::sync::Mutex::new(catalog.clone()));
        let mut persistence = R2oCatalogPersistence::new(started, snapshot);

        client
            .install_http_candidate(
                &target,
                "split",
                &mut catalog,
                &catalog_path,
                Some(&mut persistence),
            )
            .unwrap();
        peer.join().unwrap();

        let saved = Catalog::load(&catalog_path).unwrap();
        assert!(
            saved
                .boxes
                .iter()
                .flat_map(|record| &record.plans)
                .any(|plan| { plan.enabled && plan.text.contains("proto tcp http") })
        );
        assert!(!persistence.dirty);
        assert!(
            !persistence
                .persist_due(
                    &mut catalog,
                    &catalog_path,
                    started + Duration::from_secs(59),
                    2,
                )
                .unwrap()
        );
        assert!(r2o_controller::discovery::has_usable_binding(
            &saved, &target
        ));
        if let Ok(path) = std::env::var("R2O_HTTP_DURABLE_DIFF_OUTPUT") {
            std::fs::write(path, "persisted_before_flush=yes\n").unwrap();
        }
        std::fs::remove_dir_all(work).unwrap();
    }

    #[cfg(unix)]
    #[test]
    fn http_owned_plan_rollback_matches_d2o() {
        use std::io::Cursor;
        use std::os::unix::net::UnixStream;
        use std::time::{Instant, SystemTime, UNIX_EPOCH};

        fn expect_delete(peer: &mut UnixStream, host: &str, binding: BindingContext) {
            let frame = read_frame(peer).unwrap();
            let expected_bytes = super::encode_delete_name_bound(host, 6, binding).unwrap();
            let expected = read_frame(&mut Cursor::new(expected_bytes)).unwrap();
            assert_eq!(frame.kind, r2k_core::control::COMMAND_DEL_NAME_BOUND);
            assert_eq!(frame.kind, expected.kind);
            assert_eq!(frame.body, expected.body);
        }

        fn run_case(
            label: &str,
            judged: bool,
            pending_reinstall: bool,
            late_ack_ok: bool,
        ) -> String {
            let work = std::env::temp_dir().join(format!(
                "r2o-http-rollback-{}-{}-{}",
                std::process::id(),
                SystemTime::now()
                    .duration_since(UNIX_EPOCH)
                    .unwrap()
                    .as_nanos(),
                label
            ));
            std::fs::create_dir(&work).unwrap();
            let catalog_path = work.join("catalog.json");
            Catalog::default().save_atomic(&catalog_path, 1).unwrap();
            let mut catalog = Catalog::load(&catalog_path).unwrap();
            let snapshot = Arc::new(std::sync::Mutex::new(catalog.clone()));
            let mut persistence = super::R2oCatalogPersistence::new(Instant::now(), snapshot);
            let target = DiscoveryTarget {
                host: "rutracker.org".into(),
                endpoint: "37.221.67.160:80".into(),
                family: 4,
                shape: SHAPE_HTTP,
            };
            let (socket, mut peer) = UnixStream::pair().unwrap();
            let mut client = ControlClient {
                socket,
                send_maxlen: 1500,
                send_cap: Arc::new(std::sync::atomic::AtomicUsize::new(1500)),
                pending_events: Default::default(),
                pending_applied_events: Default::default(),
                dropped_events: Arc::new(AtomicUsize::new(0)),
                http_search_started: Default::default(),
                http_acknowledged_bindings: Default::default(),
            };
            client
                .install_http_candidate(
                    &target,
                    "split",
                    &mut catalog,
                    &catalog_path,
                    Some(&mut persistence),
                )
                .unwrap();
            assert!(!persistence.dirty);
            assert_eq!(read_frame(&mut peer).unwrap().kind, COMMAND_SET_NAME_BOUND);
            let (plan_id, initial_trial) = match client
                .http_acknowledged_bindings
                .get(&(target.host.clone(), target.family))
                .copied()
                .unwrap()
            {
                super::HttpAcknowledgedBinding::Pending {
                    plan_id, trial_id, ..
                } => (plan_id, trial_id),
                _ => panic!("HTTP SET must wait for its exact ACK"),
            };
            let initial_binding = BindingContext {
                generation: 9,
                kind: 1,
                family: target.family,
                shape: SHAPE_HTTP,
                temporary: false,
                epoch: [1; 16],
            };
            client.record_http_bound_binding_acknowledgement(Ack {
                command: COMMAND_SET_NAME_BOUND,
                ok: true,
                reason: 0,
                trial_id: Some(initial_trial),
                area_id: None,
                binding_context: Some(initial_binding),
            });
            assert!(super::catalog_has_http_search_owner(
                &catalog, &target, plan_id
            ));

            let mut next_trial = None;
            let mut late_binding = None;
            if pending_reinstall {
                let plan_id_text = catalog
                    .boxes
                    .iter()
                    .flat_map(|box_record| &box_record.plans)
                    .find(|plan| plan.enabled && plan.proto == "http")
                    .unwrap()
                    .id
                    .clone();
                let mut exact_plan_id = [0; 16];
                for (index, pair) in plan_id_text.as_bytes().chunks_exact(2).enumerate() {
                    exact_plan_id[index] =
                        u8::from_str_radix(std::str::from_utf8(pair).unwrap(), 16).unwrap();
                }
                assert_eq!(exact_plan_id, plan_id);
                let text = candidate_text("split", Some(&exact_plan_id)).unwrap();
                let records = compile_text(&text).unwrap();
                let trial_id = [0x66; 16];
                let command = super::encode_set_name_bound(
                    &target.host,
                    SHAPE_HTTP,
                    target.family,
                    &records,
                    trial_id,
                )
                .unwrap();
                client
                    .write_http_candidate_install(
                        &command,
                        &target.host,
                        target.family,
                        exact_plan_id,
                        trial_id,
                    )
                    .unwrap();
                assert_eq!(read_frame(&mut peer).unwrap().kind, COMMAND_SET_NAME_BOUND);
                next_trial = Some(trial_id);
                late_binding = Some(BindingContext {
                    generation: 10,
                    kind: 1,
                    family: target.family,
                    shape: SHAPE_HTTP,
                    temporary: false,
                    epoch: [2; 16],
                });
            }

            let owner = client
                .acknowledged_http_search_owner(&catalog, &target)
                .unwrap();
            let action = super::r2o_http_failed_revoke_action(judged, Some(owner));
            let mut deletes = 0;
            let mut changes = 1;
            if let Some(owner) = action {
                assert!(
                    client
                        .revoke_http_search_owner(
                            &target,
                            owner,
                            &mut catalog,
                            &catalog_path,
                            Some(&mut persistence),
                        )
                        .unwrap()
                );
                assert!(!persistence.dirty);
                changes += 1;
                match owner {
                    super::HttpSearchOwnedBinding::Confirmed { binding, .. } => {
                        expect_delete(&mut peer, &target.host, binding);
                        deletes += 1;
                    }
                    super::HttpSearchOwnedBinding::Pending { previous, .. } => {
                        if let Some((_, binding)) = previous {
                            expect_delete(&mut peer, &target.host, binding);
                            deletes += 1;
                        }
                    }
                }
            }

            if let (Some(trial_id), Some(binding)) = (next_trial, late_binding) {
                client.record_http_bound_binding_acknowledgement(Ack {
                    command: COMMAND_SET_NAME_BOUND,
                    ok: late_ack_ok,
                    reason: if late_ack_ok { 0 } else { 1 },
                    trial_id: Some(trial_id),
                    area_id: None,
                    binding_context: late_ack_ok.then_some(binding),
                });
                expect_delete(
                    &mut peer,
                    &target.host,
                    if late_ack_ok {
                        binding
                    } else {
                        initial_binding
                    },
                );
                deletes += 1;
            }

            let saved = Catalog::load(&catalog_path).unwrap();
            let plan_present = super::catalog_has_http_search_owner(&saved, &target, plan_id);
            let unknown_delete = 0;
            std::fs::remove_dir_all(work).unwrap();
            format!(
                "{label}:plan_present={},del_plan={deletes},changed={changes},unknown_delete={unknown_delete}\n",
                u8::from(plan_present)
            )
        }

        let output = format!(
            "{}{}{}{}",
            run_case("judged", true, false, true),
            run_case("unjudged", false, false, true),
            run_case("late_ack", true, true, true),
            run_case("late_nack", true, true, false),
        );
        assert_eq!(
            output,
            "judged:plan_present=0,del_plan=1,changed=2,unknown_delete=0\n\
             unjudged:plan_present=1,del_plan=0,changed=1,unknown_delete=0\n\
             late_ack:plan_present=0,del_plan=2,changed=2,unknown_delete=0\n\
             late_nack:plan_present=0,del_plan=2,changed=2,unknown_delete=0\n"
                .replace("             ", "")
        );
        if let Ok(path) = std::env::var("R2O_HTTP_ROLLBACK_DIFF_OUTPUT") {
            std::fs::write(path, output).unwrap();
        }
    }

    #[cfg(unix)]
    #[test]
    fn network_whitelist_probe_decisions_matches_d2o() {
        let tx_only = Catalog::parse(
            br#"{"schema":1,"network_whitelist":{"name":"learned-white.example","searched":false,"tx_only":true}}"#,
        )
        .unwrap();
        let tx_only_round_trip =
            Catalog::parse(tx_only.to_json_at(1_791_593_321).unwrap().as_bytes()).unwrap();
        assert!(
            tx_only_round_trip
                .network_whitelist
                .as_ref()
                .unwrap()
                .tx_only
        );
        let known_rx = Catalog::parse(
            br#"{"schema":1,"network_whitelist":{"name":"learned-white.example","searched":true}}"#,
        )
        .unwrap();
        assert!(
            !known_rx
                .to_json_at(1_791_593_321)
                .unwrap()
                .contains("\"tx_only\"")
        );
        let persisted: Catalog =
            Catalog::parse(include_bytes!("../tests/fixtures/d2o_net_whitelist.json")).unwrap();
        let persisted_network = persisted.network_whitelist.as_ref().unwrap();
        if let Ok(path) = std::env::var("R2O_NET_WHITELIST_CATALOG_DIFF_OUTPUT") {
            std::fs::write(
                path,
                format!(
                    "{} {} {} {}\n",
                    persisted_network.name,
                    u8::from(persisted_network.searched),
                    u8::from(persisted_network.tx_only),
                    persisted_network.confirmed_at.unwrap_or_default()
                ),
            )
            .unwrap();
        }
        let unresolved = Catalog::default();
        let cases = [
            ("unresolved", &unresolved, true),
            ("known_rx", &known_rx, true),
            ("tx_only_rx", &tx_only, true),
            ("tx_only_tx", &tx_only, false),
        ];
        let mut output = String::new();
        for (name, catalog, rx_cut) in cases {
            let network_probe = super::r2o_discovery_network_whitelist_probe(Some(catalog), rx_cut);
            output.push_str(&format!("{name} {}\n", u8::from(network_probe)));
        }
        if let Ok(path) = std::env::var("R2O_NET_WHITELIST_DIFF_OUTPUT") {
            std::fs::write(path, output).unwrap();
        }
    }

