    fn network_whitelist_updates_keep_the_cut_direction_and_clear_exhausted_names() {
        let mut catalog = Catalog::default();
        let network = catalog
            .network_whitelist
            .get_or_insert_with(r2o_controller::catalog::NetworkWhitelist::default);
        super::r2o_update_network_whitelist(
            network,
            &super::R2oNetworkWhitelistUpdate {
                name: Some("tx-only.example".into()),
                rx_cut: false,
            },
            1_791_593_321,
        );
        let network = catalog.network_whitelist.as_ref().unwrap();
        assert!(!network.searched);
        assert!(network.tx_only);
        assert!(super::r2o_discovery_network_whitelist_probe(
            Some(&catalog),
            true
        ));
        assert!(!super::r2o_discovery_network_whitelist_probe(
            Some(&catalog),
            false
        ));

        let network = catalog.network_whitelist.as_mut().unwrap();
        super::r2o_update_network_whitelist(
            network,
            &super::R2oNetworkWhitelistUpdate {
                name: Some("rx-verified.example".into()),
                rx_cut: true,
            },
            1_791_593_322,
        );
        let network = catalog.network_whitelist.as_ref().unwrap();
        assert_eq!(network.name, "rx-verified.example");
        assert!(network.searched);
        assert!(!network.tx_only);
        assert!(!super::r2o_discovery_network_whitelist_probe(
            Some(&catalog),
            true
        ));

        let network = catalog.network_whitelist.as_mut().unwrap();
        super::r2o_update_network_whitelist(
            network,
            &super::R2oNetworkWhitelistUpdate {
                name: Some("tx-only.example".into()),
                rx_cut: false,
            },
            1_791_593_323,
        );
        let network = catalog.network_whitelist.as_mut().unwrap();
        super::r2o_update_network_whitelist(
            network,
            &super::R2oNetworkWhitelistUpdate {
                name: None,
                rx_cut: true,
            },
            1_791_593_324,
        );
        let network = catalog.network_whitelist.as_ref().unwrap();
        assert!(network.name.is_empty());
        assert!(network.searched);
        assert!(network.tx_only);
        assert!(!super::r2o_discovery_network_whitelist_probe(
            Some(&catalog),
            true
        ));
    }

    #[test]
    fn candidate_confirmation_uses_datapath_mark_even_when_direct_probe_has_a_bypass_mark() {
        #[cfg(target_os = "linux")]
        for direct_mark in [Some(45), None] {
            use std::os::fd::AsRawFd;
            let probe = super::BoundTcpProbe::open(4, r2o_candidate_confirmation_mark(direct_mark))
                .unwrap();
            let mut actual_mark: u32 = u32::MAX;
            let mut length = std::mem::size_of_val(&actual_mark) as libc::socklen_t;
            assert_eq!(
                unsafe {
                    libc::getsockopt(
                        probe.socket.as_raw_fd(),
                        libc::SOL_SOCKET,
                        libc::SO_MARK,
                        (&mut actual_mark as *mut u32).cast(),
                        &mut length,
                    )
                },
                0
            );
            assert_eq!(actual_mark, 0, "candidate socket bypasses NFQUEUE");
        }
    }

