    #[test]
    fn d2o_scheduler_dead_address_matches_donor() {
        let now = std::time::Instant::now();
        let target = DiscoveryTarget {
            host: "dead.example".into(),
            endpoint: "192.0.2.10:443".into(),
            family: 4,
            shape: SHAPE_MODERN,
        };
        let mut cache = super::R2oDeadAddressCache::default();
        let first = cache.step(&target, now).unwrap();
        let second = cache.step(&target, now + first).unwrap();
        let third = cache.step(&target, now + first + second).unwrap();
        assert_eq!(
            [first.as_secs(), second.as_secs(), third.as_secs()],
            [600, 1800, 3600]
        );
        let expiry = now + first + second + third;
        assert!(cache.is_blocked(&target, expiry - std::time::Duration::from_nanos(1)));
        assert!(!cache.is_blocked(&target, expiry));
        let recheck_retains_expired_record = cache.requires_recheck(&target, expiry);
        assert!(recheck_retains_expired_record);

        let same_address_other_port = DiscoveryTarget {
            endpoint: "192.0.2.10:8443".into(),
            ..target.clone()
        };
        let other_address = DiscoveryTarget {
            endpoint: "192.0.2.11:443".into(),
            ..target.clone()
        };
        let other_name = DiscoveryTarget {
            host: "other.example".into(),
            ..target.clone()
        };
        let other_transport = DiscoveryTarget {
            shape: SHAPE_QUIC,
            ..target.clone()
        };
        let other_family = DiscoveryTarget {
            family: 6,
            endpoint: "[2001:db8::10]:443".into(),
            ..target.clone()
        };
        let other_address_allowed = !cache.is_blocked(&other_address, expiry);
        let other_name_allowed = !cache.is_blocked(&other_name, expiry);
        let other_transport_allowed = !cache.is_blocked(&other_transport, expiry);
        let other_family_allowed = !cache.is_blocked(&other_family, expiry);
        let same_address_other_port_blocked =
            cache.requires_recheck(&same_address_other_port, expiry);
        assert!(other_address_allowed);
        assert!(other_name_allowed);
        assert!(other_transport_allowed);
        assert!(other_family_allowed);
        assert!(same_address_other_port_blocked);
        cache.clear(&target);
        let clear_allows_address = !cache.requires_recheck(&target, expiry);
        assert!(clear_allows_address);

        let mut ring = super::R2oDeadAddressCache::default();
        for index in 0..super::R2O_DISCOVERY_COOLDOWN_CAPACITY {
            ring.step(
                &DiscoveryTarget {
                    host: format!("ring-{index:03}.example"),
                    endpoint: format!("192.0.2.{}:443", index + 1),
                    family: 4,
                    shape: SHAPE_MODERN,
                },
                now + std::time::Duration::from_secs(index as u64),
            );
        }
        let replacement = DiscoveryTarget {
            host: "ring-new.example".into(),
            endpoint: "198.51.100.1:443".into(),
            family: 4,
            shape: SHAPE_MODERN,
        };
        ring.step(&replacement, now + std::time::Duration::from_secs(1000));
        let ring_evicts_earliest = !ring.is_blocked(
            &DiscoveryTarget {
                host: "ring-000.example".into(),
                endpoint: "192.0.2.1:443".into(),
                family: 4,
                shape: SHAPE_MODERN,
            },
            now,
        );
        let ring_keeps_next = ring.is_blocked(
            &DiscoveryTarget {
                host: "ring-001.example".into(),
                endpoint: "192.0.2.2:443".into(),
                family: 4,
                shape: SHAPE_MODERN,
            },
            now,
        );
        let ring_keeps_new = ring.is_blocked(&replacement, now);
        assert!(ring_evicts_earliest);
        assert!(ring_keeps_next);
        assert!(ring_keeps_new);

        let output = format!(
            "dead_retry_seconds {} {} {}\ndead_recheck_retains_expired_record {}\ndead_other_ip_allowed {}\ndead_other_name_allowed {}\ndead_other_transport_allowed {}\ndead_other_family_allowed {}\ndead_same_ip_other_port_blocked {}\ndead_clear_allows_address {}\ndead_ring_evicts_earliest {}\ndead_ring_keeps_next {}\ndead_ring_keeps_new {}\n",
            first.as_secs(),
            second.as_secs(),
            third.as_secs(),
            u8::from(recheck_retains_expired_record),
            u8::from(other_address_allowed),
            u8::from(other_name_allowed),
            u8::from(other_transport_allowed),
            u8::from(other_family_allowed),
            u8::from(same_address_other_port_blocked),
            u8::from(clear_allows_address),
            u8::from(ring_evicts_earliest),
            u8::from(ring_keeps_next),
            u8::from(ring_keeps_new),
        );
        let recheck_target = DiscoveryTarget {
            host: "recheck.example".into(),
            endpoint: "192.0.2.40:443".into(),
            family: 4,
            shape: SHAPE_MODERN,
        };
        let recheck_cache = std::sync::Mutex::new(super::R2oDeadAddressCache::default());
        let recheck_start = std::time::Instant::now();
        let initial_retry = recheck_cache
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .step(&recheck_target, recheck_start)
            .unwrap();
        let silent_calls = std::cell::Cell::new(0);
        let mut silent_probes = 0;
        let silent = super::r2o_saved_address_recheck(
            &recheck_cache,
            &recheck_target,
            recheck_start + initial_retry,
            &mut silent_probes,
            || {
                silent_calls.set(silent_calls.get() + 1);
                Ok(false)
            },
        );
        assert_eq!(silent, super::R2oSavedAddressRecheck::Silent);
        assert_eq!(silent_calls.get(), 3);
        assert_eq!(silent_probes, 3);
        let silent_retry = recheck_cache
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .step(&recheck_target, recheck_start + initial_retry)
            .unwrap();
        assert_eq!(silent_retry, std::time::Duration::from_secs(1800));

        let accepted_target = DiscoveryTarget {
            host: "accepted-recheck.example".into(),
            endpoint: "192.0.2.41:443".into(),
            ..recheck_target.clone()
        };
        let accepted_cache = std::sync::Mutex::new(super::R2oDeadAddressCache::default());
        let accepted_retry = accepted_cache
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .step(&accepted_target, recheck_start)
            .unwrap();
        let accepted_calls = std::cell::Cell::new(0);
        let mut accepted_probes = 0;
        let accepted = super::r2o_saved_address_recheck(
            &accepted_cache,
            &accepted_target,
            recheck_start + accepted_retry,
            &mut accepted_probes,
            || {
                accepted_calls.set(accepted_calls.get() + 1);
                Ok(true)
            },
        );
        assert_eq!(accepted, super::R2oSavedAddressRecheck::Accepted);
        assert_eq!(accepted_calls.get(), 1);
        assert_eq!(accepted_probes, 1);
        let accepted_trigger_delta =
            usize::from(accepted == super::R2oSavedAddressRecheck::Accepted);
        let mut next_ack_calls = 0;
        let mut next_ack_probes = 0;
        let next_recheck = super::r2o_saved_address_recheck(
            &accepted_cache,
            &accepted_target,
            recheck_start + accepted_retry + std::time::Duration::from_secs(660),
            &mut next_ack_probes,
            || {
                next_ack_calls += 1;
                Ok(false)
            },
        );
        assert_eq!(next_recheck, super::R2oSavedAddressRecheck::NotRequired);
        assert_eq!(next_ack_calls, 0);
        assert_eq!(next_ack_probes, 0);
        let accepted_next_trigger_delta = usize::from(matches!(
            next_recheck,
            super::R2oSavedAddressRecheck::NotRequired
                | super::R2oSavedAddressRecheck::Accepted
                | super::R2oSavedAddressRecheck::Unmeasured
        ));
        let adapter_target = DiscoveryTarget {
            host: "adapter-recheck.example".into(),
            endpoint: "192.0.2.42:443".into(),
            ..recheck_target.clone()
        };
        let adapter_cache = std::sync::Mutex::new(super::R2oDeadAddressCache::default());
        let adapter_retry = adapter_cache
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .step(&adapter_target, recheck_start)
            .unwrap();
        let mut adapter_silent_probes = 0;
        assert_eq!(
            super::r2o_saved_address_recheck(
                &adapter_cache,
                &adapter_target,
                recheck_start + adapter_retry,
                &mut adapter_silent_probes,
                || Ok(false),
            ),
            super::R2oSavedAddressRecheck::Silent
        );
        assert_eq!(adapter_silent_probes, 3);
        let mut adapter_accepted_calls = 0;
        let mut adapter_accepted_probes = 0;
        assert_eq!(
            super::r2o_saved_address_recheck(
                &adapter_cache,
                &adapter_target,
                recheck_start + adapter_retry,
                &mut adapter_accepted_probes,
                || {
                    adapter_accepted_calls += 1;
                    Ok(adapter_accepted_calls == 2)
                },
            ),
            super::R2oSavedAddressRecheck::Accepted
        );
        assert_eq!(adapter_accepted_probes, 2);
        let error_target = DiscoveryTarget {
            host: "error-recheck.example".into(),
            endpoint: "192.0.2.43:443".into(),
            ..recheck_target.clone()
        };
        let error_cache = std::sync::Mutex::new(super::R2oDeadAddressCache::default());
        let error_retry = error_cache
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .step(&error_target, recheck_start)
            .unwrap();
        let mut failed_probes = 0;
        assert_eq!(
            super::r2o_saved_address_recheck(
                &error_cache,
                &error_target,
                recheck_start + error_retry,
                &mut failed_probes,
                || Err(super::R2oSavedAddressAckError::Failed),
            ),
            super::R2oSavedAddressRecheck::Unmeasured
        );
        assert_eq!(failed_probes, 1);
        let mut unsupported_probes = 0;
        assert_eq!(
            super::r2o_saved_address_recheck(
                &error_cache,
                &error_target,
                recheck_start + error_retry,
                &mut unsupported_probes,
                || Err(super::R2oSavedAddressAckError::Unsupported),
            ),
            super::R2oSavedAddressRecheck::Unmeasured
        );
        assert_eq!(unsupported_probes, 0);
        let mut stopped_probes = 0;
        assert_eq!(
            super::r2o_saved_address_recheck(
                &error_cache,
                &error_target,
                recheck_start + error_retry,
                &mut stopped_probes,
                || Err(super::R2oSavedAddressAckError::NotAttempted),
            ),
            super::R2oSavedAddressRecheck::Unmeasured
        );
        assert_eq!(stopped_probes, 0);
        let ack_adapter_output = format!(
            "saved_ack_silent probes={} result=Silent\nsaved_ack_accepted probes={} result=Accepted\nsaved_ack_failed probes={} result=Unmeasured\nsaved_ack_unsupported probes={} result=Unmeasured\nsaved_ack_stopped probes={} result=Unmeasured\n",
            adapter_silent_probes,
            adapter_accepted_probes,
            failed_probes,
            unsupported_probes,
            stopped_probes,
        );
        let recheck_output = format!(
            "saved_recheck_silent probes={} trigger_delta=0 retry_30m={}\nsaved_recheck_accepted probes={} trigger_delta={}\nsaved_recheck_cleared next_ack_delta={} next_trigger_delta={}\n",
            silent_probes,
            u8::from(silent_retry == std::time::Duration::from_secs(1800)),
            accepted_probes,
            accepted_trigger_delta,
            next_ack_calls,
            accepted_next_trigger_delta,
        );
        if let Ok(path) = std::env::var("R2O_SCHED_DEAD_ADDRESS_DIFF_OUTPUT") {
            std::fs::write(
                path,
                format!("{output}{recheck_output}{ack_adapter_output}"),
            )
            .unwrap();
        }
    }

    #[test]
    fn перепроверка_мёртвого_адреса_повторяет_ack_до_успеха_и_сохраняет_неизмеренное() {
        let target = DiscoveryTarget {
            host: "ack-dead.example".into(),
            endpoint: "192.0.2.20:443".into(),
            family: 4,
            shape: SHAPE_MODERN,
        };
        let now = std::time::Instant::now();
        let cache = std::sync::Mutex::new(super::R2oDeadAddressCache::default());
        let first_delay = cache
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .step(&target, now)
            .unwrap();
        let before_expiry_calls = std::cell::Cell::new(0);
        let mut before_expiry_probes = 0;
        assert_eq!(
            super::r2o_saved_address_recheck(
                &cache,
                &target,
                now + first_delay - std::time::Duration::from_nanos(1),
                &mut before_expiry_probes,
                || {
                    before_expiry_calls.set(before_expiry_calls.get() + 1);
                    Ok(false)
                },
            ),
            super::R2oSavedAddressRecheck::CoolingDown
        );
        assert_eq!(before_expiry_calls.get(), 0);
        assert_eq!(before_expiry_probes, 0);

        let silent_calls = std::cell::Cell::new(0);
        let mut silent_probes = 0;
        assert_eq!(
            super::r2o_saved_address_recheck(
                &cache,
                &target,
                now + first_delay,
                &mut silent_probes,
                || {
                    silent_calls.set(silent_calls.get() + 1);
                    Ok(false)
                }
            ),
            super::R2oSavedAddressRecheck::Silent
        );
        assert_eq!(silent_calls.get(), 3);
        assert_eq!(silent_probes, 3);
        assert!(
            cache
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .requires_recheck(&target, now + first_delay)
        );

        let accepted_calls = std::cell::Cell::new(0);
        let mut accepted_probes = 0;
        assert_eq!(
            super::r2o_saved_address_recheck(
                &cache,
                &target,
                now + first_delay,
                &mut accepted_probes,
                || {
                    accepted_calls.set(accepted_calls.get() + 1);
                    Ok(accepted_calls.get() == 2)
                }
            ),
            super::R2oSavedAddressRecheck::Accepted
        );
        assert_eq!(accepted_calls.get(), 2);
        assert_eq!(accepted_probes, 2);
        assert!(
            !cache
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .requires_recheck(&target, now + first_delay)
        );

        let unmeasured = DiscoveryTarget {
            host: "ack-unmeasured.example".into(),
            endpoint: "192.0.2.21:443".into(),
            ..target
        };
        let delay = cache
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .step(&unmeasured, now)
            .unwrap();
        let error_calls = std::cell::Cell::new(0);
        let mut error_probes = 0;
        assert_eq!(
            super::r2o_saved_address_recheck(
                &cache,
                &unmeasured,
                now + delay,
                &mut error_probes,
                || {
                    error_calls.set(error_calls.get() + 1);
                    Err(super::R2oSavedAddressAckError::Failed)
                }
            ),
            super::R2oSavedAddressRecheck::Unmeasured
        );
        assert_eq!(error_calls.get(), 1);
        assert_eq!(error_probes, 1);
        assert!(
            cache
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .requires_recheck(&unmeasured, now + delay)
        );
        for error in [
            super::R2oSavedAddressAckError::Unsupported,
            super::R2oSavedAddressAckError::NotAttempted,
        ] {
            let mut uncounted_probes = 0;
            assert_eq!(
                super::r2o_saved_address_recheck(
                    &cache,
                    &unmeasured,
                    now + delay,
                    &mut uncounted_probes,
                    || Err(error),
                ),
                super::R2oSavedAddressRecheck::Unmeasured
            );
            assert_eq!(uncounted_probes, 0);
        }
    }

    #[test]
    fn scheduler_address_failure_scopes_queue_and_post_ack_retry() {
        let mut worker = r2o_test_discovery_worker_without_threads();
        let target = DiscoveryTarget {
            host: "dead-outcome.example".into(),
            endpoint: "192.0.2.30:443".into(),
            family: 4,
            shape: SHAPE_MODERN,
        };
        let failure_key = super::r2o_discovery_failure_key(&target);
        for streak in 1..=3 {
            if streak > 1 {
                let mut cache = worker
                    .dead_addresses
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner);
                let key = super::r2o_dead_address_key(&target).unwrap();
                cache
                    .slots
                    .iter_mut()
                    .flatten()
                    .find(|entry| entry.key == key)
                    .unwrap()
                    .expires_at = std::time::Instant::now() - std::time::Duration::from_nanos(1);
            }
            worker.seen.insert(target.clone());
            worker.seen_order.push_back(target.clone());
            worker.r2o_complete_outcome(DiscoveryOutcome {
                target: target.clone(),
                plan_text: None,
                detail: "адрес не принимает данные".into(),
                queue_expired: false,
                address_failure: true,
                address_recheck_acknowledged: false,
                address_recheck_probes: 0,
                direct_clear: false,
                volume_recovery: false,
                volume_fingerprint: None,
                volume_box_id: None,
                retry_after: None,
            });
            let cache = worker
                .dead_addresses
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            let key = super::r2o_dead_address_key(&target).unwrap();
            let entry = cache
                .slots
                .iter()
                .flatten()
                .find(|entry| entry.key == key)
                .unwrap();
            assert_eq!(entry.streak, streak);
            assert_eq!(
                worker.failed_retry_after.get(&failure_key),
                Some(&super::R2O_DISCOVERY_TASK_REST)
            );
            assert!(
                worker
                    .cooldown_ring
                    .endpoint_state(&failure_key, std::time::Instant::now())
                    .is_none()
            );
        }

        assert!(!worker.queue(target.clone()));
        let other_address = DiscoveryTarget {
            endpoint: "192.0.2.31:443".into(),
            ..target.clone()
        };
        assert!(worker.queue(other_address.clone()));
        worker
            .jobs
            .0
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .entries
            .clear();
        let task_key = super::r2o_discovery_task_key(&other_address);
        worker.active.remove(&task_key);
        worker
            .active_cancels
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .remove(&task_key);
        worker.seen.remove(&other_address);
        worker.seen_order.retain(|seen| seen != &other_address);

        {
            let mut cache = worker
                .dead_addresses
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            let key = super::r2o_dead_address_key(&target).unwrap();
            cache
                .slots
                .iter_mut()
                .flatten()
                .find(|entry| entry.key == key)
                .unwrap()
                .expires_at = std::time::Instant::now() - std::time::Duration::from_nanos(1);
        }
        assert!(!worker.queue(target.clone()));
        worker.failed_at.insert(
            failure_key.clone(),
            std::time::Instant::now() - super::R2O_DISCOVERY_TASK_REST,
        );
        assert!(
            !worker
                .dead_addresses
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .is_blocked(&target, std::time::Instant::now())
        );
        assert!(!worker.seen.contains(&target));
        assert!(
            !worker
                .completed
                .contains(&super::r2o_discovery_task_key(&target))
        );
        assert!(
            !worker
                .active
                .contains_key(&super::r2o_discovery_task_key(&target))
        );
        assert!(
            worker
                .r2o_reusable_task_slot(&super::r2o_discovery_task_key(&target))
                .is_some()
        );
        assert!(worker.queue(target.clone()));
        worker
            .jobs
            .0
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .entries
            .clear();
        worker.seen.remove(&target);
        worker.seen_order.retain(|seen| seen != &target);

        let mut accepted_probes = 0;
        let accepted = super::r2o_saved_address_recheck(
            &worker.dead_addresses,
            &target,
            std::time::Instant::now(),
            &mut accepted_probes,
            || Ok(true),
        );
        assert_eq!(accepted, super::R2oSavedAddressRecheck::Accepted);
        worker
            .searches
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .update(&target, "распознаём поведение", 0, 3, "", "");
        worker.seen.insert(target.clone());
        worker.seen_order.push_back(target.clone());
        let post_ack = worker.r2o_complete_outcome(DiscoveryOutcome {
            target: target.clone(),
            plan_text: None,
            detail: "ACK принят, последующий классификатор дал ADDRESS".into(),
            queue_expired: false,
            address_failure: true,
            address_recheck_acknowledged: true,
            address_recheck_probes: accepted_probes,
            direct_clear: false,
            volume_recovery: false,
            volume_fingerprint: None,
            volume_box_id: None,
            retry_after: None,
        });
        assert_eq!(
            post_ack.retry_after,
            Some(super::R2O_DISCOVERY_INCOMPLETE_RETRY)
        );
        assert_eq!(
            worker.failed_retry_after.get(&failure_key),
            Some(&super::R2O_DISCOVERY_INCOMPLETE_RETRY)
        );
        let searches = worker
            .searches
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        assert_eq!(
            searches.entries[&super::r2o_discovery_task_key(&target)].probes,
            4
        );
        assert_eq!(searches.probes_used, 4);
        drop(searches);
        assert!(
            !worker
                .dead_addresses
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .requires_recheck(&target, std::time::Instant::now())
        );
    }

    #[test]
    fn кэш_чистого_tcp_рукопожатия_сверяет_имя_семейство_срок_и_ёмкость() {
        let now = std::time::Instant::now();
        let mut cache = super::R2oCleanHandshakeCache::default();
        cache.note("clean.example", 4, now);

        assert!(cache.r2o_recent("clean.example", 4, now));
        assert!(cache.suppresses_unplanned_tcp_suspicion("clean.example", 4, false, now));
        assert!(!cache.suppresses_unplanned_tcp_suspicion("clean.example", 4, true, now));
        assert!(!cache.r2o_recent("other.example", 4, now));
        assert!(!cache.r2o_recent("clean.example", 6, now));
        assert!(!cache.suppresses_unplanned_tcp_suspicion("clean.example", 6, false, now));
        assert!(cache.r2o_recent("clean.example", 4, now + std::time::Duration::from_secs(60),));
        assert!(!cache.r2o_recent("clean.example", 4, now + std::time::Duration::from_secs(61),));

        for index in 0..16 {
            cache.note(&format!("other-{index}.example"), 4, now);
        }
        assert!(!cache.r2o_recent("clean.example", 4, now));
    }

    #[test]
    fn кэш_tcp_приветствий_связывает_имя_цель_и_подозрение_с_точным_потоком() {
        let now = std::time::Instant::now();
        let mut key = [0; KEY_LEN];
        key[0] = 4;
        key[1..5].copy_from_slice(&[192, 0, 2, 10]);
        key[17..21].copy_from_slice(&[198, 51, 100, 80]);
        key[33..35].copy_from_slice(&45_000_u16.to_be_bytes());
        key[35..37].copy_from_slice(&443_u16.to_be_bytes());
        key[37] = 6;
        let hello = HelloEvent {
            key,
            host: Some(b"CLEAN.Example.COM.".to_vec()),
            shape: Some(SHAPE_MODERN),
            r2o_wire_len: Some(812),
            quic_snapshot: None,
            tcp_has_timestamp: None,
        };
        let mut cache = super::R2oTcpHelloCache::default();
        cache.note(hello, now);

        assert_eq!(
            cache.clean_handshake_name(&key, now).as_deref(),
            Some("clean.example.com")
        );
        let target = cache.target_for_tcp_flow(&key, now).unwrap();
        assert_eq!(target.host, "clean.example.com");
        assert_eq!(target.family, 4);

        let mut foreign = key;
        foreign[4] = 11;
        assert!(cache.clean_handshake_name(&foreign, now).is_none());
        assert!(cache.target_for_tcp_flow(&foreign, now).is_none());
        assert!(
            cache
                .clean_handshake_name(&key, now + std::time::Duration::from_secs(61))
                .is_none()
        );
        assert!(
            cache
                .target_for_tcp_flow(&key, now + std::time::Duration::from_secs(61))
                .is_none()
        );
    }

    #[cfg(unix)]
    #[test]
    fn кэш_недавних_tcp_имён_даёт_свидетелей_с_адресом_и_сроком_жизни() {
        let now = std::time::Instant::now();
        let target = r2o_controller::discovery::DiscoveryTarget {
            host: "cloudflare-ech.com".into(),
            endpoint: "198.51.100.80:443".into(),
            family: 4,
            shape: r2k_core::control::SHAPE_ECH_TCP,
        };
        let hello = |name: &[u8], server: [u8; 4], port: u16| {
            let mut key = [0; KEY_LEN];
            key[0] = 4;
            key[1..5].copy_from_slice(&[192, 0, 2, 10]);
            key[17..21].copy_from_slice(&server);
            key[33..35].copy_from_slice(&port.to_be_bytes());
            key[35..37].copy_from_slice(&443_u16.to_be_bytes());
            key[37] = 6;
            HelloEvent {
                key,
                host: Some(name.to_vec()),
                shape: Some(SHAPE_MODERN),
                r2o_wire_len: None,
                quic_snapshot: None,
                tcp_has_timestamp: None,
            }
        };
        let mut cache = super::R2oRecentTcpNameCache::default();
        cache.note(&hello(b"SAME.Example.", [198, 51, 100, 80], 41_001), now);
        cache.note(
            &hello(b"stale.example", [203, 0, 113, 5], 41_002),
            now - std::time::Duration::from_secs(601),
        );
        cache.note(&hello(b"cross.example", [203, 0, 113, 5], 41_003), now);

        assert_eq!(
            cache.ech_witness_names(&target, now),
            [
                ("same.example".into(), true),
                ("cross.example".into(), false),
            ]
        );
        assert_eq!(
            cache.ech_witness_names(&target, now + std::time::Duration::from_secs(601)),
            []
        );
    }

    #[cfg(unix)]
    #[test]
    fn ech_rr_сохраняет_положительный_и_отрицательный_ответ_до_срока() {
        let now = std::time::Instant::now();
        let mut cache = super::R2oEchWitnessResolutionCache::default();
        let config = r2o_controller::ech::R2oEchConfig {
            public_name: "public.example".into(),
            origin_name: "witness.example".into(),
            config_list: vec![1, 2, 3],
        };

        cache.store("positive.example", Some(config.clone()), now);
        cache.store("negative.example", None, now);

        assert_eq!(
            cache.lookup(
                "positive.example",
                now + std::time::Duration::from_secs(6 * 60 * 60)
            ),
            Some(Some(config))
        );
        assert!(
            cache
                .lookup(
                    "positive.example",
                    now + std::time::Duration::from_secs(6 * 60 * 60)
                        + std::time::Duration::from_nanos(1)
                )
                .is_none()
        );
        assert_eq!(
            cache.lookup(
                "negative.example",
                now + std::time::Duration::from_secs(11 * 60)
            ),
            Some(None)
        );
        assert!(
            cache
                .lookup(
                    "negative.example",
                    now + std::time::Duration::from_secs(30 * 60)
                        + std::time::Duration::from_nanos(1)
                )
                .is_none()
        );
    }

    #[cfg(unix)]
    #[test]
    fn ech_rr_свежие_положительные_свидетели_получают_приоритет() {
        let now = std::time::Instant::now();
        let mut cache = super::R2oEchWitnessResolutionCache::default();
        let config = |public_name: &str| r2o_controller::ech::R2oEchConfig {
            public_name: public_name.into(),
            origin_name: "witness.example".into(),
            config_list: vec![1],
        };
        cache.store("known-one.example", Some(config("public.example")), now);
        cache.store("known-two.example", Some(config("public.example")), now);
        cache.store("wrong.example", Some(config("other.example")), now);
        cache.store("negative.example", None, now);
        cache.store(
            "expired.example",
            Some(config("public.example")),
            now - super::R2O_DISCOVERY_ECH_RR_POSITIVE_TTL - std::time::Duration::from_nanos(1),
        );

        let cached = cache.cached_witness_names("public.example", now);
        let mut discovered = vec!["known-one.example".into(), "public.example".into()];
        discovered.extend((0..40).map(|index| format!("catalog-{index}.example")));
        let candidates =
            super::r2o_merge_ech_witness_candidates("public.example", &cached, &discovered);

        assert_eq!(
            &candidates[..3],
            [
                "known-one.example",
                "known-two.example",
                "catalog-0.example"
            ]
        );
        assert_eq!(
            candidates.len(),
            r2o_controller::discovery::R2O_ECH_WITNESS_LIMIT
        );
        assert!(!candidates.iter().any(|name| {
            matches!(
                name.as_str(),
                "public.example" | "wrong.example" | "negative.example" | "expired.example"
            )
        }));
    }

