    #[cfg(unix)]
    fn r2o_http_response(code: u8, path: &[u8]) -> HttpResponseEvent {
        let mut key = [0; KEY_LEN];
        key[0] = 4;
        key[1..5].copy_from_slice(&[192, 0, 2, 10]);
        key[17..21].copy_from_slice(&[198, 51, 100, 80]);
        key[33..35].copy_from_slice(&45_000_u16.to_be_bytes());
        key[35..37].copy_from_slice(&80_u16.to_be_bytes());
        key[37] = 6;
        HttpResponseEvent {
            key,
            code,
            host: b"Example.com".to_vec(),
            execution_id: 0,
            plan_id: [0; 16],
            trial_id: [0; 16],
            request_ms: 0,
            path: path.to_vec(),
            binding: BindingContext {
                generation: 0,
                kind: 0,
                family: 0,
                shape: 0,
                temporary: false,
                epoch: [0; 16],
            },
            status: 200,
            body_bytes: 1024,
            request_no: 1,
        }
    }

    #[cfg(unix)]
    #[test]
    fn r2o_http_search_сохраняет_путь_повторяемого_запроса() {
        let portal = r2o_http_response(3, b"/account/view");
        let (target, path, expected) = super::r2o_http_search_from_response(&portal).unwrap();
        assert_eq!(target.host, "example.com");
        assert_eq!(path, b"/");
        assert!(matches!(
            expected,
            r2o_controller::http_search::Answer::Injected
        ));

        let cut = r2o_http_response(4, b"/watch/42");
        let (_, path, expected) = super::r2o_http_search_from_response(&cut).unwrap();
        assert_eq!(path, b"/watch/42");
        assert!(matches!(expected, r2o_controller::http_search::Answer::Cut));
        let invalid_portal_path = r2o_http_response(3, b"//host/admin");
        let (_, path, expected) =
            super::r2o_http_search_from_response(&invalid_portal_path).unwrap();
        assert_eq!(path, b"/");
        assert_eq!(expected, r2o_controller::http_search::Answer::Injected);
        assert!(
            super::r2o_http_search_from_response(&r2o_http_response(4, b"//host/admin")).is_none()
        );
    }

    #[cfg(unix)]
    #[test]
    fn r2o_http_cut_context_survives_a_later_portal() {
        let target = r2o_controller::discovery::DiscoveryTarget {
            host: "example.com".into(),
            endpoint: "192.0.2.10:80".into(),
            family: 4,
            shape: SHAPE_HTTP,
        };
        let mut records = super::HttpSearchRecordCache::default();
        records.record_cut(&target, b"/watch/first");
        let (path, expected) = records
            .context(
                &target,
                b"/account/view",
                r2o_controller::http_search::Answer::Injected,
            )
            .unwrap();
        assert_eq!(path, b"/watch/first");
        assert_eq!(expected, r2o_controller::http_search::Answer::Cut);
        records.record_cut(&target, b"/watch/later");
        let (path, expected) = records
            .context(&target, b"/", r2o_controller::http_search::Answer::Injected)
            .unwrap();
        assert_eq!(path, b"/watch/first");
        assert_eq!(expected, r2o_controller::http_search::Answer::Cut);
        if let Ok(output) = std::env::var("R2O_HTTP_CUT_CONTEXT_DIFF_OUTPUT") {
            std::fs::write(
                output,
                format!(
                    "request_path={}\nbaseline={expected:?}\n",
                    String::from_utf8_lossy(&path)
                ),
            )
            .unwrap();
        }
    }

    #[cfg(unix)]
    #[test]
    fn семейный_план_требует_https_и_applied_точного_потока_и_trial() {
        let target = DiscoveryTarget {
            host: "media.example.com".into(),
            endpoint: "198.51.100.20:443".into(),
            family: 4,
            shape: SHAPE_MODERN,
        };
        let plan_id = [0x55; 16];
        let mut key = [0; KEY_LEN];
        key[0] = 4;
        key[1..5].copy_from_slice(&[192, 0, 2, 10]);
        key[17..21].copy_from_slice(&[198, 51, 100, 20]);
        key[33..35].copy_from_slice(&41_000_u16.to_be_bytes());
        key[35..37].copy_from_slice(&443_u16.to_be_bytes());
        key[37] = 6;
        let event = r2k_core::control::AppliedEvent {
            key,
            plan_id,
            trial_id: [0; 16],
            execution_id: 7,
            binding: r2k_core::control::BindingContext {
                generation: 1,
                kind: 1,
                family: 4,
                shape: SHAPE_MODERN,
                temporary: false,
                epoch: [1; 16],
            },
        };
        assert!(r2o_family_applied_flow_matches(
            &event, &target, 41_000, plan_id, [0; 16]
        ));
        assert!(!r2o_family_applied_flow_matches(
            &event, &target, 41_001, plan_id, [0; 16]
        ));
        assert!(!r2o_family_applied_flow_matches(
            &event, &target, 41_000, [0x56; 16], [0; 16]
        ));

        let mut legacy = event.clone();
        legacy.execution_id = 0;
        legacy.binding = r2k_core::control::BindingContext {
            generation: 0,
            kind: 0,
            family: 0,
            shape: 0,
            temporary: false,
            epoch: [0; 16],
        };
        assert!(r2o_family_applied_flow_matches(
            &legacy, &target, 41_000, plan_id, [0; 16]
        ));

        let trial_id = [0x44; 16];
        let mut temporary = event.clone();
        temporary.trial_id = trial_id;
        temporary.binding.temporary = true;
        assert!(r2o_family_applied_flow_matches(
            &temporary, &target, 41_000, plan_id, trial_id
        ));
        assert!(!r2o_family_applied_flow_matches(
            &temporary, &target, 41_000, plan_id, [0x45; 16]
        ));
        let mut legacy_temporary = temporary.clone();
        legacy_temporary.execution_id = 0;
        legacy_temporary.binding = legacy.binding;
        assert!(r2o_family_applied_flow_matches(
            &legacy_temporary,
            &target,
            41_000,
            plan_id,
            trial_id
        ));

        let fetch = FetchResult {
            address: "198.51.100.20:443".parse().unwrap(),
            local_port: 41_000,
            tls: Some("1.3"),
            peer_name_ok: None,
            ech_accepted: None,
            status: 200,
            http_outcome: r2o_controller::fetch::R2oFetchHttpOutcome::Positive,
            cloudflare_challenge: false,
            body_bytes: 64,
            body_expected: Some(64),
            body_has_length: true,
            location: String::new(),
            chunked: false,
            gzip: false,
            complete: true,
            application_verified: true,
            handshake_verified: false,
            elapsed: std::time::Duration::from_millis(30),
            reason: None,
            r2o_volume_observation: Default::default(),
            r2o_resources: Vec::new(),
        };
        assert_eq!(
            r2o_family_recovery_decision(&Ok(fetch.clone()), false),
            R2oFamilyRecoveryDecision::Reclassify
        );
        assert_eq!(
            r2o_family_recovery_decision(&Ok(fetch.clone()), true),
            R2oFamilyRecoveryDecision::Verified
        );
        let mut replay_proof = fetch.clone();
        replay_proof.tls = None;
        replay_proof.status = 0;
        replay_proof.complete = false;
        replay_proof.application_verified = false;
        replay_proof.handshake_verified = true;
        assert_eq!(
            r2o_family_recovery_decision(&Ok(replay_proof.clone()), false),
            R2oFamilyRecoveryDecision::Reclassify,
            "ServerHello without the matching APPLIED event cannot verify a candidate"
        );
        assert_eq!(
            r2o_family_recovery_decision(&Ok(replay_proof), true),
            R2oFamilyRecoveryDecision::Verified,
            "the captured ClientHello plus ServerHello and exact APPLIED is sufficient"
        );
        let mut ech_result = fetch.clone();
        ech_result.ech_accepted = Some(true);
        ech_result.peer_name_ok = Some(true);
        assert_eq!(
            r2o_family_recovery_decision(&Ok(ech_result.clone()), true),
            R2oFamilyRecoveryDecision::Verified
        );
        ech_result.peer_name_ok = Some(false);
        assert_eq!(
            r2o_family_recovery_decision(&Ok(ech_result.clone()), true),
            R2oFamilyRecoveryDecision::Reclassify
        );
        ech_result.peer_name_ok = Some(true);
        ech_result.ech_accepted = Some(false);
        assert_eq!(
            r2o_family_recovery_decision(&Ok(ech_result), true),
            R2oFamilyRecoveryDecision::Reclassify
        );
        let mut unresolved_redirect = fetch.clone();
        unresolved_redirect.status = 302;
        unresolved_redirect.location = "/landing".into();
        unresolved_redirect.application_verified = false;
        assert_eq!(
            r2o_family_recovery_decision(&Ok(unresolved_redirect), true),
            R2oFamilyRecoveryDecision::Reclassify
        );
        let mut blocked_page = fetch.clone();
        blocked_page.status = 403;
        blocked_page.http_outcome = r2o_controller::fetch::R2oFetchHttpOutcome::Blocked;
        blocked_page.application_verified = false;
        assert_eq!(
            r2o_family_recovery_decision(&Ok(blocked_page), true),
            R2oFamilyRecoveryDecision::Reclassify
        );
        let mut legal_denial = fetch.clone();
        legal_denial.status = 451;
        legal_denial.http_outcome = r2o_controller::fetch::R2oFetchHttpOutcome::LegalDenial;
        legal_denial.application_verified = false;
        assert_eq!(
            r2o_family_recovery_decision(&Ok(legal_denial), true),
            R2oFamilyRecoveryDecision::Reclassify
        );
        let mut incomplete = fetch;
        incomplete.complete = false;
        assert_eq!(
            r2o_family_recovery_decision(&Ok(incomplete), true),
            R2oFamilyRecoveryDecision::Reclassify
        );
        assert_eq!(
            r2o_family_recovery_decision(&Ok(r2o_test_fetch_result()), false),
            R2oFamilyRecoveryDecision::Reclassify
        );
    }

    #[cfg(unix)]
    #[test]
    fn d2o_legacy_applied_frame_matches_donor_flow_proof() {
        let line = include_str!("../../r2k-core/tests/fixtures/d2o_control_events.hex")
            .lines()
            .find(|line| line.starts_with("APPLIED "))
            .unwrap();
        let mut fields = line.split_whitespace();
        let _kind = fields.next().unwrap();
        let wire_hex = fields.next().unwrap();
        let wire = (0..wire_hex.len())
            .step_by(2)
            .map(|offset| u8::from_str_radix(&wire_hex[offset..offset + 2], 16).unwrap())
            .collect::<Vec<_>>();
        let frame = read_frame(&mut std::io::Cursor::new(wire)).unwrap();
        let event = r2k_core::control::decode_applied(&frame).unwrap();
        let target = DiscoveryTarget {
            host: "legacy.example".into(),
            endpoint: "198.51.100.2:443".into(),
            family: 4,
            shape: SHAPE_MODERN,
        };
        let matches =
            r2o_family_applied_flow_matches(&event, &target, 40_123, [0x11; 16], [0x22; 16]);
        assert!(matches);
        if let Ok(path) = std::env::var("R2O_CONTROL_PROOF_DIFF_OUTPUT") {
            std::fs::write(path, format!("MATCH:{}\n", u8::from(matches))).unwrap();
        }
    }

