    #[cfg(unix)]
    #[test]
    fn discovery_bridge_rejects_socket_only_split_results() {
        use std::fmt::Write as _;

        assert!(super::r2o_discovery_split_needs_raw(super::Verdict::Prefix));
        assert!(super::r2o_discovery_split_needs_raw(
            super::Verdict::WholePacket
        ));
        assert!(!super::r2o_discovery_split_needs_raw(
            super::Verdict::Opaque
        ));
        assert!(super::r2o_discovery_split_raw_executed(
            super::Verdict::Prefix,
            1
        ));
        assert!(!super::r2o_discovery_split_raw_executed(
            super::Verdict::Prefix,
            0
        ));
        assert!(!super::r2o_discovery_split_raw_executed(
            super::Verdict::WholePacket,
            0
        ));
        assert!(!super::r2o_discovery_split_raw_executed(
            super::Verdict::Opaque,
            1
        ));

        let (socket_result, socket_pos, socket_only) =
            super::r2o_discovery_split_gate(super::Verdict::Prefix, Some(5), 0);
        let (raw_result, raw_pos, raw_socket_only) =
            super::r2o_discovery_split_gate(super::Verdict::Prefix, Some(5), 1);
        let socket_owned =
            super::r2o_discovery_bridge_search_owned(socket_only, false, false, 0, false);
        let raw_owned =
            super::r2o_discovery_bridge_search_owned(raw_socket_only, false, true, 0, false);
        assert_eq!(socket_result, super::Verdict::Flaky);
        assert_eq!(socket_pos, None);
        assert_eq!(raw_result, super::Verdict::Prefix);
        assert_eq!(raw_pos, Some(5));
        assert!(socket_owned && raw_owned);

        if let Ok(path) = std::env::var("R2O_DISCOVERY_SPLIT_BRIDGE_DIFF_OUTPUT") {
            let mut output = String::new();
            writeln!(
                output,
                "socket-only={} split={} owns={}",
                socket_result.as_str(),
                socket_pos.unwrap_or(0),
                u8::from(socket_owned)
            )
            .unwrap();
            writeln!(
                output,
                "raw-split={} split={} owns={}",
                raw_result.as_str(),
                raw_pos.unwrap_or(0),
                u8::from(raw_owned)
            )
            .unwrap();
            std::fs::write(path, output).unwrap();
        }
    }

    #[cfg(unix)]
    #[test]
    fn measured_split_plans_match_donor() {
        use std::fmt::Write as _;

        let cases = [
            (1024, 1, 60_000, 0),
            (1024, 1, 60_000, 1492),
            (1024, 1, 60_000, 1280),
            (1024, 1, 60_000, 100),
            (1024, 1, 60_000, 72),
            (1024, 0, 60_000, 1492),
            (1024, 1024, 60_000, 1492),
        ];
        let mut output = String::new();
        for verdict in [super::Verdict::Prefix, super::Verdict::WholePacket] {
            let verdict_name = match verdict {
                super::Verdict::Prefix => "prefix",
                super::Verdict::WholePacket => "whole_packet",
                _ => unreachable!(),
            };
            for (trigger_len, split, gap_us, send_cap) in cases {
                let plan: Option<String> = super::r2o_discovery_measured_split_plan(
                    verdict,
                    true,
                    Some(split),
                    trigger_len,
                    gap_us,
                    send_cap,
                );
                writeln!(
                    output,
                    "{verdict_name} {trigger_len} {split} {gap_us} {send_cap} {}",
                    if plan.is_some() { "plan" } else { "skip" }
                )
                .unwrap();
                if let Some(plan) = plan {
                    output.push_str(&plan);
                    output.push('\n');
                } else {
                    output.push('\n');
                }
            }
        }
        assert!(
            super::r2o_discovery_measured_split_plan(
                super::Verdict::Prefix,
                false,
                Some(1),
                1024,
                60_000,
                0,
            )
            .is_none()
        );
        assert!(
            super::r2o_discovery_measured_split_plan(
                super::Verdict::Opaque,
                true,
                Some(1),
                1024,
                60_000,
                0,
            )
            .is_none()
        );
        if let Ok(path) = std::env::var("R2O_MEASURED_SPLIT_DIFF_OUTPUT") {
            std::fs::write(path, output).unwrap();
        }
    }

    #[cfg(unix)]
    #[test]
    fn measured_fallback_keeps_transport_failure_and_rejects_missing_evidence() {
        let evidence = super::R2oCandidateTrialEvidence {
            transport_established: true,
            local_limit: false,
            dropped_before: 7,
            dropped_after: 7,
            layered_rx_handled: false,
            layered_rx_proven: false,
        };
        let failed = Err("TLS-рукопожатие не завершилось".into());
        assert!(super::r2o_discovery_measured_fallback_allowed(
            true, &failed, true, evidence
        ));
        assert!(!super::r2o_discovery_measured_fallback_allowed(
            true, &failed, false, evidence
        ));
        assert!(!super::r2o_discovery_measured_fallback_allowed(
            false, &failed, true, evidence
        ));
        for changed in [
            super::R2oCandidateTrialEvidence {
                transport_established: false,
                ..evidence
            },
            super::R2oCandidateTrialEvidence {
                local_limit: true,
                ..evidence
            },
            super::R2oCandidateTrialEvidence {
                dropped_after: 8,
                ..evidence
            },
        ] {
            assert!(!super::r2o_discovery_measured_fallback_allowed(
                true, &failed, true, changed
            ));
        }
        let mut challenge = r2o_test_fetch_result();
        challenge.cloudflare_challenge = true;
        assert!(!super::r2o_discovery_measured_fallback_allowed(
            true,
            &Ok(challenge),
            true,
            evidence
        ));
        let mut denial = r2o_test_fetch_result();
        denial.http_outcome = r2o_controller::fetch::R2oFetchHttpOutcome::LegalDenial;
        assert!(!super::r2o_discovery_measured_fallback_allowed(
            true,
            &Ok(denial),
            true,
            evidence
        ));
    }

