    #[test]
    fn volume_raw_measurements_do_not_spend_candidate_budget() {
        use r2o_controller::fetch::{R2oFetchVolumeTxResult, R2oFetchVolumeTxVerdict};
        use std::sync::Mutex;
        use std::sync::atomic::AtomicBool;

        for raw in [0, 5, 67, 100] {
            let target = DiscoveryTarget {
                host: "media.example".into(),
                endpoint: "192.0.2.31:443".into(),
                family: 4,
                shape: SHAPE_MODERN,
            };
            let now = std::time::Instant::now();
            let mut cache = super::R2oDiscoveryVolumeSearchCache::default();
            cache.insert(
                target.clone(),
                super::R2oDiscoveryVolumeSearch {
                    key: super::R2oDiscoveryVolumeSearchKey {
                        wire_len: super::r2o_discovery_volume_wire_len(&target, None),
                        send_cap: 1492,
                        probe_path: "/".into(),
                        alternate_path: None,
                        network_probe: false,
                        white_name: "hcaptcha.com".into(),
                    },
                    measured_at: now,
                    tx: Ok(R2oFetchVolumeTxResult {
                        address: target.endpoint.parse().unwrap(),
                        verdict: R2oFetchVolumeTxVerdict::Cut,
                        at_kb: 16,
                        elapsed: std::time::Duration::from_secs(1),
                        reason: "обрыв на 16 КБ".into(),
                    }),
                    rx: Default::default(),
                    next_candidate: 0,
                    tried_plans: Vec::new(),
                },
            );
            let mut outcome = super::DiscoveryOutcome {
                target: target.clone(),
                plan_text: None,
                detail: String::new(),
                queue_expired: false,
                address_failure: false,
                address_recheck_acknowledged: false,
                address_recheck_probes: 0,
                direct_clear: true,
                volume_recovery: false,
                volume_fingerprint: None,
                volume_box_id: None,
                retry_after: None,
            };
            let cancel = Arc::new(AtomicBool::new(false));
            let controller_cancel = Arc::clone(&cancel);
            let (commands, requests) = std::sync::mpsc::sync_channel(8);
            let controller = std::thread::spawn(move || {
                let mut installed = 0;
                while let Ok(command) = requests.recv() {
                    match command {
                        super::HttpSearchCommand::InstallProbe { reply, .. } => {
                            installed += 1;
                            controller_cancel.store(true, Ordering::Relaxed);
                            reply.send(Err("местный отказ стенда".into())).unwrap();
                        }
                        _ => panic!("unexpected controller command"),
                    }
                }
                installed
            });
            assert!(super::r2o_discovery_volume_recovery(
                &mut outcome,
                &target,
                None,
                true,
                Some(0),
                &commands,
                &Mutex::new(VecDeque::new()),
                None,
                &r2o_controller::catalog::Fingerprint::default(),
                &[],
                0,
                "hcaptcha.com",
                &AtomicUsize::new(1492),
                &Mutex::new(Default::default()),
                &Mutex::new(cache),
                &Mutex::new(Default::default()),
                &cancel,
                now,
                raw,
            ));
            drop(commands);
            assert_eq!(
                controller.join().unwrap(),
                1,
                "raw={raw} consumed candidate budget"
            );
        }
    }

    #[cfg(unix)]
    #[test]
    fn volume_поиск_сохраняет_замер_и_курсоры_только_для_того_же_входа() {
        use r2o_controller::fetch::{R2oFetchVolumeTxResult, R2oFetchVolumeTxVerdict};

        let target = DiscoveryTarget {
            host: "media.example".into(),
            endpoint: "192.0.2.31:443".into(),
            family: 4,
            shape: SHAPE_MODERN,
        };
        let now = std::time::Instant::now();
        let key = super::R2oDiscoveryVolumeSearchKey {
            wire_len: Some(812),
            send_cap: 1492,
            probe_path: "/asset.css".into(),
            alternate_path: Some("/image.webp".into()),
            network_probe: false,
            white_name: "hcaptcha.com".into(),
        };
        let search = super::R2oDiscoveryVolumeSearch {
            key: key.clone(),
            measured_at: now,
            tx: Ok(R2oFetchVolumeTxResult {
                address: "192.0.2.31:443".parse().unwrap(),
                verdict: R2oFetchVolumeTxVerdict::Cut,
                at_kb: 16,
                elapsed: std::time::Duration::from_secs(1),
                reason: "обрыв на 16 КБ".into(),
            }),
            rx: Default::default(),
            next_candidate: 7,
            tried_plans: Vec::new(),
        };
        let mut cache = super::R2oDiscoveryVolumeSearchCache::default();
        cache.insert(target.clone(), search);

        let cached = cache.get(&target, &key, now).unwrap();
        assert_eq!(cached.next_candidate, 7);
        assert_eq!(cached.key.wire_len, Some(812));
        assert!(
            cache
                .get(
                    &target,
                    &super::R2oDiscoveryVolumeSearchKey {
                        probe_path: "/".into(),
                        ..key.clone()
                    },
                    now,
                )
                .is_none()
        );
        assert!(cache.entries.is_empty());

        cache.insert(
            target.clone(),
            super::R2oDiscoveryVolumeSearch {
                key: key.clone(),
                measured_at: now,
                tx: Ok(R2oFetchVolumeTxResult {
                    address: "192.0.2.31:443".parse().unwrap(),
                    verdict: R2oFetchVolumeTxVerdict::Passed,
                    at_kb: 64,
                    elapsed: std::time::Duration::ZERO,
                    reason: "лестница пройдена".into(),
                }),
                rx: Default::default(),
                next_candidate: 0,
                tried_plans: Vec::new(),
            },
        );
        assert!(
            cache
                .get(
                    &target,
                    &key,
                    now + super::R2O_DISCOVERY_TASK_LIFETIME + std::time::Duration::from_secs(1),
                )
                .is_none()
        );
        assert!(cache.entries.is_empty());
    }

    #[cfg(unix)]
    #[test]
    fn cached_rx_cut_disables_client_alpn_handshake_verification() {
        use r2o_controller::fetch::{
            R2oFetchVolumeRxResult, R2oFetchVolumeTxResult, R2oFetchVolumeTxVerdict,
        };
        use r2o_controller::r2o_volume::{R2oVolumeRxDomain, R2oVolumeRxEvidence};
        use std::sync::Mutex;

        let target = DiscoveryTarget {
            host: "mqtt.example".into(),
            endpoint: "192.0.2.31:443".into(),
            family: 4,
            shape: SHAPE_MODERN,
        };
        let now = std::time::Instant::now();
        let key = super::R2oDiscoveryVolumeSearchKey {
            wire_len: super::r2o_discovery_volume_wire_len(&target, None),
            send_cap: 1492,
            probe_path: "/".into(),
            alternate_path: None,
            network_probe: false,
            white_name: "hcaptcha.com".into(),
        };
        let mut cache = super::R2oDiscoveryVolumeSearchCache::default();
        cache.insert(
            target.clone(),
            super::R2oDiscoveryVolumeSearch {
                key,
                measured_at: now,
                tx: Ok(R2oFetchVolumeTxResult {
                    address: target.endpoint.parse().unwrap(),
                    verdict: R2oFetchVolumeTxVerdict::Passed,
                    at_kb: 64,
                    elapsed: std::time::Duration::ZERO,
                    reason: "TX ladder passed".into(),
                }),
                rx: R2oFetchVolumeRxResult {
                    evidence: Some(R2oVolumeRxEvidence {
                        domain: R2oVolumeRxDomain::TlsWire,
                        cut_kb: 16,
                        expected_kb: 32,
                        cut_packets: 18,
                        compressed_complete: true,
                        reason: "cached RX cut".into(),
                    }),
                    ..Default::default()
                },
                next_candidate: 0,
                tried_plans: Vec::new(),
            },
        );
        let searches = Mutex::new(cache);
        let cached_rx_cut = super::r2o_discovery_cached_volume_cut(
            &searches,
            &target,
            None,
            None,
            &AtomicUsize::new(1492),
            &Mutex::new(Default::default()),
            "hcaptcha.com",
        );

        assert!(cached_rx_cut);
        assert!(!super::r2o_discovery_client_alpn_verification_allowed(
            &target,
            "/",
            true,
            cached_rx_cut,
        ));
    }

