    #[cfg(unix)]
    #[test]
    fn applied_collection_returns_on_exact_event_without_waiting_for_timeout() {
        let trial_id = [2; 16];
        let event = r2k_core::control::AppliedEvent {
            key: [0; KEY_LEN],
            plan_id: [3; 16],
            trial_id,
            execution_id: 1,
            binding: r2k_core::control::BindingContext {
                generation: 0,
                kind: 0,
                family: 0,
                shape: 0,
                temporary: false,
                epoch: [0; 16],
            },
        };
        let wrong_plan = r2k_core::control::AppliedEvent {
            plan_id: [4; 16],
            ..event.clone()
        };
        let (commands, receiver) = std::sync::mpsc::sync_channel(1);
        let controller = std::thread::spawn(move || {
            let mut pending = VecDeque::from([wrong_plan, event]);
            while let Ok(command) = receiver.recv() {
                let HttpSearchCommand::CollectApplied {
                    trial_id: requested,
                    reply,
                    ..
                } = command
                else {
                    panic!("ожидалась команда сбора APPLIED");
                };
                assert_eq!(requested, trial_id);
                reply
                    .send(Ok(pending.pop_front().into_iter().collect()))
                    .unwrap();
            }
        });

        let started = std::time::Instant::now();
        let events = super::r2o_collect_controller_applied_events_until(
            &commands,
            trial_id,
            std::time::Duration::from_secs(5),
            |event| event.trial_id == trial_id && event.plan_id == [3; 16],
        )
        .unwrap();

        assert_eq!(events.len(), 2);
        assert_eq!(events[0].plan_id, [4; 16]);
        assert_eq!(events[1].plan_id, [3; 16]);
        assert!(
            started.elapsed() < std::time::Duration::from_millis(200),
            "exact APPLIED was available but collection took {} ms",
            started.elapsed().as_millis()
        );
        drop(commands);
        controller.join().unwrap();
    }

    #[cfg(unix)]
    #[test]
    fn http_applied_collection_requires_each_unique_execution_within_donor_window() {
        use r2k_core::control::{AppliedEvent, BindingContext, KEY_LEN, SHAPE_HTTP};
        use r2o_controller::http_search::{ProbeIdentity, confirmed_applied};
        use std::collections::HashSet;
        use std::net::{IpAddr, Ipv4Addr};

        let trial_id = [2; 16];
        let plan_id = [3; 16];
        let identity = ProbeIdentity {
            plan_id,
            trial_id,
            family: 4,
            client: IpAddr::V4(Ipv4Addr::new(127, 0, 0, 1)),
            server: IpAddr::V4(Ipv4Addr::new(1, 2, 3, 4)),
            local_port: 41_000,
        };
        let event = |execution_id| {
            let mut key = [0; KEY_LEN];
            key[0] = 4;
            key[1..5].copy_from_slice(&[127, 0, 0, 1]);
            key[17..21].copy_from_slice(&[1, 2, 3, 4]);
            key[33..35].copy_from_slice(&41_000_u16.to_be_bytes());
            key[35..37].copy_from_slice(&80_u16.to_be_bytes());
            key[37] = 6;
            AppliedEvent {
                key,
                plan_id,
                trial_id,
                execution_id,
                binding: BindingContext {
                    generation: 1,
                    kind: 1,
                    family: 4,
                    shape: SHAPE_HTTP,
                    temporary: true,
                    epoch: [7; 16],
                },
            }
        };
        let exact = |event: &AppliedEvent| {
            event.trial_id == trial_id && event.plan_id == plan_id && event.execution_id != 0
        };
        let exact_count = |events: &[AppliedEvent]| {
            events
                .iter()
                .filter(|event| exact(event))
                .map(|event| event.execution_id)
                .collect::<HashSet<_>>()
                .len()
        };

        let first = event(1);
        let duplicate = first.clone();
        let second = event(2);
        let (commands, receiver) = std::sync::mpsc::sync_channel(1);
        let controller = std::thread::spawn(move || {
            let started = std::time::Instant::now();
            let mut first_batch = true;
            let mut second_sent = false;
            while let Ok(command) = receiver.recv() {
                let HttpSearchCommand::CollectApplied {
                    trial_id: requested,
                    reply,
                    ..
                } = command
                else {
                    panic!("ожидалась команда сбора APPLIED");
                };
                assert_eq!(requested, trial_id);
                let batch = if first_batch {
                    first_batch = false;
                    vec![first.clone(), duplicate.clone()]
                } else if !second_sent && started.elapsed() >= std::time::Duration::from_millis(80)
                {
                    second_sent = true;
                    vec![second.clone()]
                } else {
                    Vec::new()
                };
                reply.send(Ok(batch)).unwrap();
            }
        });

        let inside = super::r2o_collect_controller_applied_events_until_satisfied(
            &commands,
            trial_id,
            std::time::Duration::from_millis(500),
            |events| confirmed_applied(events, &identity, 2).is_some(),
        )
        .unwrap();
        assert_eq!(exact_count(&inside), 2);
        assert!(confirmed_applied(&inside, &identity, 2).is_some());
        drop(commands);
        controller.join().unwrap();

        let first = event(1);
        let second = event(2);
        let (commands, receiver) = std::sync::mpsc::sync_channel(1);
        let controller = std::thread::spawn(move || {
            let started = std::time::Instant::now();
            let mut first_sent = false;
            let mut late_sent = false;
            while let Ok(command) = receiver.recv() {
                let HttpSearchCommand::CollectApplied {
                    trial_id: requested,
                    reply,
                    ..
                } = command
                else {
                    panic!("ожидалась команда сбора APPLIED");
                };
                assert_eq!(requested, trial_id);
                let batch = if !first_sent {
                    first_sent = true;
                    vec![first.clone()]
                } else if !late_sent && started.elapsed() >= std::time::Duration::from_millis(600) {
                    late_sent = true;
                    vec![second.clone()]
                } else {
                    Vec::new()
                };
                reply.send(Ok(batch)).unwrap();
            }
        });

        let outside = super::r2o_collect_controller_applied_events_until_satisfied(
            &commands,
            trial_id,
            std::time::Duration::from_millis(500),
            |events| confirmed_applied(events, &identity, 2).is_some(),
        )
        .unwrap();
        assert_eq!(exact_count(&outside), 1);
        assert!(confirmed_applied(&outside, &identity, 2).is_none());
        if let Ok(path) = std::env::var("R2O_HTTP_APPLIED_DIFF_OUTPUT") {
            std::fs::write(path, "inside=2\noutside=1\n").unwrap();
        }
        drop(commands);
        controller.join().unwrap();
    }

    #[cfg(unix)]
    struct HttpBaselineFixture {
        responses: std::io::Cursor<Vec<u8>>,
        requests: Vec<u8>,
    }

    #[cfg(unix)]
    impl std::io::Read for HttpBaselineFixture {
        fn read(&mut self, bytes: &mut [u8]) -> std::io::Result<usize> {
            std::io::Read::read(&mut self.responses, bytes)
        }
    }

    #[cfg(unix)]
    impl std::io::Write for HttpBaselineFixture {
        fn write(&mut self, bytes: &[u8]) -> std::io::Result<usize> {
            self.requests.extend_from_slice(bytes);
            Ok(bytes.len())
        }

        fn flush(&mut self) -> std::io::Result<()> {
            Ok(())
        }
    }

    #[cfg(unix)]
    fn http_baseline_fixture() -> HttpBaselineFixture {
        HttpBaselineFixture {
            responses: std::io::Cursor::new(
                b"HTTP/1.1 200 OK\r\nContent-Length: 0\r\n\r\nHTTP/1.1 200 OK\r\nContent-Length: 0\r\n\r\n"
                    .to_vec(),
            ),
            requests: Vec::new(),
        }
    }

    #[cfg(unix)]
    fn http_request_paths(requests: &[u8]) -> Vec<String> {
        std::str::from_utf8(requests)
            .unwrap()
            .lines()
            .filter(|line| line.starts_with("GET "))
            .map(|line| line.split_whitespace().nth(1).unwrap().to_owned())
            .collect()
    }

    #[cfg(unix)]
